import { formatAgentTypeLabel } from '../../../src/shared/agent-type-label'
import {
  formatNativeChatEmptyStateCopy,
  type NativeChatEmptyStateCopy
} from '../../../src/shared/native-chat-empty-state'
import { isRootAgentJournalItem } from '../../../src/shared/agent-session-journal-producer'
import { stripNoiseMessages } from '../../../src/shared/native-chat-noise'
import { isWordlessProviderFrameMessage } from '../../../src/shared/native-chat-provider-frame-summary'
import { foldToolMessages } from '../../../src/shared/native-chat-tool-fold'
import { foldSubagentItems } from '../../../src/shared/native-chat-subagent-items'
import { prepareNativeChatMessages } from '../../../src/shared/native-chat-message-preparation'
import {
  isImageRefBlock,
  type AgentType,
  type NativeChatMessage
} from '../../../src/shared/native-chat-types'
import { isImageSourceUserTurn } from './mobile-native-chat-image-transcript-markers'
import type { MobileNativeChatStatus } from './use-mobile-native-chat-session'

/** The centered empty-state copy for a chat with no messages, mirroring the
 *  desktop `NativeChatEmptyState` (shared copy + agent label) so the two surfaces
 *  stay in lockstep. Returns null when the list should stay bare (idle, or the
 *  loading spinner owns the view). */
export function mobileNativeChatEmptyState(
  status: MobileNativeChatStatus,
  agent: string | null,
  error?: string
): NativeChatEmptyStateCopy | null {
  const agentLabel = agent ? formatAgentTypeLabel(agent) : 'the agent'
  switch (status) {
    // A live agent with no transcript yet — an unwritten transcript file, or a
    // loaded-but-empty one — is "start a chat"; invite the first message instead
    // of implying the agent is still starting up.
    case 'waiting-session':
    case 'awaiting-transcript':
    case 'ready':
      return formatNativeChatEmptyStateCopy('empty', agentLabel)
    case 'error': {
      const copy = formatNativeChatEmptyStateCopy('error', agentLabel)
      return error ? { ...copy, subtitle: error } : copy
    }
    default:
      return null
  }
}

/** An optimistic user echo: the text and/or the local preview URIs of any images
 *  ridden along on the send, shown until the transcript catches up. */
export type MobileNativeChatPendingItem = {
  id: string
  text: string
  images?: string[]
  /** Transcript tail when the send was issued. The echo renders directly after
   *  that row, so a send whose row never arrives stays where it was sent instead
   *  of trailing every turn that lands afterwards. */
  baselineTailMessageId?: string | null
}

export function foldMobileNativeChatMessages(
  messages: readonly NativeChatMessage[],
  agent: AgentType
): NativeChatMessage[] {
  // The conversation only: a subagent's rows are that subagent's, and mobile shows
  // each spawn as its roster row (one line per child) rather than the child's own rows.
  // Prepared as desktop prepares them, so a skill turn and an image marker turn draw as the
  // user's message. An unrecognised event with no words of its own is stored, not drawn;
  // mobile draws no task list, so a plan update goes too, before folding, so it never splits
  // a tool run.
  return stripNoiseMessages(
    foldToolMessages(
      foldSubagentItems(
        prepareNativeChatMessages(
          messages.filter(
            (message) => isRootAgentJournalItem(message) && !isWordlessProviderFrameMessage(message)
          ),
          agent
        )
      )
    )
  )
}

/** Assemble the folded transcript, streaming text, and optimistic user echoes. */
export function buildMobileNativeChatTransientData({
  messages,
  folded,
  streaming,
  pending,
  imagePreviewsByMessageId
}: {
  /** Raw transcript rows, used to project folded-away send boundaries. */
  messages: NativeChatMessage[]
  folded: NativeChatMessage[]
  /** Streaming bubble text, already gated by `deriveMobileNativeChatStreaming`. */
  streaming: string | null
  pending: MobileNativeChatPendingItem[]
  imagePreviewsByMessageId?: Record<string, string[]>
}): { folded: NativeChatMessage[]; streaming: string | null; data: NativeChatMessage[] } {
  const renderedFolded = folded.map((message) => {
    const previews = imagePreviewsByMessageId?.[message.id]
    if (message.role !== 'user' || !previews?.length) {
      return message
    }
    let previewIndex = 0
    const blocks = message.blocks.map((block) => {
      if (!isImageRefBlock(block)) {
        return block
      }
      const url = previews[previewIndex]
      previewIndex += 1
      return url ? { ...block, url } : block
    })
    while (previewIndex < previews.length) {
      blocks.push({ type: 'image-ref', url: previews[previewIndex] })
      previewIndex += 1
    }
    return { ...message, blocks }
  })
  // Why anchored rather than appended: an echo whose transcript row never
  // arrives — Claude consumes a mid-turn send without writing a user record —
  // used to sit at the tail forever, re-reading below every turn that landed
  // afterwards. That is what makes the conversation look re-ordered. Rendering it
  // after the row it was sent against keeps it in place, so an unmatched echo is
  // at worst a duplicate in the right position instead of a scrambled one.
  const anchoredPending = new Map<string, NativeChatMessage[]>()
  const leadingPending: NativeChatMessage[] = []
  const trailingPending: NativeChatMessage[] = []
  const foldedIds = new Set(renderedFolded.map((message) => message.id))
  const missingBaselineIds = new Set<string>()
  for (const item of pending) {
    const baselineId = item.baselineTailMessageId
    if (baselineId && !foldedIds.has(baselineId)) {
      missingBaselineIds.add(baselineId)
    }
  }
  const foldedAnchorByRawId = new Map<string, string>()
  const leadingBaselineIds = new Set<string>()
  if (missingBaselineIds.size > 0) {
    let lastVisibleId: string | null = null
    const forwardImageBaselineIds: string[] = []
    for (const message of messages) {
      if (foldedIds.has(message.id)) {
        for (const baselineId of forwardImageBaselineIds) {
          foldedAnchorByRawId.set(baselineId, message.id)
        }
        forwardImageBaselineIds.length = 0
        lastVisibleId = message.id
      }
      if (!missingBaselineIds.has(message.id)) {
        continue
      }
      if (isImageSourceUserTurn(message)) {
        forwardImageBaselineIds.push(message.id)
      } else if (lastVisibleId) {
        foldedAnchorByRawId.set(message.id, lastVisibleId)
      } else {
        leadingBaselineIds.add(message.id)
      }
    }
  }
  for (const item of pending) {
    const bubble: NativeChatMessage = {
      id: item.id,
      role: 'user',
      // Text first (when present), then a thumbnail per ridden-along image so the
      // sent photo shows immediately, before the transcript echo lands.
      blocks: [
        ...(item.text ? [{ type: 'text' as const, text: item.text }] : []),
        ...(item.images ?? []).map((uri) => ({ type: 'image-ref' as const, url: uri }))
      ],
      timestamp: null,
      source: 'transcript'
    }
    // Tool/noise rows fold backward; image-source rows fold into their following prompt.
    const baselineId = item.baselineTailMessageId
    if (baselineId && leadingBaselineIds.has(baselineId)) {
      leadingPending.push(bubble)
      continue
    }
    const anchor = baselineId
      ? foldedIds.has(baselineId)
        ? baselineId
        : foldedAnchorByRawId.get(baselineId)
      : undefined
    if (!anchor || !foldedIds.has(anchor)) {
      trailingPending.push(bubble)
      continue
    }
    const siblings = anchoredPending.get(anchor)
    if (siblings) {
      siblings.push(bubble)
    } else {
      anchoredPending.set(anchor, [bubble])
    }
  }

  const data: NativeChatMessage[] = [...leadingPending]
  for (const message of renderedFolded) {
    data.push(message)
    const attached = anchoredPending.get(message.id)
    if (attached) {
      data.push(...attached)
    }
  }
  if (streaming) {
    data.push({
      id: 'streaming',
      role: 'assistant',
      blocks: [{ type: 'text', text: streaming }],
      timestamp: null,
      source: 'hook'
    })
  }
  data.push(...trailingPending)
  return { folded: renderedFolded, streaming, data }
}

mobile/src/session/mobile-structured-que.source:
// Render models for the host-held queued drafts shown above the composer.
// The wire carries no hold copy on purpose: the caption is derived here from the
// draft's own state plus the live facts the client already holds.

import {
  readWholeAgentSessionFailureFact,
  type AgentSessionFailureFact
} from '../../../src/shared/agent-session-failure'
import { agentSessionFailureStatedByRow } from '../../../src/shared/agent-session-visible-failures'
import {
  agentSessionWriteNotDoneParts,
  agentSessionWriteNoticeEnglish
} from '../../../src/shared/agent-session-refusal-notice'
import type { AgentJournalSubmission } from '../../../src/shared/agent-session-journal-types'
import { dispatchWasWithdrawn } from '../../../src/shared/structured-agent-session-dispatch-rejection'
import { structuredAgentSessionAttemptFailureParts } from '../../../src/shared/structured-agent-session-rejection-words'
import {
  QUEUED_MESSAGE_PAUSED_SEND_FAILED,
  type AgentSessionQueuedMessage
} from '../../../src/shared/agent-session-wire'
import { readAgentMessageSource } from '../../../src/shared/agent-session-message-source'
import { agentMessageAttribution } from './mobile-agent-message-attribution'

export type MobileQueuedMessageCard = {
  messageId: string
  /** The draft's text blocks joined for display and for Edit's composer copy. */
  text: string
  state: 'waiting' | 'returned'
  paused: boolean
  /** Returned, or its own send failed: the row leads with an alert. */
  needsAttention: boolean
  /** Status under the text; null for a card plainly waiting its turn, also behind an open
   *  question or in a paused queue: the question and the pause row say why. */
  caption: string | null
  /** "From <name>" on another agent's card; null on the person's. */
  attribution: string | null
  /** A conversation command such as /compact: it never steers into a running turn. */
  command?: true
  /** A command card while the agent works: it offers no send until the agent is idle. */
  waitsForAgent?: true
}

function queuedMessageBodyText(body: AgentSessionQueuedMessage['body']): string {
  return body.blocks.flatMap((block) => (block.type === 'text' ? [block.text] : [])).join('\n')
}

function returnedCaption(
  draft: Pick<AgentSessionQueuedMessage, 'returnedReason' | 'returnedRejection'>,
  agentName?: string,
  statedFailures: readonly AgentSessionFailureFact[] = []
): string {
  const reason = draft.returnedReason ?? null
  const rejection = draft.returnedRejection
  if (agentSessionFailureStatedByRow(rejection, statedFailures)) {
    return agentSessionWriteNoticeEnglish(agentSessionWriteNotDoneParts('send'))
  }
  if (dispatchWasWithdrawn({ dispatchState: 'rejected', reason, rejection })) {
    return 'Stopped before it was sent'
  }
  // Worded as the desktop card words it: a fact read whole decides, the host's reason is the
  // fallback, and the card's own Send is the retry, so the words leave out sending again.
  return agentSessionWriteNoticeEnglish(
    structuredAgentSessionAttemptFailureParts(
      { kind: 'rejected', reason },
      { agentName, retryControl: true },
      readWholeAgentSessionFailureFact(rejection)
    )
  )
}

/** One card's own hold: a failed conversion; the queue's pause is the list's header. */
function pausedCaption(reason: string | undefined, waitsForAgent: boolean): string {
  if (reason === QUEUED_MESSAGE_PAUSED_SEND_FAILED) {
    return waitsForAgent
      ? "Couldn't send — tap Send to retry once the agent finishes"
      : "Couldn't send — tap Send to retry"
  }
  // Absent or unknown (newer host) marker: a plain pause, promising no release rule.
  return 'Paused'
}

/** Whether Resume would send anything: a waiting card with no hold of its own, ahead of any
 *  returned card. The drain stops at a returned card, so cards behind one never go. */
export function mobileQueueHasResumableCard(cards: readonly MobileQueuedMessageCard[]): boolean {
  for (const card of cards) {
    if (card.state === 'returned') {
      return false
    }
    if (!card.paused) {
      return true
    }
  }
  return false
}

/** Cards in published order. A waiting card is hidden once a live hand-off of it arrived — a
 *  submission naming it as its `queuedMessageId` that was not rejected — as the desktop hides it:
 *  on a multi-page catch-up the shrunk list rides only the final page, so the bubble and the card
 *  would otherwise briefly show together. A rejected hand-off is what sent the draft back, so it
 *  hides nothing. Returned cards always show. */
export function mobileQueuedMessageCards(
  queuedMessages: readonly AgentSessionQueuedMessage[] | null,
  submissions: readonly Pick<AgentJournalSubmission, 'queuedMessageId' | 'dispatchState'>[],
  facts: {
    agentWorking?: boolean
    agentName?: string
    statedFailures?: readonly AgentSessionFailureFact[]
  } = {}
): MobileQueuedMessageCard[] {
  if (!queuedMessages || queuedMessages.length === 0) {
    return []
  }
  const handedOff = new Set(
    submissions.flatMap((submission) =>
      submission.queuedMessageId !== undefined && submission.dispatchState !== 'rejected'
        ? [submission.queuedMessageId]
        : []
    )
  )
  let behindReturned = false
  const cards: MobileQueuedMessageCard[] = []
  for (const draft of queuedMessages) {
    if (draft.state !== 'returned' && handedOff.has(draft.messageId)) {
      continue
    }
    const paused = draft.paused === true
    const caption =
      draft.state === 'returned'
        ? returnedCaption(draft, facts.agentName, facts.statedFailures)
        : paused
          ? pausedCaption(
              draft.pausedReason,
              draft.body.command !== undefined && facts.agentWorking === true
            )
          : behindReturned
            ? 'Waiting — a message ahead needs attention'
            : null
    cards.push({
      messageId: draft.messageId,
      text: queuedMessageBodyText(draft.body),
      state: draft.state,
      paused,
      needsAttention:
        draft.state === 'returned' ||
        (paused && draft.pausedReason === QUEUED_MESSAGE_PAUSED_SEND_FAILED),
      caption,
      attribution: agentMessageAttribution('From', readAgentMessageSource(draft.body.from)),
      ...(draft.body.command !== undefined
        ? {
            command: true as const,
            ...(facts.agentWorking ? { waitsForAgent: true as const } : {})
          }
        : {})
    })
    if (draft.state === 'returned') {
      behindReturned = true
    }
  }
  return cards
}

src/shared/agent-journal-tool-call-lifec.source:
// A tool call's lifecycle as readers show it. A call cut short keeps `state: 'failed'`, which every
// build reads, and carries the finer fact beside it: persisted rows outlive the build that wrote
// them, and a new state value would read as a success to a build that only knows these three.

import type {
  AgentJournalToolCallEnding,
  AgentJournalToolCallItem,
  AgentJournalToolCallState,
  AgentJournalTurnLifecycleState
} from './agent-session-journal-types'

export type AgentJournalToolCallLifecycle = AgentJournalToolCallState | 'interrupted'

/** How the turn or session around a still-running call ended. */
export type AgentJournalRunningCallEnd = Exclude<AgentJournalTurnLifecycleState, 'running'>

type ToolCallLifecycleFields = {
  state?: AgentJournalToolCallState
  endedAs?: AgentJournalToolCallEnding
}

/** Undefined when the lane reports no lifecycle, as legacy transcripts do. */
export function agentJournalToolCallLifecycle(
  call: ToolCallLifecycleFields
): AgentJournalToolCallLifecycle | undefined {
  return call.state === 'failed' && call.endedAs === 'interrupted' ? 'interrupted' : call.state
}

/** A call that stopped because its turn or session was proven to end, or the provider cancelled
 *  it: it neither finished nor failed on its own. */
export function interruptedAgentJournalToolCall(
  call: AgentJournalToolCallItem
): AgentJournalToolCallItem {
  return { ...call, state: 'failed', endedAs: 'interrupted' }
}

/** What a call still running when its turn or session ended becomes. Only a proven interruption
 *  cuts it short: a turn the provider completed around it, or an end the host could not verify,
 *  proves none, so it reads failed as it always has. An unverified end is kept beside that, so a
 *  proof written later can still find the call. */
export function endedRunningAgentJournalToolCall(
  call: AgentJournalToolCallItem,
  end: AgentJournalRunningCallEnd
): AgentJournalToolCallItem {
  if (end === 'interrupted') {
    return interruptedAgentJournalToolCall(call)
  }
  return end === 'unverifiable'
    ? { ...call, state: 'failed', endedAs: 'unverifiable' }
    : { ...call, state: 'failed' }
}

/** A call an unverified end closed: still waiting on a proof that its owner died. */
export function isUnverifiedEndAgentJournalToolCall(call: ToolCallLifecycleFields): boolean {
  return call.state === 'failed' && call.endedAs === 'unverifiable'
}

src/shared/agent-session-account-home.ts.source:
/** Durable account binding: existing single-directory records or OpenCode's data context. */

import type { AgentSessionStoredAgent } from './agent-session-stored-agent'

/** Account root pinned at launch by the account selector, so a resume cannot drift to another login. */
export type LegacyAgentSessionAccountHome = {
  /** Environment variable naming the agent's config directory. */
  variable: string
  /** Host-resolved absolute path in the execution host's own path syntax. */
  path: string
}

export type OpenCodeAccountLocator =
  | { kind: 'managed'; managedProfileId: string }
  // The user's own environment, read at every launch.
  | { kind: 'unmanaged' }

export type OpenCodeAgentSessionAccountHome = {
  kind: 'opencode'
  locator: OpenCodeAccountLocator
}

export type AgentSessionAccountHome =
  | LegacyAgentSessionAccountHome
  | OpenCodeAgentSessionAccountHome

export function isLegacyAgentSessionAccountHome(
  home: AgentSessionAccountHome
): home is LegacyAgentSessionAccountHome {
  return !('kind' in home)
}

export function requireLegacyAgentSessionAccountHome(
  home: AgentSessionAccountHome
): LegacyAgentSessionAccountHome {
  if (!isLegacyAgentSessionAccountHome(home)) {
    throw new Error('Expected a single-directory agent account binding.')
  }
  return home
}

export function agentSessionAccountHomesEqual(
  left: AgentSessionAccountHome,
  right: AgentSessionAccountHome
): boolean {
  if (isLegacyAgentSessionAccountHome(left)) {
    return (
      isLegacyAgentSessionAccountHome(right) &&
      left.variable === right.variable &&
      left.path === right.path
    )
  }
  if (isLegacyAgentSessionAccountHome(right)) {
    return false
  }
  if (left.locator.kind === 'managed') {
    return (
      right.locator.kind === 'managed' &&
      left.locator.managedProfileId === right.locator.managedProfileId
    )
  }
  return right.locator.kind === 'unmanaged'
}

/** The account home of `agent` at `path`. */
export function agentSessionAccountHome(
  agent: { accountHomeVariable: string },
  path: string
): LegacyAgentSessionAccountHome {
  return { variable: agent.accountHomeVariable, path }
}

/** Whether `home` is the kind of account `agent` pins: its own directory variable, or its locator
 *  kind. It becomes the child's environment, so a record pinning another agent's kind never starts. */
export function agentPinsAccountHome(
  agent: AgentSessionStoredAgent,
  home: AgentSessionAccountHome
): boolean {
  return isLegacyAgentSessionAccountHome(home)
    ? agent.accountHomeVariable !== undefined && home.variable === agent.accountHomeVariable
    : agent.accountLocatorKind === home.kind
}

function isBoundedAccountString(value: unknown, max: number): value is string {
  return (
    typeof value === 'string' &&
    value.length > 0 &&
    value.length <= max &&
    !value.includes('\u0000')
  )
}

const ENVIRONMENT_VARIABLE_NAME = /^[A-Za-z_][A-Za-z0-9_]{0,127}$/
export const MAX_PATH_LENGTH = 4096
const PROFILE_ID = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i

/** Shape only: whether the variable is the one the record's agent pins is a launch-time question
 *  (`agentDrivesSession`), so an agent that renames its variable never hides its chats. Fields a
 *  newer build adds are ignored, so its records stay readable here. */
export function isAgentSessionAccountHome(value: unknown): value is AgentSessionAccountHome {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) {
    return false
  }
  if (!('kind' in value)) {
    return (
      'variable' in value &&
      typeof value.variable === 'string' &&
      ENVIRONMENT_VARIABLE_NAME.test(value.variable) &&
      'path' in value &&
      isBoundedAccountString(value.path, MAX_PATH_LENGTH)
    )
  }
  if (
    value.kind !== 'opencode' ||
    !('locator' in value) ||
    typeof value.locator !== 'object' ||
    value.locator === null ||
    Array.isArray(value.locator) ||
    !('kind' in value.locator)
  ) {
    return false
  }
  const locator = value.locator
  if (locator.kind === 'managed') {
    return (
      'managedProfileId' in locator &&
      typeof locator.managedProfileId === 'string' &&
      PROFILE_ID.test(locator.managedProfileId)
    )
  }
  return locator.kind === 'unmanaged'
}

src/shared/agent-session-argument-proble.source:
/** Orca's validated saved Arguments refusal. The option has no value or user-authored operand. */
export type AgentSessionArgumentProblem = {
  agent: 'Codex' | 'Claude'
  option: string
  problem: 'unsupportedOption' | 'missingValue' | 'multipleValues' | 'positionalPrompt'
}

export function readAgentSessionArgumentProblem(
  value: unknown
): AgentSessionArgumentProblem | undefined {
  if (
    typeof value !== 'object' ||
    value === null ||
    Array.isArray(value) ||
    !('agent' in value) ||
    !('problem' in value) ||
    !('option' in value)
  ) {
    return undefined
  }
  const agent = value.agent
  const problem = value.problem
  const option = value.option
  if (
    (agent !== 'Codex' && agent !== 'Claude') ||
    (problem !== 'unsupportedOption' &&
      problem !== 'missingValue' &&
      problem !== 'multipleValues' &&
      problem !== 'positionalPrompt') ||
    typeof option !== 'string' ||
    (problem === 'positionalPrompt'
      ? option !== 'prompt'
      : !/^(?:--[a-zA-Z][a-zA-Z0-9-]{0,63}|-[a-zA-Z]|--\?)$/.test(option))
  ) {
    return undefined
  }
  return { agent, option, problem }
}

src/shared/agent-session-availability-se.source:
import { agentSessionSignInCopyId } from './agent-session-availability'
import type { AgentSessionFailureFact } from './agent-session-failure'
import type { AgentSessionFailureSay } from './agent-session-failure-copy'
import type {
  AgentSessionFailureWordsContext,
  AgentSessionFailureSurface
} from './agent-session-failure-words'
import { joinSentences } from './sentence-joining'
import { agentSessionSignInFor } from './agent-session-sign-in'

const SENTENCE_END = /[.!?。！？][\p{Pe}\p{Pf}"']*\s*$/u

// The sentences for a start no account or CLI on this host can make: also the chat's notice.

function agent(say: AgentSessionFailureSay, { agentName }: AgentSessionFailureWordsContext) {
  return { agent: agentName ?? say('theAgent') }
}

export function notSignedInSentence(
  context: AgentSessionFailureWordsContext,
  fact: AgentSessionFailureFact,
  say: AgentSessionFailureSay,
  surface: AgentSessionFailureSurface = 'row'
): string {
  const signIn = agentSessionSignInFor(context.agentName ?? context.provider)
  const copy = say(signIn ? agentSessionSignInCopyId(signIn.agent, fact.account) : 'notSignedIn', {
    ...agent(say, context),
    loginCommand: signIn?.loginCommand.join(' '),
    slashCommand: signIn && 'slashCommand' in signIn ? signIn.slashCommand : undefined
  })
  const next = context.retryControl
    ? undefined
    : context.command
      ? say('runCommandAgain', { command: context.command })
      : surface === 'rejection' &&
          context.messageSubmitted !== false &&
          signIn?.agent !== 'claude' &&
          signIn?.agent !== 'codex'
        ? say(signIn ? 'thenSendAgain' : 'signInThenSend')
        : undefined
  const detail = fact.detail?.audience === 'person' ? fact.detail.text : undefined
  const detailSentence =
    detail && next && !SENTENCE_END.test(detail) ? `${detail.trimEnd()}.` : detail
  return joinSentences(
    [copy, detailSentence, next].filter((sentence): sentence is string => sentence !== undefined)
  )
}

/** A command the start was for is still run again once the CLI is installed. */
export function cliMissingSentence(
  context: AgentSessionFailureWordsContext,
  say: AgentSessionFailureSay
): string {
  return joinSentences([
    say('cliMissing', agent(say, context)),
    ...(context.command && !context.retryControl
      ? [say('runCommandAgain', { command: context.command })]
      : [])
  ])
}

src/shared/agent-session-availability.ts.source:
import { agentSessionSignInFor } from './agent-session-sign-in'

export type AgentSessionAccountKind = 'managed' | 'system'

/** Why no chat can start under the account a chat runs with, as the host's catalog probe found it.
 *  Absent (an older host, or no verdict yet) is unknown, which shows nothing. */
export type AgentSessionUnavailable =
  | { reason: 'notSignedIn'; account?: AgentSessionAccountKind }
  | { reason: 'cliMissing' }

/** A reason this build does not know reads as unknown, never as a different reason. */
export function readAgentSessionUnavailable(value: unknown): AgentSessionUnavailable | null {
  if (typeof value !== 'object' || value === null || !('reason' in value)) {
    return null
  }
  if (value.reason === 'cliMissing') {
    return { reason: 'cliMissing' }
  }
  if (value.reason !== 'notSignedIn') {
    return null
  }
  const account = 'account' in value ? value.account : undefined
  return {
    reason: 'notSignedIn',
    ...(account === 'managed' || account === 'system' ? { account } : {})
  }
}

export function agentSessionSignInCopyId(provider: string, account?: AgentSessionAccountKind) {
  const signIn = agentSessionSignInFor(provider)
  return signIn?.agent === 'claude'
    ? account === 'managed'
      ? 'claudeManagedNotSignedIn'
      : 'claudeSystemNotSignedIn'
    : signIn?.agent === 'codex'
      ? account === 'managed'
        ? 'codexManagedNotSignedIn'
        : 'codexSystemNotSignedIn'
      : signIn?.agent === 'pi'
        ? 'interactiveAgentNotSignedIn'
        : signIn?.loginCommand.length
          ? 'agentCommandNotSignedIn'
          : 'agentNotSignedIn'
}

src/shared/agent-session-background-task.source:
// The background-tasks half of the agent-session wire: the per-task row, the
// roster state that carries it, and the field equality both the client reducer
// and the host status feed compare with. Split out of `agent-session-wire.ts`
// when that file reached its line budget; the definitions below are unchanged.

import type { AgentChildWorkView } from './agent-status-child-work-view'

/** Per-task run state, reusing the agent-state vocabulary the dashboard already
 *  renders. Optional on the wire: an old host sends none and clients fall back
 *  to kind-derived defaults. */
export type AgentSessionBackgroundTaskRunState =
  | 'working'
  | 'monitoring'
  | 'waiting'
  | 'blocked'
  | 'done'
  | 'idle'
  | 'unverifiable'

export type AgentSessionBackgroundTask = {
  id: string
  kind: 'agent' | 'workflow' | 'command' | 'monitor' | 'unknown'
  description?: string
  /** Provider-reported identity (e.g. a subagent type). `description` stays the
   *  display name; this is the fallback when the description is absent. */
  name?: string
  state?: AgentSessionBackgroundTaskRunState
  /** Host epoch ms when the task was first observed, so clients render elapsed. */
  startedAt?: number
  /** Cumulative provider-reported token usage, where the provider supplies it. */
  totalTokens?: number
  /** Whether this row's own stop can act on it. Absent means yes: every host
   *  that predates this field published only backgrounded, stoppable rows, and
   *  a client that read absence as "not stoppable" would hide a working control
   *  on those hosts. A row the host cannot target sends `false`. */
  stoppable?: boolean
}

export type AgentSessionBackgroundTaskState = {
  state: 'monitoring'
  /** Optional so mixed-version clients can consume state-only hosts. */
  tasks?: AgentSessionBackgroundTask[]
  /** Terminal-state siblings of a still-live roster, kept apart from `tasks`
   *  so old clients keep rendering exactly the live set they render today. */
  settledTasks?: AgentSessionBackgroundTask[]
  /** Optional so clients only send targeted stops to hosts that accept them. */
  supportsTaskStop?: boolean
  /** Whether an untargeted "stop everything" is available at all. Absent means
   *  yes: every host that predates this field accepted one, and a client that
   *  read absence as "no stop" would hide a working control on those hosts.
   *  A host whose provider exposes no honest stop sends `false`. */
  supportsStopAll?: boolean
  /** The host's child records for this session as views, live and recently settled; `tasks` and
   *  `settledTasks` are derived from them. Absent from older hosts. A reader that does not
   *  advertise `agent-session.background-task-child-views.v1` never receives a state whose only
   *  rows are settled: to it, as before, the roster is live work. */
  children?: AgentChildWorkView[]
  /** The host refused some of this session's child work for room, so what is listed is not all
   *  that runs; no row's absence means it ended. A refused child stops counting once a later
   *  report of it is admitted or it reports its own end; past the host's bound, and in every case
   *  once the provider session ends, the whole flag goes. */
  incomplete?: true
}

function backgroundTaskFieldsEqual(
  left: AgentSessionBackgroundTask,
  right: AgentSessionBackgroundTask
): boolean {
  return (
    left.id === right.id &&
    left.kind === right.kind &&
    left.description === right.description &&
    left.name === right.name &&
    left.state === right.state &&
    left.startedAt === right.startedAt &&
    left.totalTokens === right.totalTokens &&
    left.stoppable === right.stoppable
  )
}

/** Field equality for task lists, shared by the client reducer and the host
 *  status feed so a publish whose only change is one task's state is never
 *  judged equal and dropped. */
export function agentSessionBackgroundTasksEqual(
  left: AgentSessionBackgroundTask[] | undefined,
  right: AgentSessionBackgroundTask[] | undefined
): boolean {
  if (left === right) {
    return true
  }
  if (!left || !right || left.length !== right.length) {
    return false
  }
  return left.every((task, index) => backgroundTaskFieldsEqual(task, right[index]))
}

src/shared/agent-session-command-refusal.source:
// A conversation command refused for a reason the person can act on: said as that refusal is
// everywhere, so a command's row names what to wait for rather than "try it again".

import type { AgentSessionFailureFact } from './agent-session-failure'
import type { AgentSessionFailureSay } from './agent-session-failure-copy'
import type { AgentSessionConversationCommand } from './agent-session-conversation-command'
import { joinSentences } from './sentence-joining'

type ReasonWords = (
  say: AgentSessionFailureSay,
  command: AgentSessionConversationCommand | undefined
) => string | undefined

const STILL_WORKING: ReasonWords = (say, command) =>
  command
    ? joinSentences([say('agentStillWorking'), say('runCommandWhenDone', { command })])
    : undefined

/** A wait the person ends: nothing runs the command after it, so they run it again. */
const WAIT_THEN_RUN_AGAIN =
  (
    cause: 'backgroundTasksRunning' | 'agentStarting',
    wait: 'waitForBackgroundTasks' | 'waitForStart'
  ): ReasonWords =>
  (say, command) =>
    joinSentences([
      say(cause),
      say(wait),
      ...(command ? [say('runCommandAgain', { command })] : [])
    ])

const WORDS_BY_REASON: Partial<Record<string, ReasonWords>> = {
  backgroundTasksRunning: WAIT_THEN_RUN_AGAIN('backgroundTasksRunning', 'waitForBackgroundTasks'),
  handoffInFlight: WAIT_THEN_RUN_AGAIN('agentStarting', 'waitForStart'),
  turnActive: STILL_WORKING,
  messagesUnsettled: STILL_WORKING,
  promptPending: (say, command) => (command ? say('commandAfterAnswer', { command }) : undefined)
}

/** Undefined for a reason with no words of its own: the command's generic sentence says it. */
export function commandRefusedByReason(
  say: AgentSessionFailureSay,
  { command }: { command?: AgentSessionConversationCommand },
  fact: AgentSessionFailureFact
): string | undefined {
  const details = fact.refusal?.details
  const reason = details && 'reason' in details ? details.reason : undefined
  return reason === undefined ? undefined : WORDS_BY_REASON[reason]?.(say, command)
}

src/shared/agent-session-compaction.ts.source:
import { parseAgentJournalItemKey } from './agent-session-journal-item-key'
import { spelledProviderTimelineItemKey } from './provider-timeline-item-key'

export const AGENT_SESSION_COMPACTION_SKIPPED_PRESENTATION = 'compaction-skipped'

/** Older OMP outcomes carried their meaning in the host's reserved item identity. */
export function isAgentSessionLegacyCompactionResult(itemId: string): boolean {
  const identity = parseAgentJournalItemKey(itemId)
  return (
    identity?.provider === 'legacy' &&
    identity.agent === 'omp' &&
    spelledProviderTimelineItemKey(identity.recordId)?.startsWith('compaction%3Acompact%3A') ===
      true
  )
}

src/shared/agent-session-context-clear.t.source:
import type {
  AgentJournalItemBody,
  AgentJournalRenderItem,
  AgentJournalSubmission
} from './agent-session-journal-types'
import { isAgentSessionProviderContextBoundary } from './agent-session-provider-context'
import type { NativeChatMessage } from './native-chat-types'

export function isAgentSessionContextClear(body: AgentJournalItemBody | undefined): boolean {
  return body?.kind === 'status' && isAgentSessionProviderContextBoundary(body.contextClear)
}

export function isNativeChatContextClear(message: NativeChatMessage): boolean {
  return (
    message.role === 'system' &&
    message.blocks.some(
      (block) => block.type === 'text' && isAgentSessionProviderContextBoundary(block.contextClear)
    )
  )
}

export function agentSessionContextSequenceFor(
  sequence: number,
  boundaries: readonly number[]
): number {
  let left = 0
  let right = boundaries.length
  while (left < right) {
    const middle = Math.floor((left + right) / 2)
    if (boundaries[middle] < sequence) {
      left = middle + 1
    } else {
      right = middle
    }
  }
  return left > 0 ? boundaries[left - 1] : 0
}

export function latestAgentSessionContextClearSequence(
  items: Iterable<Pick<AgentJournalRenderItem, 'sequence' | 'body'>>
): number {
  let sequence = 0
  for (const item of items) {
    if (item.sequence > sequence && isAgentSessionContextClear(item.body)) {
      sequence = item.sequence
    }
  }
  return sequence
}

export function agentSessionCurrentContextRows(
  items: readonly AgentJournalRenderItem[],
  submissions: readonly AgentJournalSubmission[] = [],
  minimumSequence = 0
) {
  const sequence = Math.max(minimumSequence, latestAgentSessionContextClearSequence(items))
  return sequence > 0
    ? {
        items: items.filter((item) => item.sequence > sequence),
        submissions: submissions.filter(
          (submission) => (submission.acceptedSequence ?? 0) > sequence
        )
      }
    : { items, submissions }
}

src/shared/agent-session-context-usage-s.source:
// Admission for the context facts a turn row carries. Bounded to what the
// writer can produce, so a replayed row can never hold more than a live one.

import { z } from 'zod'
import {
  MAX_CONTEXT_CATEGORIES,
  MAX_CONTEXT_CATEGORY_NAME_CHARS,
  MAX_CONTEXT_MODEL_ID_CHARS,
  type AgentSessionContextUsage
} from './agent-session-context-usage'

const TokenCount = z.number().finite().nonnegative()
const WindowTokens = z.number().finite().positive()
const CapturedAt = z.number().finite()
const ModelId = z.string().min(1).max(MAX_CONTEXT_MODEL_ID_CHARS)

const TokenUsage = z.object({
  inputTokens: TokenCount,
  cacheCreationInputTokens: TokenCount,
  cacheReadInputTokens: TokenCount,
  outputTokens: TokenCount
})

const Used = z.discriminatedUnion('kind', [
  z.object({
    kind: z.literal('report'),
    model: ModelId,
    usedTokens: TokenCount,
    windowTokens: WindowTokens,
    percentage: z.number().finite(),
    autoCompactAtTokens: TokenCount.optional(),
    categories: z
      .array(
        z.object({
          name: z.string().min(1).max(MAX_CONTEXT_CATEGORY_NAME_CHARS),
          tokens: TokenCount,
          deferred: z.literal(true).optional()
        })
      )
      .max(MAX_CONTEXT_CATEGORIES),
    capturedAt: CapturedAt
  }),
  z.object({ kind: z.literal('estimate'), usage: TokenUsage, capturedAt: CapturedAt }),
  z.object({ kind: z.literal('unknown'), capturedAt: CapturedAt })
])

export const AgentSessionContextUsageSchema = z.object({
  window: z.object({ tokens: WindowTokens, capturedAt: CapturedAt }).optional(),
  used: Used.optional()
})

export function isAdmissibleAgentSessionContextUsage(
  value: unknown
): value is AgentSessionContextUsage {
  return AgentSessionContextUsageSchema.validate(value)
}

type Admits<T extends true> = T
export type CanonicalContextUsageIsAdmissible = Admits<
  AgentSessionContextUsage extends z.input<typeof AgentSessionContextUsageSchema> ? true : false
>

src/shared/agent-session-context-usage.t.source:
// What the provider has said about a session's context window, as facts on
// turn rows. Writes land only on the open or newest turn and each replaces its
// namesake, so a reader takes the part from the newest row that carries it.

/** The API's accounting on one assistant response. */
export type AgentSessionTokenUsage = {
  inputTokens: number
  cacheCreationInputTokens: number
  cacheReadInputTokens: number
  outputTokens: number
}

/** Everything the model read on that request, which is what fills the window. */
export function contextTokensFromUsage(usage: AgentSessionTokenUsage): number {
  return usage.inputTokens + usage.cacheCreationInputTokens + usage.cacheReadInputTokens
}

/** Longest model id a fact records; a longer one is not a model id. */
export const MAX_CONTEXT_MODEL_ID_CHARS = 256
export const MAX_CONTEXT_CATEGORIES = 64
export const MAX_CONTEXT_CATEGORY_NAME_CHARS = 80

/** One row of the provider's breakdown, as it names and counts it. */
export type AgentSessionContextUsageCategory = {
  /** Display name as the provider renders it, e.g. `Messages`. */
  name: string
  tokens: number
  /** Listed for awareness but loaded on demand, so outside the used count. */
  deferred?: true
}

/** The provider's own `/context` answer. */
export type AgentSessionContextReport = {
  /** Model the report was measured for. */
  model: string
  usedTokens: number
  windowTokens: number
  /** The provider's rounding, unclamped: an over-limit session reads above 100. */
  percentage: number
  /** Where the provider compacts on its own, when auto-compaction is on. */
  autoCompactAtTokens?: number
  categories: AgentSessionContextUsageCategory[]
  capturedAt: number
}

/** The main thread's window. After a model change the writer holds estimates until a new one lands. */
export type AgentSessionContextWindow = {
  tokens: number
  capturedAt: number
}

/** How much of the window is in use, as last learned. */
export type AgentSessionContextUsed =
  | ({ kind: 'report' } & AgentSessionContextReport)
  /** The newest main-thread response, whatever its blocks: its input is the
   *  live context size. A subagent's measures its own window. */
  | { kind: 'estimate'; usage: AgentSessionTokenUsage; capturedAt: number }
  /** Compaction, a conversation reset or a model change: unknown until a response or report restates it. */
  | { kind: 'unknown'; capturedAt: number }

/** Context facts on a turn row. An absent part says nothing. */
export type AgentSessionContextUsage = {
  window?: AgentSessionContextWindow
  used?: AgentSessionContextUsed
}

src/shared/agent-session-conversation-co.source:
import type { AgentSessionFailureFact } from './agent-session-failure'
import type { AgentSessionFailureSentence } from './agent-session-failure-words'
import type { AgentSessionQueuedSendReceipt } from './agent-session-wire'

export type AgentSessionConversationCommand = 'clear' | 'compact'

/** How long a client waits for a conversation command: the host may first start an agent at rest. */
export const AGENT_SESSION_CONVERSATION_COMMAND_TIMEOUT_MS = 195_000

export type AgentSessionConversationCommandResult = {
  command: AgentSessionConversationCommand
  state: 'completed' | 'unknown'
  replacementSessionId?: string
  /** A /compact the host holds as a card behind work in flight, with `state: 'completed'`: the
   *  card is its one surface from here. Only clients that sent `delivery` receive it. */
  queued?: AgentSessionQueuedSendReceipt
} &
  /** `error`: a sentence for a person; released clients print it as it is. */
  (
    | { error?: string; failure?: undefined }
    /** What failed, typed, beside its sentence, both from `agentSessionFailureWords`; `failure` is
     *  absent from older hosts. */
    | { error: AgentSessionFailureSentence; failure: AgentSessionFailureFact }
  )

export type AgentSessionConversationCommandRecord = AgentSessionConversationCommandResult & {
  runtimeFence?: number
  operationId: string
  callerKey: string
  phase: 'prepared' | 'committed'
}

/** A newer host may answer with a command this build doesn't know. */
export function isAgentSessionConversationCommand(
  value: unknown
): value is AgentSessionConversationCommand {
  return value === 'clear' || value === 'compact'
}

export function isAgentSessionConversationCommandResult(
  value: unknown
): value is AgentSessionConversationCommandResult {
  if (!value || typeof value !== 'object') {
    return false
  }
  const row = value as AgentSessionConversationCommandResult
  return (
    isAgentSessionConversationCommand(row.command) &&
    (row.state === 'completed' || row.state === 'unknown') &&
    (row.replacementSessionId === undefined ||
      (typeof row.replacementSessionId === 'string' &&
        /^[A-Za-z0-9_-]{8,128}$/.test(row.replacementSessionId))) &&
    (row.error === undefined || (typeof row.error === 'string' && row.error.length <= 4096))
  )
}

export function isAgentSessionConversationCommandRecord(
  value: unknown
): value is AgentSessionConversationCommandRecord {
  if (!isAgentSessionConversationCommandResult(value)) {
    return false
  }
  const row = value as AgentSessionConversationCommandRecord
  return (
    (row.phase === 'prepared' || row.phase === 'committed') &&
    (row.runtimeFence === undefined ||
      (Number.isSafeInteger(row.runtimeFence) && row.runtimeFence >= 0)) &&
    typeof row.operationId === 'string' &&
    row.operationId.length > 0 &&
    row.operationId.length <= 512 &&
    typeof row.callerKey === 'string' &&
    row.callerKey.length > 0 &&
    row.callerKey.length <= 512
  )
}

src/shared/agent-session-conversation-na.source:
// The conversation name Orca recorded for one structured chat, normalized once
// at the single boundary that writes it.
//
// The text is free-form and provider-supplied, so it is bounded and flattened
// here rather than trusted: a name carrying a newline or a bidi override is not
// something the record should ever hold.

import { sliceAtCodeUnitLimit } from './surrogate-safe-text-slice'

/** Well past any provider's own cap, short enough that a pasted essay cannot enter the record. */
export const AGENT_SESSION_CONVERSATION_NAME_MAX_LENGTH = 200

/** Whitespace, plus the C0/C1 controls, bidi controls and zero-width marks `\s`
 *  misses. A bidi override renders a label that reads as text the name does not
 *  contain, and a zero-width run renders as nothing at all. Subtracted from all
 *  of `\p{Cf}` rather than enumerated, so a format character Unicode adds later
 *  is covered with no list to remember; U+200C/U+200D are the one exception,
 *  being load-bearing in Persian, Hindi and every multi-part emoji. Accepted
 *  cost: the U+E0020-E007F tag sequences go too, so the England, Scotland and
 *  Wales flags degrade — far cheaper than an invisible payload in a label.
 *  Deliberately NOT reached: blank-RENDERING letters and marks such as U+2800,
 *  U+3164 and U+115F, which are Lo/So/Mn rather than any invisible category. A
 *  name made only of those is accepted and looks empty; Braille and the Hangul
 *  jamo fillers carry meaning in real text, so stripping them would cost more. */
const UNRENDERABLE_RUN = /(?:[\s\p{Cc}\p{Zl}\p{Zp}]|(?![\u200C\u200D])\p{Cf})+/gu

/** The joiners outlive the run above by design; alone — or separated only by the
 *  spaces that run collapsed to — they are still a blank label. */
const BLANK_ONLY = /^[\s\u200C\u200D]+$/u

/** A surrogate with no partner — a provider that truncated an emoji, usually.
 *  Under `u` this class matches ONLY unpaired ones, so astral characters keep
 *  both halves; left in, each renders as U+FFFD on every surface. */
const LONE_SURROGATE = /[\uD800-\uDFFF]/gu

/** A cut inside an emoji sequence strands the joiner that attached it. */
const TRAILING_DANGLE = /[\s\u200C\u200D]+$/u

export function normalizeAgentSessionConversationName(value: unknown): string | null {
  if (typeof value !== 'string') {
    return null
  }
  // Surrogates first, so the gap one leaves collapses with the run around it.
  const collapsed = value.replace(LONE_SURROGATE, '').replace(UNRENDERABLE_RUN, ' ').trim()
  if (!collapsed || BLANK_ONLY.test(collapsed)) {
    return null
  }
  if (collapsed.length <= AGENT_SESSION_CONVERSATION_NAME_MAX_LENGTH) {
    return collapsed
  }
  // Cut on a character boundary: a raw slice can strand a lone high surrogate,
  // which every surface then renders as U+FFFD.
  const truncated = sliceAtCodeUnitLimit(
    collapsed,
    AGENT_SESSION_CONVERSATION_NAME_MAX_LENGTH
  ).replace(TRAILING_DANGLE, '')
  return truncated || null
}

export function isAgentSessionConversationName(value: unknown): value is string {
  return (
    typeof value === 'string' &&
    value.length > 0 &&
    value.length <= AGENT_SESSION_CONVERSATION_NAME_MAX_LENGTH &&
    normalizeAgentSessionConversationName(value) === value
  )
}

src/shared/agent-session-failure-words.t.source:
// The sentence a person reads beside each failure fact, and the one constructor that writes both.
//
// A row's `text`, a rejected message's `reason` and a conversation command's `error` are what
// every released client prints as they are, so the host writes them here, from the fact, and
// nowhere else: never Orca's own error text, a refusal's message, or a probe's evidence. A
// provider's words reach the sentence only when the provider wrote them for a person. Each sentence
// is built from the pieces in `agent-session-failure-copy`, which desktop translates to word the
// same fact in the reader's language.

import {
  isSubmissionRejectionFact,
  type AgentSessionAttachmentProblem,
  type AgentSessionAttachmentProblemReason,
  type AgentSessionFailureFact,
  type AgentSessionFailureKind,
  type ProviderDiagnostic,
  type SubmissionRejectionFact,
  type SubmissionRejectionKind
} from './agent-session-failure'
import type { AgentSessionConversationCommand } from './agent-session-conversation-command'
import { cliMissingSentence, notSignedInSentence } from './agent-session-availability-sentences'
import {
  codexInstallationFailureWords,
  sayAgentSessionFailureEnglish,
  type AgentSessionFailureCopyId,
  type AgentSessionFailureCopyValues,
  type AgentSessionFailureSay
} from './agent-session-failure-copy'
import { START_REFUSAL_RESUMABLE } from './agent-session-start-refusal-resumable'
import { providerRetryWords, withRetryCause } from './agent-session-provider-retry-words'
import { commandRefusedByReason } from './agent-session-command-refusal-words'
import { joinSentences } from './sentence-joining'
import {
  DISPATCH_REJECTED_CANCELLED,
  DISPATCH_REJECTED_CODEX_QUEUE_FULL,
  DISPATCH_REJECTED_QUEUE_FULL,
  DISPATCH_REJECTED_WRITE_FAILED
} from './structured-agent-session-dispatch-rejection'

declare const failureSentence: unique symbol

/** Words only `agentSessionFailureWords` makes, so no writer can put its own beside a fact. */
export type AgentSessionFailureSentence = string & { readonly [failureSentence]: true }

/** A status row that reports a failure. */
export type AgentSessionFailureRowWords = {
  text: AgentSessionFailureSentence
  failure: AgentSessionFailureFact
}

/** A rejection as the host writes it: the sentence (or, for the cases released clients already
 *  hide, the legacy marker) they print, and the fact newer ones read. */
export type AgentJournalDispatchRejection = {
  reason: AgentSessionFailureSentence
  rejection: SubmissionRejectionFact
}

/** `row`: a status row, about the chat. `rejection`: a rejected message's reason, about it.
 *  `answer`: a refused answer to an approval or question, about it. */
export type AgentSessionFailureSurface = 'row' | 'rejection' | 'answer'

export type AgentSessionFailureWordsContext = {
  /** The chat's agent, when the writer knows it. */
  agentName?: string
  /** Names the legacy queue-full marker; without it a full queue is worded as a sentence. */
  provider?: 'claude' | 'codex'
  /** The conversation command a failed start was for, so the next step is to run it again
   *  rather than to send a message. */
  command?: AgentSessionConversationCommand
  /** The surface retries for the person — its own Retry beside the words, or a read that reconnects
   *  on its own — so they leave out sending or trying again. */
  retryControl?: boolean
  /** A direct create has no submitted message to send again. */
  messageSubmitted?: boolean
}

/** Person-facing provider text is quoted, but bounded so the sentence stays one. */
const MAX_QUOTED_DETAIL_CHARS = 512
const BYTES_PER_MB = 1024 * 1024

type Sentence = (
  context: AgentSessionFailureWordsContext,
  fact: AgentSessionFailureFact,
  surface: AgentSessionFailureSurface,
  say: AgentSessionFailureSay
) => string

function agent(say: AgentSessionFailureSay, { agentName }: AgentSessionFailureWordsContext) {
  return { agent: agentName ?? say('theAgent') }
}

function quotingPersonDetail(
  say: AgentSessionFailureSay,
  lead: AgentSessionFailureCopyId,
  quotedLead: AgentSessionFailureCopyId,
  detail: ProviderDiagnostic | undefined,
  values: AgentSessionFailureCopyValues = {}
): string {
  const quoted =
    detail?.audience === 'person'
      ? detail.text
          .slice(0, MAX_QUOTED_DETAIL_CHARS)
          .trim()
          .replace(/[.\s]+$/, '')
      : ''
  return quoted ? say(quotedLead, { ...values, detail: quoted }) : say(lead, values)
}

/** The next step after a start or restart that failed: the command, or the message, again. */
function startRetry(
  say: AgentSessionFailureSay,
  { command, retryControl, messageSubmitted }: AgentSessionFailureWordsContext,
  sendAgain: 'sendToTryAgain' | 'sendAgainToTryOnceMore' = 'sendToTryAgain'
): string[] {
  if (retryControl) {
    return []
  }
  return [
    command
      ? say('runCommandAgain', { command })
      : say(messageSubmitted === false ? 'sendToTryAgain' : sendAgain)
  ]
}

function couldNot(verb: 'couldNotStart' | 'couldNotRestart'): Sentence {
  return (context, fact, _surface, say) => {
    const installationFailure = codexInstallationFailureWords(fact.refusal, say)
    if (installationFailure) {
      return installationFailure
    }
    const failed = say(verb, agent(say, context))
    if (fact.argumentProblem) {
      const problemCopy = {
        unsupportedOption: 'argumentsUnsupportedOption',
        missingValue: 'argumentsMissingValue',
        multipleValues: 'argumentsMultipleValues',
        positionalPrompt: 'argumentsPositionalPrompt'
      } as const
      return joinSentences([
        failed,
        say(problemCopy[fact.argumentProblem.problem], { option: fact.argumentProblem.option }),
        say('editSavedArguments'),
        ...startRetry(say, context)
      ])
    }
    // Only a terminal agent an older build recorded holds a claim; quitting it frees the chat.
    if (fact.refusal?.details?.reason === 'claimConflicted') {
      return joinSentences([failed, say('terminalAgentHoldsChat'), say('quitTerminalAgent')])
    }
    // The previous process may still run, so nothing started: that, never that it exited.
    if (fact.refusal?.details?.reason === 'previousExitUnverifiable') {
      return joinSentences([
        say('previousExitUnverifiable', agent(say, context)),
        ...startRetry(say, context, 'sendAgainToTryOnceMore')
      ])
    }
    const code = fact.refusal?.code
    return joinSentences(
      code && !START_REFUSAL_RESUMABLE[code]
        ? [failed, say('startNewChat')]
        : [failed, ...startRetry(say, context)]
    )
  }
}

// The number only; each language's sentence carries its own unit.
function megabytes(bytes: number): string {
  return String(Math.round((bytes / BYTES_PER_MB) * 10) / 10)
}

const ATTACHMENT_SENTENCES = {
  empty: (say) => say('attachmentEmpty'),
  tooLarge: (say, _, { limit }) =>
    limit ? say('attachmentLargerThan', { size: megabytes(limit) }) : say('attachmentTooLarge'),
  tooMany: (say, context, { limit }) =>
    limit
      ? say('attachmentAtMost', { ...agent(say, context), limit: String(limit) })
      : say('attachmentTooMany'),
  totalTooLarge: (say, _, { limit }) =>
    limit
      ? say('attachmentTotalMoreThan', { size: megabytes(limit) })
      : say('attachmentTotalTooLarge'),
  unsupportedType: (say, context) => say('attachmentUnsupportedType', agent(say, context)),
  notAFile: (say) => say('attachmentNotAFile'),
  noSource: (say) => say('attachmentNoSource')
} satisfies Record<
  AgentSessionAttachmentProblemReason,
  (
    say: AgentSessionFailureSay,
    context: AgentSessionFailureWordsContext,
    problem: AgentSessionAttachmentProblem
  ) => string
>

const FAILURE_SENTENCES = {
  providerStartFailed: (context, _fact, _surface, say) =>
    joinSentences([say('providerStartFailed', agent(say, context)), ...startRetry(say, context)]),
  startFailed: couldNot('couldNotStart'),
  notSignedIn: (context, fact, surface, say) => notSignedInSentence(context, fact, say, surface),
  cliMissing: (context, _fact, _surface, say) => cliMissingSentence(context, say),
  historyTooLarge: (_context, _fact, _surface, say) =>
    joinSentences([say('historyTooLarge'), say('startNewChat')]),
  managedAccountEnvOverride: (_context, _fact, _surface, say) => say('managedAccountEnvOverride'),
  accountSwitchInProgress: (_context, _fact, _surface, say) => say('accountSwitchInProgress'),
  launchFolderMissing: (_context, _fact, _surface, say) => say('launchFolderMissing'),
  historyInOtherAccount: (_context, _fact, _surface, say) => say('historyInOtherAccount'),
  claudeAccountFolderMissing: (_context, _fact, _surface, say) => say('claudeAccountFolderMissing'),
  claudeAccountSetupFailed: (_context, _fact, _surface, say) => say('claudeAccountSetupFailed'),
  agentCommandNotRunnable: (context, _fact, _surface, say) =>
    say('agentCommandNotRunnable', agent(say, context)),
  runtimeNotInstalled: (context, _fact, _surface, say) =>
    say('runtimeNotInstalled', agent(say, context)),
  managedAccountUnsupported: (context, _fact, _surface, say) =>
    joinSentences([
      say('managedAccountUnsupported'),
      context.retryControl || context.messageSubmitted === false
        ? say('chooseClaudeAccount')
        : context.command
          ? say('chooseClaudeAccountThenRunCommand', { command: context.command })
          : say('chooseClaudeAccountThenSend')
    ]),
  providerExited: (context, _fact, surface, say) =>
    say(
      surface === 'row'
        ? 'providerExitedRow'
        : surface === 'answer'
          ? 'providerExitedAnswer'
          : 'providerExitedRejection',
      agent(say, context)
    ),
  restartFailed: couldNot('couldNotRestart'),
  providerRejected: (context, fact, _surface, say) =>
    quotingPersonDetail(
      say,
      'providerRejected',
      'providerRejectedQuoted',
      fact.detail,
      agent(say, context)
    ),
  attachmentInvalid: (context, fact, _surface, say) =>
    fact.attachment
      ? ATTACHMENT_SENTENCES[fact.attachment.reason](say, context, fact.attachment)
      : say('attachmentInvalid'),
  attachmentUnreadable: (_context, _fact, _surface, say) => say('attachmentUnreadable'),
  emptyMessage: (_context, _fact, _surface, say) => say('emptyMessage'),
  queueFull: (_context, _fact, _surface, say) => say('queueFull'),
  writeFailed: (_context, _fact, _surface, say) => say('writeFailed'),
  cancelled: (_context, _fact, _surface, say) => say('cancelled'),
  chatClosed: (_context, _fact, _surface, say) => say('chatClosed'),
  hostRestarted: (_context, _fact, _surface, say) => say('hostRestarted'),
  notDelivered: ({ retryControl }, _fact, _surface, say) =>
    say(retryControl ? 'notDelivered' : 'notDeliveredSendAgain'),
  commandRefused: (context, fact, _surface, say) =>
    commandRefusedByReason(say, context, fact) ??
    say(context.retryControl ? 'commandRefused' : 'commandRefusedTryAgain'),
  compactionFailed: (_context, fact, _surface, say) =>
    quotingPersonDetail(say, 'compactionFailed', 'compactionFailedQuoted', fact.detail),
  compactionUnconfirmed: (_context, _fact, _surface, say) => say('compactionUnconfirmed'),
  cancelUnconfirmed: (_context, _fact, _surface, say) => say('cancelUnconfirmed'),
  // The agent was reached and declined, so the sentence says that, not that the Stop was lost.
  stopRefused: (context, fact, _surface, say) =>
    fact.detail?.audience === 'person'
      ? quotingPersonDetail(
          say,
          'stopRefused',
          'stopRefusedQuoted',
          fact.detail,
          agent(say, context)
        )
      : say('noTurnToStop', agent(say, context)),
  // Mid-sentence, so an unnamed agent is not capitalized.
  stopFailed: ({ agentName }, _fact, _surface, say) =>
    agentName ? say('couldNotStop', { agent: agentName }) : say('couldNotStopTheAgent'),
  backgroundTaskNotStopped: (_context, fact, _surface, say) =>
    say(fact.backgroundStop === 'task' ? 'backgroundTaskNotStopped' : 'backgroundTasksNotStopped'),
  answerUnconfirmed: (_context, _fact, _surface, say) => say('answerUnconfirmed'),
  hostFault: ({ retryControl }, _fact, _surface, say) =>
    say(retryControl ? 'hostFault' : 'hostFaultTryAgain'),
  hostStopped: (context, _fact, _surface, say) => say('hostStopped', agent(say, context)),
  // A provider that says how its retry is going, for a person, is quoted: that is the progress.
  providerRetrying: (context, { retry, detail }, _surface, say) =>
    detail?.audience === 'person'
      ? withRetryCause(
          quotingPersonDetail(
            say,
            'providerRetrying',
            'providerRetryingQuoted',
            detail,
            agent(say, context)
          ),
          retry?.cause
        )
      : providerRetryWords(say, agent(say, context), retry),
  previousExitUnverifiable: (context, _fact, _surface, say) =>
    say('previousExitUnverifiable', agent(say, context)),
  sessionNotRestored: (context, _fact, _surface, say) =>
    say('sessionNotRestored', agent(say, context))
} satisfies Record<AgentSessionFailureKind, Sentence>

/** The sentence a person reads for this fact on this surface; never a marker. */
export function agentSessionFailureSentence(
  fact: AgentSessionFailureFact,
  surface: AgentSessionFailureSurface,
  context: AgentSessionFailureWordsContext = {},
  /** Desktop passes its translations; the host and the phone keep English. */
  say: AgentSessionFailureSay = sayAgentSessionFailureEnglish
): string {
  const sentence: Sentence = FAILURE_SENTENCES[fact.kind]
  return sentence(context, fact, surface, say)
}

/** The markers released clients hide, for the rejections that had one before rows carried a fact.
 *  A write failure is the bare marker: its error belongs in the log. */
const LEGACY_REJECTION_MARKERS: Partial<
  Record<SubmissionRejectionKind, (context: AgentSessionFailureWordsContext) => string | undefined>
> = {
  cancelled: () => DISPATCH_REJECTED_CANCELLED,
  writeFailed: () => DISPATCH_REJECTED_WRITE_FAILED,
  queueFull: ({ provider }) =>
    provider === 'codex'
      ? DISPATCH_REJECTED_CODEX_QUEUE_FULL
      : provider === 'claude'
        ? DISPATCH_REJECTED_QUEUE_FULL
        : undefined
}

/** The words a status row reporting this fact records. */
export function agentSessionFailureWords(
  fact: AgentSessionFailureFact,
  context: AgentSessionFailureWordsContext & { surface: 'row' }
): AgentSessionFailureRowWords
/** The words a message rejected for this fact records. */
export function agentSessionFailureWords(
  fact: SubmissionRejectionFact,
  context: AgentSessionFailureWordsContext & { surface: 'rejection' }
): AgentJournalDispatchRejection
export function agentSessionFailureWords(
  fact: AgentSessionFailureFact,
  context: AgentSessionFailureWordsContext & { surface: AgentSessionFailureSurface }
): AgentSessionFailureRowWords | AgentJournalDispatchRejection {
  if (context.surface === 'row') {
    return { text: branded(agentSessionFailureSentence(fact, 'row', context)), failure: fact }
  }
  // The rejection overload admits only these; a caller that got past the types is Orca's bug.
  if (!isSubmissionRejectionFact(fact)) {
    throw new Error(`agent session failure kind ${fact.kind} cannot reject a message`)
  }
  const words =
    LEGACY_REJECTION_MARKERS[fact.kind]?.(context) ??
    agentSessionFailureSentence(fact, 'rejection', context)
  return { reason: branded(words), rejection: fact }
}

function branded(words: string): AgentSessionFailureSentence {
  // oxlint-disable-next-line typescript/consistent-type-assertions -- SAFETY: only `agentSessionFailureWords` calls this, with words from the table or a legacy marker for its fact.
  return words as AgentSessionFailureSentence
}

src/shared/agent-session-failure.ts.source:
// What went wrong in a chat, typed where the host decides it, beside the sentence a person reads.
//
// The host writes both at once: `text`/`reason` stays a complete sentence because released clients
// print it as it is, and this fact is what newer clients choose their copy and action from. A
// provider's own words ride separately as `detail`, set only where Orca composed them from a
// value the provider wrote — never recovered from a string afterwards, since by then nothing can
// tell a provider's sentence from Orca's.

import type { AgentSessionAccountKind } from './agent-session-availability'
import {
  readAgentSessionArgumentProblem,
  type AgentSessionArgumentProblem
} from './agent-session-argument-problem'
export type { AgentSessionArgumentProblem } from './agent-session-argument-problem'

import { structuralValuesEqualIgnoringUndefined } from './structural-value-equality'
import {
  readAgentSessionRefusalReference,
  type AgentSessionRefusalReference
} from './agent-session-wire-refusals'

/** One per situation with its own honest next step; a new one needs copy before it compiles. */
export const AGENT_SESSION_FAILURE_KINDS = [
  /** Only an observed exit: the provider stopped while starting. */
  'providerStartFailed',
  /** A start that did not land, with no one to blame: Orca's fault, a failed spawn, a close. */
  'startFailed',
  'notSignedIn',
  /** The agent's CLI is not installed where the chat runs: its spawn found no such file. */
  'cliMissing',
  'historyTooLarge',
  'managedAccountEnvOverride',
  'accountSwitchInProgress',
  'managedAccountUnsupported',
  'launchFolderMissing',
  'historyInOtherAccount',
  'claudeAccountFolderMissing',
  'claudeAccountSetupFailed',
  'agentCommandNotRunnable',
  'runtimeNotInstalled',
  'providerExited',
  'restartFailed',
  'providerRejected',
  'attachmentInvalid',
  'attachmentUnreadable',
  'emptyMessage',
  'queueFull',
  'writeFailed',
  'cancelled',
  'chatClosed',
  'hostRestarted',
  'notDelivered',
  /** A conversation command the chat's state refused when its turn to run came. */
  'commandRefused',
  'compactionFailed',
  'compactionUnconfirmed',
  'cancelUnconfirmed',
  /** A Stop naming no turn reached the agent, which ended nothing while the chat read working. */
  'stopRefused',
  /** A Stop Orca could not save: only a refusal says it. */
  'stopFailed',
  /** A background-task Stop the agent answered with the task still running. */
  'backgroundTaskNotStopped',
  'answerUnconfirmed',
  'hostFault',
  /** Orca stopped an agent whose start never finished. */
  'hostStopped',
  /** The provider is retrying a request its API refused; not a failure yet. */
  'providerRetrying',
  /** A child a Stop could not prove gone: its exit is unverifiable. Kept for rows hosts wrote. */
  'previousExitUnverifiable',
  /** The agent could not reopen the chat's saved session, so a fresh one without its memory continues it. */
  'sessionNotRestored'
] as const
export type AgentSessionFailureKind = (typeof AGENT_SESSION_FAILURE_KINDS)[number]

export function isAgentSessionFailureKind(value: unknown): value is AgentSessionFailureKind {
  return typeof value === 'string' && AGENT_SESSION_FAILURE_KINDS.some((kind) => kind === value)
}

/** Kinds only a status row reports: none is ever why a message was not sent. */
const STATUS_ROW_ONLY_FAILURE_KINDS = [
  'compactionFailed',
  'compactionUnconfirmed',
  'cancelUnconfirmed',
  'stopRefused',
  'stopFailed',
  'backgroundTaskNotStopped',
  'answerUnconfirmed',
  'providerRetrying',
  'previousExitUnverifiable',
  'sessionNotRestored'
] as const satisfies readonly AgentSessionFailureKind[]

/** Why a message was not sent. A new failure kind is one of these until listed above. */
export type SubmissionRejectionKind = Exclude<
  AgentSessionFailureKind,
  (typeof STATUS_ROW_ONLY_FAILURE_KINDS)[number]
>

export function isSubmissionRejectionKind(value: unknown): value is SubmissionRejectionKind {
  return (
    isAgentSessionFailureKind(value) &&
    !STATUS_ROW_ONLY_FAILURE_KINDS.some((statusOnly) => statusOnly === value)
  )
}

/** `person`: written by the provider for whoever reads the chat, shown inline. `log`: a stderr
 *  tail or exit status, shown only behind Details. */
export type ProviderDiagnosticAudience = 'person' | 'log'

export type ProviderDiagnostic = {
  text: string
  audience: ProviderDiagnosticAudience
}

/** Stderr can be a whole dump; the row keeps enough to act on. The same cap as the exit reason a
 *  lease record keeps, so a diagnostic never outgrows what the record may store. */
export const MAX_PROVIDER_DIAGNOSTIC_CHARS = 512

/** Which of Orca's checks an image failed. A new one needs a sentence before it compiles. */
export const AGENT_SESSION_ATTACHMENT_PROBLEM_REASONS = [
  'empty',
  'tooLarge',
  'tooMany',
  'totalTooLarge',
  'unsupportedType',
  'notAFile',
  'noSource'
] as const
export type AgentSessionAttachmentProblemReason =
  (typeof AGENT_SESSION_ATTACHMENT_PROBLEM_REASONS)[number]

export type AgentSessionAttachmentProblem = {
  reason: AgentSessionAttachmentProblemReason
  /** The limit it broke: bytes for `tooLarge` and `totalTooLarge`, a count for `tooMany`. */
  limit?: number
}

/** What the provider said it is retrying, in its own fields. */
export type AgentSessionProviderRetry = {
  /** The provider's error type, e.g. `rate_limit` or `overloaded`. */
  error?: string
  /** The HTTP status the request failed with. */
  status?: number
  /** The provider's own account of what failed, written for a person: the row's second line. */
  cause?: string
  /** Which retry this is, counted from 1. */
  attempt?: number
  /** The most retries the provider makes before it gives up. */
  maxRetries?: number
}

export type AgentSessionFailureFact = {
  kind: AgentSessionFailureKind
  account?: AgentSessionAccountKind
  /** Provider-authored only; absent whenever Orca wrote the words. */
  detail?: ProviderDiagnostic
  /** On `restartFailed` and `startFailed`: the refusal that kept the agent from starting. On
   *  `commandRefused`: the refusal that kept the command from running. */
  refusal?: AgentSessionRefusalReference
  /** On `attachmentInvalid`: which check the attachment failed. */
  attachment?: AgentSessionAttachmentProblem
  /** On `providerRetrying`: why the provider is retrying. */
  retry?: AgentSessionProviderRetry
  /** A safe option name from Orca's saved Arguments parser, never an error message. */
  argumentProblem?: AgentSessionArgumentProblem
  /** Written only where Orca proves the agent never received the message: a Stop's withdrawal is
   *  then owed as stopped history, and a refused carrier owes its history again. Absent means
   *  unknown. Host-only; clients read the kind. */
  neverReachedAgent?: true
  /** On `backgroundTaskNotStopped`: one named task, or every task the Stop reached. */
  backgroundStop?: AgentSessionBackgroundStop
}

export type AgentSessionBackgroundStop = 'task' | 'all'

/** A fact as a row stores it: its kind may be one a newer host added, so only
 *  `readAgentSessionFailureFact` or the rejection classifier may place it. */
export type UnreadAgentSessionFailureFact = { kind: string }

/** A fact a rejected message may carry. */
export type SubmissionRejectionFact = AgentSessionFailureFact & { kind: SubmissionRejectionKind }

export function isSubmissionRejectionFact(
  fact: AgentSessionFailureFact
): fact is SubmissionRejectionFact {
  return isSubmissionRejectionKind(fact.kind)
}

/** Null for empty text, so a writer never records a detail with nothing in it. */
export function providerDiagnostic(
  text: string,
  audience: ProviderDiagnosticAudience
): ProviderDiagnostic | undefined {
  const bounded = text.trim().slice(0, MAX_PROVIDER_DIAGNOSTIC_CHARS).trim()
  return bounded ? { text: bounded, audience } : undefined
}

export function agentSessionFailureFact<TKind extends AgentSessionFailureKind>(
  kind: TKind,
  extra: {
    account?: AgentSessionAccountKind
    detail?: ProviderDiagnostic
    refusal?: AgentSessionRefusalReference
    attachment?: AgentSessionAttachmentProblem
    retry?: AgentSessionProviderRetry
    argumentProblem?: AgentSessionArgumentProblem
    neverReachedAgent?: true
    backgroundStop?: AgentSessionBackgroundStop
  } = {}
): AgentSessionFailureFact & { kind: TKind } {
  // Re-bounded here, so no writer can store more than the cap however it built the detail.
  const detail = extra.detail
    ? providerDiagnostic(extra.detail.text, extra.detail.audience)
    : undefined
  return {
    kind,
    ...(extra.account ? { account: extra.account } : {}),
    ...(detail ? { detail } : {}),
    ...(extra.refusal ? { refusal: extra.refusal } : {}),
    ...(extra.attachment ? { attachment: extra.attachment } : {}),
    ...(extra.retry ? { retry: extra.retry } : {}),
    ...(extra.argumentProblem ? { argumentProblem: extra.argumentProblem } : {}),
    ...(extra.neverReachedAgent ? { neverReachedAgent: true as const } : {}),
    ...(extra.backgroundStop ? { backgroundStop: extra.backgroundStop } : {})
  }
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

export function isProviderDiagnostic(value: unknown): value is ProviderDiagnostic {
  return (
    isRecord(value) &&
    typeof value.text === 'string' &&
    (value.audience === 'person' || value.audience === 'log')
  )
}

function readAttachmentProblem(value: unknown): AgentSessionAttachmentProblem | undefined {
  if (!isRecord(value)) {
    return undefined
  }
  const reason = AGENT_SESSION_ATTACHMENT_PROBLEM_REASONS.find((known) => known === value.reason)
  if (!reason) {
    return undefined
  }
  const limit = value.limit
  return typeof limit === 'number' && Number.isFinite(limit) && limit > 0
    ? { reason, limit }
    : { reason }
}

/** A retry as a reader meets it; undefined when it names no field. */
export function readProviderRetry(value: unknown): AgentSessionProviderRetry | undefined {
  if (!isRecord(value)) {
    return undefined
  }
  const error =
    typeof value.error === 'string' && value.error.trim() ? value.error.trim() : undefined
  const status = positiveInteger(value.status)
  const cause =
    typeof value.cause === 'string' ? providerDiagnostic(value.cause, 'person')?.text : undefined
  const attempt = positiveInteger(value.attempt)
  // A maximum bounds a retry; alone, or below the retry it bounds, it says nothing.
  const max = positiveInteger(value.maxRetries)
  const maxRetries = attempt && max && max >= attempt ? max : undefined
  return error || status || cause || attempt
    ? {
        ...(error ? { error } : {}),
        ...(status ? { status } : {}),
        ...(cause ? { cause } : {}),
        ...(attempt ? { attempt } : {}),
        ...(maxRetries ? { maxRetries } : {})
      }
    : undefined
}

function positiveInteger(value: unknown): number | undefined {
  return typeof value === 'number' && Number.isInteger(value) && value > 0 ? value : undefined
}

/** A fact as a reader meets it. Undefined for anything this build cannot place, including a kind a
 *  newer host added, so the reader falls back to what it does for a row with no fact. */
export function readAgentSessionFailureFact(value: unknown): AgentSessionFailureFact | undefined {
  if (!isRecord(value) || !isAgentSessionFailureKind(value.kind)) {
    return undefined
  }
  const refusal = readAgentSessionRefusalReference(value.refusal)
  const attachment = readAttachmentProblem(value.attachment)
  const retry = readProviderRetry(value.retry)
  const argumentProblem = readAgentSessionArgumentProblem(value.argumentProblem)
  return agentSessionFailureFact(value.kind, {
    ...(value.account === 'managed' || value.account === 'system'
      ? { account: value.account }
      : {}),
    ...(isProviderDiagnostic(value.detail) ? { detail: value.detail } : {}),
    ...(refusal ? { refusal } : {}),
    ...(attachment ? { attachment } : {}),
    ...(retry ? { retry } : {}),
    ...(argumentProblem ? { argumentProblem } : {}),
    ...(value.neverReachedAgent === true ? { neverReachedAgent: true as const } : {}),
    ...(value.backgroundStop === 'task' || value.backgroundStop === 'all'
      ? { backgroundStop: value.backgroundStop }
      : {})
  })
}

/** The fact only when this build read all of it. Anything it dropped, such as a newer refusal code
 *  or reason, may change the advice, so a surface that would re-word the fact shows the host's
 *  sentence instead. */
export function readWholeAgentSessionFailureFact(
  value: unknown
): AgentSessionFailureFact | undefined {
  const fact = readAgentSessionFailureFact(value)
  return fact && structuralValuesEqualIgnoringUndefined(fact, value) ? fact : undefined
}

/** The provider-authored diagnostic an error carries, set only where it was composed. Follows the
 *  `cause` chain, since wrappers such as the acquisition errors keep the original as their cause. */
export function providerDiagnosticOf(error: unknown): ProviderDiagnostic | undefined {
  return providerDiagnosticWithin(error, 0)
}

// One depth bound across `cause` and aggregated errors, so an error that contains itself ends.
function providerDiagnosticWithin(error: unknown, start: number): ProviderDiagnostic | undefined {
  let current: unknown = error
  for (let depth = start; depth < 6 && current instanceof Error; depth += 1) {
    if ('providerDiagnostic' in current && isProviderDiagnostic(current.providerDiagnostic)) {
      return current.providerDiagnostic
    }
    if (current instanceof AggregateError) {
      for (const inner of current.errors) {
        const found = providerDiagnosticWithin(inner, depth + 1)
        if (found) {
          return found
        }
      }
    }
    current = current.cause
  }
  return undefined
}

/** Attaches the provider's words to the error Orca built around them. */
export function withProviderDiagnostic<TError extends Error>(
  error: TError,
  diagnostic: ProviderDiagnostic | undefined
): TError {
  return diagnostic ? Object.assign(error, { providerDiagnostic: diagnostic }) : error
}

src/shared/agent-session-host-status-row.source:
// Status rows a host writes in its own words. Each names itself with a presentation so a client can
// say it in the reader's language; its `text` stays the words for a client that can't.

import type { AgentJournalPlainStatusItem } from './agent-session-journal-types'

export const AGENT_SESSION_HOST_STATUS_COPY = {
  /** A repair skipped rows it could not read. */
  'history-repaired': "Part of this chat's history couldn't be loaded.",
  /** In place of an item too large for any history page. */
  'history-item-too-large': 'This part of the chat was too large to show.'
} as const

export type AgentSessionHostStatusPresentation = keyof typeof AGENT_SESSION_HOST_STATUS_COPY

export function agentSessionHostStatusBody(
  presentation: AgentSessionHostStatusPresentation
): AgentJournalPlainStatusItem {
  return { kind: 'status', text: AGENT_SESSION_HOST_STATUS_COPY[presentation], presentation }
}

export function isAgentSessionHostStatusPresentation(
  presentation: string | undefined
): presentation is AgentSessionHostStatusPresentation {
  return presentation !== undefined && Object.hasOwn(AGENT_SESSION_HOST_STATUS_COPY, presentation)
}

src/shared/agent-session-journal-item-ke.source:
// Item-identity → stable journal key. Pure and shared: the host keys upserts
// with it and clients reconcile optimistic sends against the same string.
//
// Components are percent-encoded before joining so a value containing the
// delimiter cannot collide with a different identity.

import type { AgentJournalItemIdentity } from './agent-session-journal-types'

const KEY_DELIMITER = ':'
const VERBATIM_BOUNDED_COMPONENT_TAG = '%FF'
const BOUNDED_COMPONENT_PATTERN = /^[\s\S]{0,40}~orca-oversized~(?:[1-9]\d*)~[0-9a-f]{16}$/
const PARSED_JOURNAL_ITEM_KEY = Symbol('parsedJournalItemKey')

type ParsedJournalItemIdentity = AgentJournalItemIdentity & {
  readonly [PARSED_JOURNAL_ITEM_KEY]?: string
}

/** Longest raw component a key may embed. Real provider ids are tens of bytes;
 *  anything larger would push the composed key past wire page budgets, so it
 *  travels as a stable digest instead of verbatim. */
export const MAX_JOURNAL_KEY_COMPONENT_CHARS = 1024

/**
 * Deterministic stand-in for an oversized or ill-formed key component: same
 * input, same output, so revisions and tombstones of one identity still share
 * a key, and re-deriving from a parsed key is a fixed point (the bounded form
 * is well-formed and far below the cap). The head keeps keys debuggable;
 * length plus two independent hashes makes an accidental collision practically
 * impossible. Pure JS because clients derive keys too and cannot reach
 * node:crypto.
 *
 * JSON strings are arbitrary UTF-16 code units, so a component can carry a
 * lone surrogate that `encodeURIComponent` throws on. Those values take the
 * digest form too: the hashes run over the raw code units, so a value and its
 * replacement-character spelling keep distinct keys.
 */
export function boundJournalKeyComponent(value: string): string {
  if (value.length <= MAX_JOURNAL_KEY_COMPONENT_CHARS && !hasLoneSurrogate(value)) {
    return value
  }
  const h1 = fnv1a32(value, 0x811c9dc5).toString(16).padStart(8, '0')
  const h2 = fnv1a32(value, 0x0100_0193).toString(16).padStart(8, '0')
  return `${wellFormedBoundedHead(value, 40)}~orca-oversized~${value.length}~${h1}${h2}`
}

/** The diagnostic head must be valid Unicode for `encodeURIComponent`: a pair
 *  split by the cut is dropped and a lone surrogate becomes U+FFFD — the
 *  hashes over the raw units keep the full key collision-safe regardless.
 *  Digest forms are persisted, so for well-formed input the head must stay
 *  byte-stable across builds or one identity would stop sharing a key. */
function wellFormedBoundedHead(value: string, maxUnits: number): string {
  let head = ''
  let index = 0
  while (index < value.length && index < maxUnits) {
    const unit = value.charCodeAt(index)
    if (unit >= 0xd800 && unit <= 0xdbff) {
      const next = index + 1 < value.length ? value.charCodeAt(index + 1) : 0
      if (next >= 0xdc00 && next <= 0xdfff) {
        if (index + 1 >= maxUnits) {
          break
        }
        head += value.charAt(index) + value.charAt(index + 1)
        index += 2
        continue
      }
      head += '�'
      index += 1
      continue
    }
    head += unit >= 0xdc00 && unit <= 0xdfff ? '�' : value.charAt(index)
    index += 1
  }
  return head
}

function hasLoneSurrogate(value: string): boolean {
  for (let index = 0; index < value.length; index += 1) {
    const unit = value.charCodeAt(index)
    if (unit >= 0xd800 && unit <= 0xdbff) {
      const next = index + 1 < value.length ? value.charCodeAt(index + 1) : 0
      if (next < 0xdc00 || next > 0xdfff) {
        return true
      }
      index += 1
    } else if (unit >= 0xdc00 && unit <= 0xdfff) {
      return true
    }
  }
  return false
}

function fnv1a32(value: string, seed: number): number {
  let hash = seed >>> 0
  for (let index = 0; index < value.length; index += 1) {
    hash ^= value.charCodeAt(index)
    hash = Math.imul(hash, 0x0100_0193) >>> 0
  }
  return hash >>> 0
}

function encodePart(value: string | number): string {
  const raw = String(value)
  const bounded = boundJournalKeyComponent(raw)
  const encoded = encodeURIComponent(bounded)
  // `%FF` is not valid UTF-8 and cannot be emitted by encodeURIComponent.
  return raw === bounded && isBoundedComponentRepresentation(raw)
    ? `${VERBATIM_BOUNDED_COMPONENT_TAG}${encoded}`
    : encoded
}

function isBoundedComponentRepresentation(value: string): boolean {
  return BOUNDED_COMPONENT_PATTERN.test(value)
}

/**
 * Stable string key for an item identity.
 *
 * Codex renumbers `item-N` ids on every resume, so its key is the thread, the
 * turn, and the item's ordinal WITHIN that turn — a position that survives
 * renumbering because a completed turn's item list does not change. `thread/fork`
 * copies turns keeping their original turn ids, so the thread id must stay in the
 * key. Claude copies item uuids on `--fork-session`, so its key is the session id
 * plus the uuid. Text never participates.
 */
export function agentJournalItemKey(identity: AgentJournalItemIdentity): string {
  // Parsed pre-tag digest keys must keep addressing their persisted revision chain.
  const parsedKey = (identity as ParsedJournalItemIdentity)[PARSED_JOURNAL_ITEM_KEY]
  if (parsedKey !== undefined) {
    return parsedKey
  }
  if (identity.provider === 'codex') {
    return [
      'codex',
      encodePart(identity.threadId),
      encodePart(identity.turnId),
      encodePart(identity.ordinal)
    ].join(KEY_DELIMITER)
  }
  if (identity.provider === 'claude') {
    return ['claude', encodePart(identity.sessionId), encodePart(identity.uuid)].join(KEY_DELIMITER)
  }
  if (identity.provider === 'orca') {
    return ['orca', encodePart(identity.clientMessageId)].join(KEY_DELIMITER)
  }
  return [
    'legacy',
    encodePart(identity.agent),
    encodePart(identity.sessionId),
    encodePart(identity.recordId)
  ].join(KEY_DELIMITER)
}

/** Key for the pre-dispatch submission placeholder, before any provider echo. */
export function agentJournalSubmissionKey(clientMessageId: string): string {
  return agentJournalItemKey({ provider: 'orca', clientMessageId })
}

/**
 * Inverse of {@link agentJournalItemKey}. Clients hold item KEYS, but an upsert
 * needs the identity behind one — answering an approval re-appends the same
 * item at the next revision. Components are percent-encoded; raw strings that
 * imitate a bounded component carry a reserved encoded-domain tag.
 */
export function parseAgentJournalItemKey(key: string): AgentJournalItemIdentity | null {
  // Persisted keys can be corrupted: a malformed percent sequence must fail
  // the parse, never throw through journal replay or open.
  const parts: string[] = []
  let preserveExactKey = false
  for (const part of key.split(KEY_DELIMITER)) {
    const decoded = decodePart(part)
    if (!decoded) {
      return null
    }
    parts.push(decoded.value)
    preserveExactKey ||= decoded.tagged || isBoundedComponentRepresentation(decoded.value)
  }
  const [provider, ...rest] = parts
  if (provider === 'codex' && rest.length === 3) {
    const ordinal = Number(rest[2])
    return Number.isSafeInteger(ordinal) && ordinal >= 0
      ? parsedIdentity(
          { provider, threadId: rest[0] as string, turnId: rest[1] as string, ordinal },
          key,
          preserveExactKey
        )
      : null
  }
  if (provider === 'claude' && rest.length === 2) {
    return parsedIdentity(
      { provider, sessionId: rest[0] as string, uuid: rest[1] as string },
      key,
      preserveExactKey
    )
  }
  if (provider === 'orca' && rest.length === 1) {
    return parsedIdentity({ provider, clientMessageId: rest[0] as string }, key, preserveExactKey)
  }
  if (provider === 'legacy' && rest.length === 3) {
    return parsedIdentity(
      {
        provider,
        agent: rest[0] as string,
        sessionId: rest[1] as string,
        recordId: rest[2] as string
      },
      key,
      preserveExactKey
    )
  }
  return null
}

function decodePart(part: string): { value: string; tagged: boolean } | null {
  const tagged = part.startsWith(VERBATIM_BOUNDED_COMPONENT_TAG)
  try {
    const value = decodeURIComponent(
      tagged ? part.slice(VERBATIM_BOUNDED_COMPONENT_TAG.length) : part
    )
    return !tagged || isBoundedComponentRepresentation(value) ? { value, tagged } : null
  } catch {
    return null
  }
}

function parsedIdentity<T extends AgentJournalItemIdentity>(
  identity: T,
  key: string,
  preserveExactKey: boolean
): T {
  if (preserveExactKey) {
    Object.defineProperty(identity, PARSED_JOURNAL_ITEM_KEY, { value: key })
  }
  return identity
}

src/shared/agent-session-journal-open-un.source:
// A discriminated union that reads a tag this build does not know instead of failing on it: the
// journal's blocks, goal states, approval subjects and item bodies, so a newer build can add one.

import { z } from 'zod'

/** A tag a newer build could have written: a string with something other than whitespace in it. */
export function isJournalTag(value: unknown): value is string {
  return typeof value === 'string' && value.trim() !== ''
}

/** Tags a discriminated union knows, read off it so the two can never disagree. */
export function knownTags(union: z.ZodDiscriminatedUnion): ReadonlySet<string> {
  const key = union.def.discriminator
  return new Set(
    union.options.flatMap((option) => {
      const tag = option instanceof z.ZodObject ? option.shape[key] : undefined
      return tag instanceof z.ZodLiteral ? [...tag.values].map(String) : []
    })
  )
}

/** A discriminated union a tag this build does not know still reads through: kept as-is, for a
 *  reader to skip. A tag of only whitespace is damage, as an empty one is. The catch-all aborts, so
 *  a known arm's own failure still reaches the reader. */
export function openDiscriminatedUnion<T extends z.ZodDiscriminatedUnion>(known: T) {
  const key = known.def.discriminator
  const tags = knownTags(known)
  const unknown = z
    .object({ [key]: z.string().regex(/\S/) })
    .refine((value) => !tags.has(value[key] ?? ''), { abort: true })
  return z.union([known, unknown])
}

src/shared/agent-session-journal-positio.source:
// The journal's own order: the sequence of the row that created an item, then the
// item's place among that row's writes. Time never enters it — a row recovered
// after a crash carries the provider's earlier clock at a later sequence.

import type { AgentJournalPosition, AgentJournalRenderItem } from './agent-session-journal-types'
import type { NativeChatMessage } from './native-chat-types'

type PositionedItem = Pick<AgentJournalRenderItem, 'sequence' | 'sequenceIndex'>

/** What every transcript row projected from a journal item carries, so a row
 *  that changes shape (a question once answered) keeps its identity and place. */
export function agentJournalItemRowOrigin(
  item: AgentJournalRenderItem
): Pick<NativeChatMessage, 'id' | 'timestamp' | 'source' | 'journalPosition'> {
  return {
    id: item.itemId,
    timestamp: item.observedAt,
    source: 'transcript',
    journalPosition: agentJournalItemPosition(item)
  }
}

export function agentJournalItemPosition(item: PositionedItem): AgentJournalPosition {
  return { sequence: item.sequence, index: item.sequenceIndex ?? 0 }
}

export function compareAgentJournalPositions(
  a: AgentJournalPosition,
  b: AgentJournalPosition
): number {
  return a.sequence - b.sequence || a.index - b.index
}

export function compareAgentJournalItems(a: PositionedItem, b: PositionedItem): number {
  return a.sequence - b.sequence || (a.sequenceIndex ?? 0) - (b.sequenceIndex ?? 0)
}

src/shared/agent-session-journal-produce.source:
// Which agent produced a journal row, and the one place absence is interpreted.
//
// One journal is the durable record of one agent SESSION, and a session may run
// subagents. Both agents' rows land in the same timeline, so every "what is this
// agent doing right now" reader has to say which producer it means. Readers ask
// "is this NOT mine", never "is this mine": the session's own agent stamps
// nothing, so root-ness is the absence of an id rather than a value to match.
// That absence is decided by a row's FIRST write: a later revision naming no
// producer keeps the row's existing one (see the journal reducer).

import type {
  AgentJournalProducerLinkage,
  AgentJournalRenderItem
} from './agent-session-journal-types'

/**
 * Whether the session's own agent produced this row, rather than a subagent.
 *
 * Presence, not truthiness. An id that failed to resolve is still an id, and a
 * truthy test would read it as root and put the child's content back on the
 * parent — the defect this attribution exists to remove, reintroduced through a
 * soft predicate. Rows written before linkage existed carry no id and read as
 * root, which reproduces exactly what those journals always showed.
 */
export function isRootAgentJournalItem(
  item: Pick<AgentJournalRenderItem, 'agentId'> | undefined
): boolean {
  return agentJournalItemSubagentId(item) === null
}

/** The subagent that produced a row, or null when the session's own agent did.
 *  Same reading of absence as {@link isRootAgentJournalItem}. */
export function agentJournalItemSubagentId(
  item: Pick<AgentJournalRenderItem, 'agentId'> | undefined
): string | null {
  return item?.agentId ?? null
}

/** Whether a write names its producer at all. One that does not revises a row
 *  without re-attributing it, so this is presence of any member, not of `agentId`. */
export function namesAgentJournalProducer(linkage: AgentJournalProducerLinkage): boolean {
  return (
    linkage.agentId !== undefined ||
    linkage.parentAgentId !== undefined ||
    linkage.providerParentRef !== undefined ||
    linkage.producerKind !== undefined ||
    linkage.attempt !== undefined
  )
}

/** Linkage as row fields, with absent members omitted rather than set to
 *  `undefined`. Every carrier spreads this, so a new field reaches the row
 *  through one edit instead of one per hop. */
export function agentJournalLinkageFields(
  linkage: AgentJournalProducerLinkage | undefined
): AgentJournalProducerLinkage {
  if (!linkage) {
    return {}
  }
  return {
    ...(linkage.agentId === undefined ? {} : { agentId: linkage.agentId }),
    ...(linkage.parentAgentId === undefined ? {} : { parentAgentId: linkage.parentAgentId }),
    ...(linkage.providerParentRef === undefined
      ? {}
      : { providerParentRef: linkage.providerParentRef }),
    ...(linkage.producerKind === undefined ? {} : { producerKind: linkage.producerKind }),
    ...(linkage.attempt === undefined ? {} : { attempt: linkage.attempt })
  }
}

src/shared/agent-session-journal-schemas.source:
// ─── Canonical runtime schemas for the journal render model ─────────────────
// The journal admits JSON it did not just write — persisted rows re-enter from
// SQLite on replay and are republished to clients — while the reducer, the
// shared projection, and the prompt surfaces dereference nested fields without
// guards. These schemas are the single deep validators for that render model:
// admission must reject a JSON-valid but structurally wrong item (a question
// whose `options` are null, a prompt without its `resolution`) so the row is
// refused at replay, where the chat fails to load, instead of throwing
// mid-render.
//
// Discriminants (`kind`, known block `type`s) are validated deeply. Open string
// fields (roles, dispatch/tool states) stay type-checked, never enum-checked,
// and unknown object keys pass — a same-version row written by a slightly
// newer build must not be misread as malformed (see journal-row-schema.ts).
//
// A newer writer extends a body only by new keys, new kinds of an open union, or a bumped row `v`,
// never by changing a field's type, a bound or a closed set this build checks (the closed sets are
// pinned in journal-closed-sets.test.ts). Open unions (a body's `kind`, a block's `type`, a goal's
// `state`, an approval subject's `kind`) keep a value this build does not know as-is and nobody
// draws it; the chat stays writable. Unreadable context usage is dropped
// (journal-row-unusable-annotations.ts). Any other failure is damage: the chat fails to load and
// nothing is deleted. A new value of an open string (turn, resolution, tool or goal `state`) is
// read as-is too, except that an older build's rewind replaces an unknown turn, tool or resolution
// state with a placeholder row and turns an unknown block into a text block of its raw JSON
// (structured-rewind-journal-body.ts); an unknown body kind is carried as-is. History pages carry
// no row `v`, so older clients see such a value too. It must be safe for every older build.

import { z } from 'zod'
import { AgentSessionContextUsageSchema } from './agent-session-context-usage-schema'
import { AgentJournalThreadGoalStateSchema } from './agent-session-journal-thread-goal-schema'
import { AgentSessionFailureFactSchema } from './agent-session-failure-fact-schema'
import { knownTags, openDiscriminatedUnion } from './agent-session-journal-open-union'
import type {
  AgentJournalItemBody,
  AgentJournalMessageItem,
  AgentJournalResolution,
  AgentJournalRenderItem
} from './agent-session-journal-types'

const BoundedPayload = z.object({
  head: z.string(),
  byteLength: z.number(),
  digest: z.string(),
  truncated: z.boolean()
})

const ProviderFrame = z.object({
  provider: z.string(),
  kind: z.string(),
  payload: BoundedPayload
})

const ToolMetadata = {
  mcpIdentity: z.object({ server: z.string(), tool: z.string() }).optional(),
  exitCode: z.number().int().optional(),
  durationMs: z.number().nonnegative().optional(),
  webSearchResults: z.array(z.object({ title: z.string(), url: z.string() })).optional()
}

/** Provider IDs are opaque; reject all-whitespace values without rewriting valid IDs. */
const ProviderCallId = z
  .string()
  .refine((value) => value.trim().length > 0, 'callId must contain a non-whitespace character')

/** Child-agent lifecycle stays an open string for the same reason tool states
 *  do: a state a newer build writes must not turn the row malformed. */
const SubagentEntry = z.object({
  id: z.string(),
  label: z.string(),
  state: z.string().min(1),
  tokens: z.number().optional(),
  startedAt: z.number().optional(),
  settledAt: z.number().optional()
})

/** Renderers select blocks by `type` equality and skip what they cannot draw,
 *  so an unknown block type stays admissible; a known type with a broken
 *  payload does not. */
const Block = openDiscriminatedUnion(
  z.discriminatedUnion('type', [
    z.object({
      type: z.literal('text'),
      text: z.string(),
      presentation: z.string().optional(),
      tone: z.string().optional(),
      providerFrame: ProviderFrame.optional()
    }),
    // `input: undefined` loses its key under JSON.stringify, so a persisted
    // canonical tool call may lack it entirely.
    z.object({
      type: z.literal('tool-call'),
      name: z.string(),
      input: z.unknown().optional(),
      callId: ProviderCallId.optional(),
      ...ToolMetadata
    }),
    z.object({
      type: z.literal('tool-result'),
      output: z.string(),
      isError: z.boolean().optional()
    }),
    z.object({
      type: z.literal('image-ref'),
      path: z.string().optional(),
      url: z.string().optional(),
      alt: z.string().optional()
    }),
    z.object({
      type: z.literal('subagent-group'),
      groupId: z.string(),
      agents: z.array(SubagentEntry)
    }),
    // `outcomeBasis` and `background` stay open for the same reason `state` does.
    SubagentEntry.extend({
      type: z.literal('subagent'),
      groupId: z.string(),
      parentId: z.string().optional(),
      run: z.string().optional(),
      outcomeBasis: z.string().optional(),
      background: z.boolean().optional()
    }),
    // `kind` and `state` stay open strings for the same reason a child's
    // lifecycle does: a vocabulary a newer build writes must not turn the row
    // malformed. The renderer falls back on anything it cannot name.
    z.object({
      type: z.literal('background-task'),
      taskId: z.string().min(1),
      kind: z.string().min(1),
      label: z.string(),
      state: z.string().min(1),
      parentToolUseId: z.string().optional(),
      summary: z.string().optional(),
      error: z.string().optional(),
      outputFile: z.string().optional(),
      tokens: z.number().optional(),
      startedAt: z.number().optional(),
      settledAt: z.number().optional()
    })
  ])
)

const PromptOption = z.object({
  id: z.string(),
  label: z.string(),
  description: z.string().optional()
})

const FreeTextInput = z.object({
  allowEmpty: z.boolean().optional(),
  multiline: z.boolean().optional(),
  initialValue: z.string().optional(),
  placeholder: z.string().optional()
})

const Question = z.object({
  id: z.string(),
  question: z.string(),
  header: z.string().optional(),
  multiSelect: z.boolean(),
  options: z.array(PromptOption),
  freeTextQuestionId: z.string().optional(),
  freeTextInput: FreeTextInput.optional()
})

const Resolution = z.object({
  state: z.string().min(1),
  selectedOptionId: z.string().nullable(),
  answers: z
    .array(
      z.object({
        questionId: z.string(),
        optionIds: z.array(z.string()),
        other: z.string().optional()
      })
    )
    .optional(),
  resolvedBy: z.string().nullable(),
  resolvedAt: z.number().nullable()
})

const ApprovalMatchedAskRule = z.object({
  source: z.string(),
  toolName: z.string(),
  ruleContent: z.string().optional()
})

const KnownApprovalSubject = z.discriminatedUnion('kind', [
  z.object({ kind: z.literal('plan'), text: z.string().min(1), filePath: z.string().optional() })
])
export const AGENT_JOURNAL_APPROVAL_SUBJECT_KINDS = knownTags(KnownApprovalSubject)
/** Open like blocks; a subject this build cannot draw is never approvable here
 *  (agent-session-approval-subject.ts). */
const ApprovalSubject = openDiscriminatedUnion(KnownApprovalSubject)

const MessageBody = z.object({
  kind: z.literal('message'),
  role: z.string().min(1),
  blocks: z.array(Block),
  // Open like roles: a send mode a newer build writes must not turn the row malformed.
  sentAs: z.string().min(1).optional(),
  command: z.object({ name: z.string().min(1) }).optional(),
  // Open like `sentAs`: a state a newer host writes reads as completed, never malformed.
  state: z.string().min(1).optional(),
  completedAt: z.number().finite().optional()
})

/** A turn's lifecycle, as the turn item and the legacy status row both carry it. */
const TurnLifecycleFields = {
  turnId: z.string(),
  state: z.string().min(1),
  // Open like `state`: a verdict a newer build writes must not turn the row
  // malformed. `readAgentJournalTurnOutcome` is where an unplaceable one
  // becomes unknown rather than an arm a caller would act on.
  outcome: z.string().min(1).optional(),
  userItemId: z.string().min(1).optional(),
  startedAt: z.number().finite().positive().optional(),
  requestedAt: z.number().finite().positive().optional(),
  completedAt: z.number().finite().positive().optional(),
  durationMs: z.number().finite().nonnegative().optional()
}

const KnownItemBody = z.discriminatedUnion('kind', [
  MessageBody,
  z.object({
    kind: z.literal('tool-call'),
    ...ToolMetadata,
    name: z.string(),
    // See the tool-call block: the key itself is lost when `input` is undefined.
    input: z.unknown().optional(),
    callId: ProviderCallId.optional(),
    state: z.string().min(1),
    // Open like `state`: an ending a newer build writes reads as the `state` beside it.
    endedAs: z.string().min(1).optional(),
    output: BoundedPayload.optional()
  }),
  z.object({ kind: z.literal('diff'), path: z.string(), patch: BoundedPayload }),
  z.object({
    kind: z.literal('approval'),
    title: z.string(),
    displayName: z.string().optional(),
    description: z.string().optional(),
    decisionReason: z.string().optional(),
    blockedPath: z.string().optional(),
    matchedAskRule: ApprovalMatchedAskRule.optional(),
    subject: ApprovalSubject.optional(),
    detail: z.string().nullable(),
    options: z.array(PromptOption),
    resolution: Resolution
  }),
  z.object({
    kind: z.literal('question'),
    question: z.string(),
    options: z.array(PromptOption),
    questions: z.array(Question).optional(),
    freeTextQuestionId: z.string().optional(),
    freeTextInput: FreeTextInput.optional(),
    resolution: Resolution
  }),
  z.object({
    kind: z.literal('status'),
    text: z.string(),
    presentation: z.string().optional(),
    contextClear: z
      .object({
        operationId: z.string().min(1).max(512),
        afterFence: z.number().int().nonnegative(),
        clearedAt: z.number().int().nonnegative()
      })
      .optional(),
    tone: z.string().optional(),
    turnLifecycle: z.object(TurnLifecycleFields).optional(),
    providerFrame: ProviderFrame.optional(),
    threadGoal: AgentJournalThreadGoalStateSchema.optional(),
    failure: AgentSessionFailureFactSchema.optional(),
    orcaStop: z.object({ cause: z.string().min(1) }).optional()
  }),
  z.object({
    kind: z.literal('turn'),
    ...TurnLifecycleFields,
    contextUsage: AgentSessionContextUsageSchema.optional(),
    providerTurnId: z.string().min(1).optional()
  })
])

/** Every body kind this build knows; a body of another kind is kept as-is and drawn by nobody. */
export const AGENT_JOURNAL_ITEM_BODY_KINDS = knownTags(KnownItemBody)
export const AgentJournalItemBodySchema = openDiscriminatedUnion(KnownItemBody)

/** Producer linkage as it rides a render item across the process boundary.
 *  `producerKind` stays an open string for the reason the header gives: a host
 *  that learns a third kind must not make its rows unreadable to this client. */
export const AgentJournalProducerLinkageFields = {
  // `.min(1)` on every id: an EMPTY string is present, and the reader that
  // scopes a parent's surfaces tests presence, not truthiness. `agentId: ''`
  // would read as a subagent and hide the row from its own author for good.
  agentId: z.string().min(1).optional(),
  parentAgentId: z.string().min(1).optional(),
  providerParentRef: z.string().min(1).optional(),
  producerKind: z.string().min(1).optional(),
  attempt: z.number().int().optional()
} as const

/** Open like the other persisted vocabularies: a scope kind a newer host states must not turn
 *  the row malformed. A reader places only `turn` with an id; anything else reads as `thread`. */
export const AgentJournalTurnScopeSchema = z.object({
  kind: z.string().min(1),
  turnItemId: z.string().min(1).optional()
})

export const AgentJournalRenderItemSchema = z.object({
  itemId: z.string().min(1),
  revision: z.number().int(),
  body: AgentJournalItemBodySchema,
  sequence: z.number().int(),
  sequenceIndex: z.number().int().nonnegative().optional(),
  observedAt: z.number(),
  recovered: z.literal(true).optional(),
  recoveredAt: z.number().optional(),
  turnScope: AgentJournalTurnScopeSchema.optional(),
  ...AgentJournalProducerLinkageFields
})

export function isAgentJournalResolution(value: unknown): value is AgentJournalResolution {
  return Resolution.safeParse(value).success
}

export function isAdmissibleAgentJournalItemBody(value: unknown): value is AgentJournalItemBody {
  return AgentJournalItemBodySchema.safeParse(value).success
}

/** Submission rows may only carry a user-authored message body. */
export function isAdmissibleAgentJournalMessageBody(
  value: unknown
): value is AgentJournalMessageItem {
  return MessageBody.safeParse(value).success
}

export function isAdmissibleAgentJournalRenderItem(
  value: unknown
): value is AgentJournalRenderItem {
  return AgentJournalRenderItemSchema.safeParse(value).success
}

/** Compile-time proof that every canonical value is admissible, so replay can
 *  never reject a row a writer in this build produced. The schemas are
 *  deliberately wider on open string fields, so only this direction holds. */
type Admits<T extends true> = T
export type CanonicalJournalTypesAreAdmissible = [
  Admits<AgentJournalItemBody extends z.input<typeof AgentJournalItemBodySchema> ? true : false>,
  Admits<AgentJournalMessageItem extends z.input<typeof MessageBody> ? true : false>,
  Admits<AgentJournalRenderItem extends z.input<typeof AgentJournalRenderItemSchema> ? true : false>
]

