import type { AgentSessionLaunchArgs } from './agent-session-record'

const MAX_LAUNCH_ARGS = 256
const MAX_LAUNCH_ARGS_BYTES = 16 * 1024

/** Arguments pinned on a record's first reservation, bounded before they are persisted. */
export function isAgentSessionLaunchArgs(value: unknown): value is AgentSessionLaunchArgs {
  return (
    Array.isArray(value) &&
    value.length <= MAX_LAUNCH_ARGS &&
    value.every((arg) => typeof arg === 'string' && !arg.includes('\0')) &&
    Buffer.byteLength(JSON.stringify(value), 'utf8') <= MAX_LAUNCH_ARGS_BYTES
  )
}

src/shared/agent-session-legacy-handoff-.source:
/**
 * Lease values only older builds wrote.
 *
 * Records an older build persisted can still carry a terminal owner (`runtimeKind: 'tui'`), a
 * handoff stage (`preparing`, `old-owner-stopped`), or the removed ownerless-reservation latch
 * (`manual-recovery`). They are accepted on disk and mapped here, once, at decode, so no in-memory
 * lease holds a value nothing in this build produces.
 */

import type {
  AgentSessionHandoffStage,
  AgentSessionLease,
  AgentSessionOwnerRuntimeKind,
  AgentSessionRecord
} from './agent-session-record'
import type { PersistedAgentSessionProviderHandleLink } from './agent-session-provider-handle'

type LegacyHandoffRuntimeKind = 'tui'
type LegacyHandoffStage = 'preparing' | 'old-owner-stopped' | 'manual-recovery'

export type PersistedAgentSessionRuntimeKind =
  | AgentSessionOwnerRuntimeKind
  | LegacyHandoffRuntimeKind
export type PersistedAgentSessionHandoffStage = AgentSessionHandoffStage | LegacyHandoffStage

/** A lease as it may appear on disk. */
export type PersistedAgentSessionLease = Omit<AgentSessionLease, 'runtimeKind' | 'handoffStage'> & {
  runtimeKind: PersistedAgentSessionRuntimeKind
  handoffStage: PersistedAgentSessionHandoffStage | null
}

/** A record as a row stores it. Decode through `decodePersistedAgentSessionRecord`. */
export type PersistedAgentSessionRecord = Omit<
  AgentSessionRecord,
  'lease' | 'providerHandleChain'
> & {
  lease: PersistedAgentSessionLease
  providerHandleChain: PersistedAgentSessionProviderHandleLink[]
}

export function isPersistedAgentSessionRuntimeKind(
  value: unknown
): value is PersistedAgentSessionRuntimeKind {
  return value === 'native' || value === 'tui'
}

export function isPersistedAgentSessionHandoffStage(
  value: unknown
): value is PersistedAgentSessionHandoffStage {
  return (
    value === 'preparing' ||
    value === 'old-owner-stopped' ||
    value === 'new-owner-proving' ||
    value === 'recovering' ||
    value === 'manual-recovery'
  )
}

function isLegacyHandoffStage(
  stage: PersistedAgentSessionHandoffStage | null
): stage is LegacyHandoffStage {
  return stage === 'preparing' || stage === 'old-owner-stopped' || stage === 'manual-recovery'
}

export function leaseCarriesLegacyHandoffValues(lease: PersistedAgentSessionLease): boolean {
  return lease.runtimeKind === 'tui' || isLegacyHandoffStage(lease.handoffStage)
}

/** Identity for every lease this build writes. */
export function normalizeLegacyHandoffLease(lease: PersistedAgentSessionLease): AgentSessionLease {
  const { runtimeKind, handoffStage } = lease
  // Why: every one of these awaited proof about an owner, which is what `recovering` resolves.
  const stage = isLegacyHandoffStage(handoffStage) ? 'recovering' : handoffStage
  if (runtimeKind === 'native') {
    return { ...lease, runtimeKind, handoffStage: stage }
  }
  return {
    ...lease,
    runtimeKind: 'native',
    handoffStage: stage,
    // Why: a recorded terminal is the user's foreground agent. `conflicted` is the claim every
    // build probes but never stops; a plain native owner would be stopped by restart recovery.
    claimStatus: lease.ownerProcess === null ? lease.claimStatus : 'conflicted'
  }
}

/** A `conflicted` claim is a terminal agent an older build recorded, and only its exit frees the chat. */
export function terminalOwnerRefusalMessage(lease: AgentSessionLease): string {
  // Why: without a start time the pid may since belong to an unrelated process.
  const owner = lease.ownerProcess
  const process = owner?.processStartTimeMs != null ? ` (process ${owner.pid})` : ''
  return `This chat is still open in a terminal agent${process}. Quit that agent to continue the chat here.`
}

src/shared/agent-session-message-source..source:
// Who a chat message is from when it is not the person at the composer: another agent, through
// Orca. Carried on the message body (`AgentJournalMessageItem.from`), outside every fingerprint.

import { z } from 'zod'
import { normalizeAgentSessionConversationName } from './agent-session-conversation-name'
import { isOrcaSessionId, type OrcaSessionId } from './orca-session-address'
import type { OrchestrationPartyIdentity } from './orchestration-party-identity'
import { openEnum, salvagedField, salvagedOptional, salvagingArray } from './zod-salvage'

/**
 * An agent a message is from, named by the orchestration database of the host that stores the
 * message: a federated sender arrives as its `dispatch:<id>` address there. No pane key: it reads
 * and consumes that agent's mailbox, so the host resolves it from the address.
 */
export type AgentMessageSender = Readonly<{
  party: Omit<OrchestrationPartyIdentity, 'paneKey'>
  /** What Orca called the sender when it wrote, kept for when it is gone; null when it had none. */
  name: string | null
}>

/** One orchestration message a notice points at: its record, and its sender's `senders` address. */
export type OrchestrationMailMessage = Readonly<{ messageId: string; runId: string; from: string }>

/** "You have N orchestration messages": the pointer a terminal agent is typed, for a mailbox's
 *  unread mail, which the agent reads with `check`. */
export type OrchestrationMailNotice = Readonly<{
  message: 'mail-notice'
  mailbox: string
  dispatchId: string | null
  messages: readonly OrchestrationMailMessage[]
}>

/** A Dispatch's task, sent as the assignee's turn: the records it joins back to while they exist. */
export type OrchestrationTaskMessage = Readonly<{
  message: 'task'
  runId: string
  taskId: string
  dispatchId: string
}>

/** What Orca delivers for other agents, one shape per message kind. */
export type OrchestrationAgentMessage = OrchestrationMailNotice | OrchestrationTaskMessage

export type AgentMessageSource = Readonly<{
  kind: 'agent'
  /** Every distinct sender of the messages it carries, in mail order. */
  senders: readonly AgentMessageSender[]
  /** Null when this build cannot read the kind a newer one wrote; the senders still stand. */
  orchestration: OrchestrationAgentMessage | null
}>

/** Who a send is from, as its submission records it: the kind only (`AgentJournalSubmission.source`),
 *  so a restart or a close keeps only a person's unsent send as a card. The senders stay on the
 *  message body. */
export type AgentSessionMessageSource = Readonly<{ kind: 'user' | 'agent' }>

export const USER_MESSAGE_SOURCE: AgentSessionMessageSource = { kind: 'user' }

export const AGENT_MESSAGE_SOURCE: AgentSessionMessageSource = { kind: 'agent' }

/** A sender name as stored: bounded and flattened like a conversation name, never raw. */
export function agentMessageSenderName(value: unknown): string | null {
  return normalizeAgentSessionConversationName(value)
}

const orcaSessionIdSchema = z.custom<OrcaSessionId>(
  (value) => typeof value === 'string' && isOrcaSessionId(value)
)

const mailNoticeSchema = z.object({
  message: z.literal('mail-notice'),
  mailbox: z.string(),
  dispatchId: z.string().nullable(),
  messages: z.array(z.object({ messageId: z.string(), runId: z.string(), from: z.string() }))
})

const taskSchema = z.object({
  message: z.literal('task'),
  runId: z.string(),
  taskId: z.string(),
  dispatchId: z.string()
})

const senderSchema = z.object({
  party: z.object({
    address: z.string().min(1),
    terminalHandle: z.string().nullable(),
    orcaSessionId: orcaSessionIdSchema.nullable()
  }),
  name: z.unknown().transform(agentMessageSenderName)
})

// Read apart, so a malformed sender or an orchestration kind this build lacks never turns an
// agent's message into the person's.
const sourceSchema = z.object({
  kind: openEnum(['agent'], 'agent'),
  senders: salvagedField('senders', salvagingArray(senderSchema), () => []),
  orchestration: salvagedOptional(
    'orchestration',
    z.discriminatedUnion('message', [mailNoticeSchema, taskSchema])
  ).transform((orchestration) => orchestration ?? null)
})

/** The one reader of a stored or published `from`: undefined (the person's) when it is absent
 *  or not an agent's at all. */
export function readAgentMessageSource(value: unknown): AgentMessageSource | undefined {
  if (value === undefined) {
    return undefined
  }
  const parsed = sourceSchema.safeParse(value)
  return parsed.success ? parsed.data : undefined
}

/** The senders a label names, and how many more it counts; one notice can carry many. */
export function agentMessageSendersShown(
  source: AgentMessageSource,
  limit = 3
): { shown: readonly AgentMessageSender[]; more: number } {
  return {
    shown: source.senders.slice(0, limit),
    more: Math.max(0, source.senders.length - limit)
  }
}

src/shared/agent-session-orca-stop.ts.source:
// Why the Orca running a chat stopped in the middle of a reply: a quit, an update, or a crash. The
// host states it on its row about the cut turn (`orcaStop`); a client names it, and offers Continue.
// Open on the wire: a cause this build does not know reads as none, and the row keeps its words.

export const AGENT_SESSION_ORCA_STOP_CAUSES = ['update', 'quit', 'crash'] as const
/** The row's presentation, so a client that re-words host rows it can't name passes it through. */
export const AGENT_SESSION_ORCA_STOP_PRESENTATION = 'orca-stop'
export type AgentSessionOrcaStopCause = (typeof AGENT_SESSION_ORCA_STOP_CAUSES)[number]
export type AgentSessionOrcaStop = { cause: AgentSessionOrcaStopCause }

export function isAgentSessionOrcaStopCause(value: unknown): value is AgentSessionOrcaStopCause {
  return AGENT_SESSION_ORCA_STOP_CAUSES.some((cause) => cause === value)
}

/** The stop a row states, when this build knows its cause. */
export function readAgentSessionOrcaStop(value: unknown): AgentSessionOrcaStop | undefined {
  const cause =
    typeof value === 'object' && value !== null && 'cause' in value ? value.cause : undefined
  return isAgentSessionOrcaStopCause(cause) ? { cause } : undefined
}

src/shared/agent-session-provider-contex.source:
import type { AgentSessionRecord } from './agent-session-record'

export type AgentSessionProviderContextBoundary = {
  operationId: string
  afterFence: number
  clearedAt: number
}

export function isAgentSessionProviderContextBoundary(
  value: unknown
): value is AgentSessionProviderContextBoundary {
  return (
    typeof value === 'object' &&
    value !== null &&
    'operationId' in value &&
    typeof value.operationId === 'string' &&
    value.operationId.length > 0 &&
    value.operationId.length <= 512 &&
    'afterFence' in value &&
    typeof value.afterFence === 'number' &&
    Number.isSafeInteger(value.afterFence) &&
    value.afterFence >= 0 &&
    'clearedAt' in value &&
    typeof value.clearedAt === 'number' &&
    Number.isSafeInteger(value.clearedAt) &&
    value.clearedAt >= 0
  )
}

/** Clear resets the chain; the boundary identifies a fresh launch before its first proof. */
export function activeProviderContext(
  record: Pick<AgentSessionRecord, 'providerHandleChain' | 'providerContextBoundary'>
) {
  const handleChain = record.providerHandleChain
  const head = handleChain.at(-1) ?? null
  return {
    handleChain,
    head,
    pendingClear: record.providerContextBoundary !== undefined && head === null
  }
}

src/shared/agent-session-provider-handle.source:
/**
 * How a provider handle is stored and sent, and the only module that knows the two typed shapes
 * the first structured transports were stored in.
 *
 * Claude and Codex handles are persisted and sent exactly as before this module existed, so an
 * older build sharing the database or the wire still reads them. Every other transport is stored
 * in the neutral shape, which an older build refuses as unreadable rather than mistaking for one
 * of its own. Decoding is strict: each handle has exactly one stored form, and the key and root
 * strings derived from it are persisted elsewhere, so none of them may ever change.
 *
 * A stored handle has a closed field set, and a rewrite drops anything else. A later build adds new
 * per-link data on the chain link, which every build preserves, never on the handle.
 */

import type {
  AgentSessionProviderHandle,
  AgentSessionProviderHandleNamespace
} from './agent-session-provider-handle'
import type {
  AgentSessionJournalIdentity,
  AgentSessionJournalProviderHandle
} from './agent-session-journal-types'

export const CLAUDE_STRUCTURED_HANDLE_NAMESPACE = {
  transport: 'claude-sdk',
  agent: 'claude'
} as const satisfies AgentSessionProviderHandleNamespace

export const CODEX_STRUCTURED_HANDLE_NAMESPACE = {
  transport: 'codex-app-server',
  agent: 'codex'
} as const satisfies AgentSessionProviderHandleNamespace

/** The typed lanes' namespaces: their handles can only ever be stored in these. */
function builtInHandleNamespace(agent: string): AgentSessionProviderHandleNamespace | null {
  return agent === CLAUDE_STRUCTURED_HANDLE_NAMESPACE.agent
    ? CLAUDE_STRUCTURED_HANDLE_NAMESPACE
    : agent === CODEX_STRUCTURED_HANDLE_NAMESPACE.agent
      ? CODEX_STRUCTURED_HANDLE_NAMESPACE
      : null
}

export function isAgentSessionProviderHandleInNamespace(
  handle: AgentSessionProviderHandleNamespace,
  namespace: AgentSessionProviderHandleNamespace
): boolean {
  return handle.transport === namespace.transport && handle.agent === namespace.agent
}

/**
 * Whether a handle belongs to a record of this agent. Compares namespaces; never reads its data.
 * Claude and Codex handles are pinned to their typed lane's transport. Another agent's handle may be
 * in any transport: the record store asks only that a chain keep one namespace owned by the
 * record's agent, and whether this build speaks that transport is asked when the agent would start
 * (`agentDrivesSession`).
 */
export function agentSessionProviderHandleBelongsTo(
  handle: AgentSessionProviderHandle,
  agent: string
): boolean {
  const builtIn = builtInHandleNamespace(agent)
  return builtIn ? isAgentSessionProviderHandleInNamespace(handle, builtIn) : handle.agent === agent
}

/** Claude's resume cursor is its leaf: the transcript entry a resume continues from. */
export function claudeProviderHandle(
  sessionId: string,
  leafUuid: string | null
): AgentSessionProviderHandle {
  return {
    ...CLAUDE_STRUCTURED_HANDLE_NAMESPACE,
    nativeId: sessionId,
    ...(leafUuid === null ? {} : { resumeCursor: leafUuid })
  }
}

export function claudeProviderHandleLeafUuid(handle: AgentSessionProviderHandle): string | null {
  return handle.resumeCursor ?? null
}

export function codexProviderHandle(threadId: string): AgentSessionProviderHandle {
  return { ...CODEX_STRUCTURED_HANDLE_NAMESPACE, nativeId: threadId }
}

// ─── Validation ─────────────────────────────────────────────────────────────

const MAX_HANDLE_FIELD_LENGTH = 512
/** A generic handle's key carries escaped ids, so it may outgrow a legacy key's bound. */
const MAX_NEUTRAL_HANDLE_KEY_LENGTH = 8192
const MAX_RESUME_CURSOR_LENGTH = 4096
const NAMESPACE_PART_PATTERN = /^[A-Za-z][A-Za-z0-9_-]{0,63}$/

export function isAgentSessionProviderHandleField(value: unknown): value is string {
  return (
    typeof value === 'string' &&
    value.length > 0 &&
    value.length <= MAX_HANDLE_FIELD_LENGTH &&
    value === value.trim()
  )
}

function isNamespacePart(value: unknown): value is string {
  return typeof value === 'string' && NAMESPACE_PART_PATTERN.test(value)
}

/** An agent id a host may register: the same bounded slug a handle's agent is. Whether a host runs
 *  it is that host's registry's answer, not this check's. */
export function isStructuredAgentId(value: unknown): value is string {
  return isNamespacePart(value)
}

function isLegacyNamespace(handle: AgentSessionProviderHandleNamespace): boolean {
  return (
    isAgentSessionProviderHandleInNamespace(handle, CLAUDE_STRUCTURED_HANDLE_NAMESPACE) ||
    isAgentSessionProviderHandleInNamespace(handle, CODEX_STRUCTURED_HANDLE_NAMESPACE)
  )
}

/** Whether builds before the neutral handle read a record of this namespace at all. */
export function isAgentSessionProviderHandleReadByOlderBuilds(
  handle: AgentSessionProviderHandleNamespace
): boolean {
  return isLegacyNamespace(handle)
}

/**
 * An in-memory handle. A Claude or Codex handle must also fit its typed stored shape: Claude's
 * resume cursor is a leaf id, and Codex has none.
 */
export function isAgentSessionProviderHandle(value: unknown): value is AgentSessionProviderHandle {
  if (typeof value !== 'object' || value === null || Object.hasOwn(value, 'provider')) {
    return false
  }
  const transport = 'transport' in value ? value.transport : undefined
  const agent = 'agent' in value ? value.agent : undefined
  const nativeId = 'nativeId' in value ? value.nativeId : undefined
  const resumeCursor = 'resumeCursor' in value ? value.resumeCursor : undefined
  if (
    !isNamespacePart(transport) ||
    !isNamespacePart(agent) ||
    !isAgentSessionProviderHandleField(nativeId)
  ) {
    return false
  }
  const namespace = { transport, agent }
  if (isAgentSessionProviderHandleInNamespace(namespace, CODEX_STRUCTURED_HANDLE_NAMESPACE)) {
    return resumeCursor === undefined
  }
  if (isAgentSessionProviderHandleInNamespace(namespace, CLAUDE_STRUCTURED_HANDLE_NAMESPACE)) {
    return resumeCursor === undefined || isAgentSessionProviderHandleField(resumeCursor)
  }
  return (
    resumeCursor === undefined ||
    (typeof resumeCursor === 'string' &&
      resumeCursor.length > 0 &&
      resumeCursor.length <= MAX_RESUME_CURSOR_LENGTH)
  )
}

/** Bound for a persisted key that names a handle in this namespace (`forkedFromKey`, `supersedesKey`). */
export function isAgentSessionProviderHandleKeyFor(
  handle: AgentSessionProviderHandle,
  value: unknown
): value is string {
  return isLegacyNamespace(handle)
    ? isAgentSessionProviderHandleField(value)
    : typeof value === 'string' && value.length > 0 && value.length <= MAX_NEUTRAL_HANDLE_KEY_LENGTH
}

// ─── Stored form ────────────────────────────────────────────────────────────

type StoredClaudeProviderHandle = { provider: 'claude'; sessionId: string; leafUuid: string | null }
type StoredCodexProviderHandle = { provider: 'codex'; threadId: string }

/** A handle as a record row stores it. */
export type PersistedAgentSessionProviderHandle =
  | StoredClaudeProviderHandle
  | StoredCodexProviderHandle
  | AgentSessionProviderHandle

export function encodePersistedAgentSessionProviderHandle(
  handle: AgentSessionProviderHandle
): PersistedAgentSessionProviderHandle {
  if (isAgentSessionProviderHandleInNamespace(handle, CLAUDE_STRUCTURED_HANDLE_NAMESPACE)) {
    return { provider: 'claude', sessionId: handle.nativeId, leafUuid: handle.resumeCursor ?? null }
  }
  if (isAgentSessionProviderHandleInNamespace(handle, CODEX_STRUCTURED_HANDLE_NAMESPACE)) {
    return { provider: 'codex', threadId: handle.nativeId }
  }
  return {
    transport: handle.transport,
    agent: handle.agent,
    nativeId: handle.nativeId,
    ...(handle.resumeCursor === undefined ? {} : { resumeCursor: handle.resumeCursor })
  }
}

/** The neutral form's discriminator and identity fields; a typed stored handle carries none of them. */
const NEUTRAL_HANDLE_FIELDS = ['transport', 'agent', 'nativeId', 'resumeCursor'] as const

export function decodePersistedAgentSessionProviderHandle(
  value: unknown
): AgentSessionProviderHandle | null {
  if (typeof value !== 'object' || value === null) {
    return null
  }
  // Why: a row in both forms names two identities; reading it as either would erase the other on
  // the next write, so it stays unreadable.
  if (
    Object.hasOwn(value, 'provider') &&
    NEUTRAL_HANDLE_FIELDS.some((field) => Object.hasOwn(value, field))
  ) {
    return null
  }
  const provider = 'provider' in value ? value.provider : undefined
  if (provider === 'claude') {
    const sessionId = 'sessionId' in value ? value.sessionId : undefined
    // Why: a null leaf and a missing one were never the same stored value; keep refusing the second.
    const leafUuid = 'leafUuid' in value ? value.leafUuid : undefined
    return isAgentSessionProviderHandleField(sessionId) &&
      (leafUuid === null || isAgentSessionProviderHandleField(leafUuid))
      ? claudeProviderHandle(sessionId, leafUuid)
      : null
  }
  if (provider === 'codex') {
    const threadId = 'threadId' in value ? value.threadId : undefined
    return isAgentSessionProviderHandleField(threadId) ? codexProviderHandle(threadId) : null
  }
  // A Claude or Codex handle has exactly one stored form, the typed one.
  if (!isAgentSessionProviderHandle(value) || isLegacyNamespace(value)) {
    return null
  }
  return {
    transport: value.transport,
    agent: value.agent,
    nativeId: value.nativeId,
    ...(value.resumeCursor === undefined ? {} : { resumeCursor: value.resumeCursor })
  }
}

// ─── Identity strings (persisted: never change them) ────────────────────────

/** Stable string identity for one handle. Two handles with the same key name the same writer target. */
export function agentSessionProviderHandleKey(handle: AgentSessionProviderHandle): string {
  const stored = encodePersistedAgentSessionProviderHandle(handle)
  if ('provider' in stored) {
    return stored.provider === 'claude'
      ? `claude:${JSON.stringify([stored.sessionId, stored.leafUuid])}`
      : `codex:${JSON.stringify(stored.threadId)}`
  }
  // Why: the resume cursor is resume state the adapter owns, not identity; only Claude's leaf, a
  // branch cursor, was ever part of a key, and its key above is fixed by records already written.
  return agentSessionProviderHandleRoot(handle)
}

/**
 * Identity root: the part that a resume must preserve. A resume that changes the root is a fork,
 * whatever the provider called it.
 */
export function agentSessionProviderHandleRoot(handle: AgentSessionProviderHandle): string {
  const stored = encodePersistedAgentSessionProviderHandle(handle)
  if ('provider' in stored) {
    return stored.provider === 'claude'
      ? `claude:${JSON.stringify(stored.sessionId)}`
      : `codex:${JSON.stringify(stored.threadId)}`
  }
  // Namespace parts cannot hold `/` or `:`, so this never reads as a typed root.
  return `${handle.transport}/${handle.agent}:${JSON.stringify(handle.nativeId)}`
}

// ─── Wire and journal forms ─────────────────────────────────────────────────

/** A handle as `agentSession.attach` carries it and an attach fingerprint covers it. */
export type AgentSessionWireProviderHandle = Exclude<
  AgentSessionJournalProviderHandle,
  { kind: 'opaque' }
>

export function agentSessionProviderHandleFromWire(
  wire: AgentSessionWireProviderHandle
): AgentSessionProviderHandle {
  return wire.kind === 'claude'
    ? claudeProviderHandle(wire.sessionId, wire.leafUuid)
    : codexProviderHandle(wire.threadId)
}

/** Null for a transport the attach wire cannot carry. */
export function agentSessionWireProviderHandle(
  handle: AgentSessionProviderHandle
): AgentSessionWireProviderHandle | null {
  const stored = encodePersistedAgentSessionProviderHandle(handle)
  if (!('provider' in stored)) {
    return null
  }
  return stored.provider === 'claude'
    ? { kind: 'claude', sessionId: stored.sessionId, leafUuid: stored.leafUuid }
    : { kind: 'codex', threadId: stored.threadId }
}

/** What a journal row records before the provider has proved any handle. */
export const AGENT_SESSION_PENDING_PROVIDER_HANDLE_VALUE = 'pending'

/** The handle a journal row records for this identity. Write-only: rows keep it for diagnosis,
 *  nothing reads it. */
export function agentSessionJournalProviderHandle(
  identity: Pick<AgentSessionJournalIdentity, 'agent' | 'providerHandle'>
): AgentSessionJournalProviderHandle {
  const handle = identity.providerHandle
  if (!handle) {
    return {
      kind: 'opaque',
      agent: identity.agent,
      value: AGENT_SESSION_PENDING_PROVIDER_HANDLE_VALUE
    }
  }
  return (
    agentSessionWireProviderHandle(handle) ?? {
      kind: 'opaque',
      agent: handle.agent,
      value: handle.nativeId
    }
  )
}

/**
 * What a chain link records when the provider could not restore a chat's saved conversation and a
 * fresh one took over.
 */

import type { AgentSessionProviderHandle } from './agent-session-provider-handle'
import {
  isAgentSessionProviderHandleKeyFor,
  isAgentSessionProviderHandleReadByOlderBuilds
} from './agent-session-provider-handle-encoding'

const MAX_REPLACEMENT_REASON_LENGTH = 64

/**
 * Why a chat's agent no longer remembers what came before this link: the provider could not
 * restore the conversation the chat had, so a fresh one continues it without that history.
 */
export type AgentSessionProviderHandleReplacement = {
  /** Key of the conversation that was lost: the head this creation followed. */
  key: string
  /** Open: a later build may record a reason this one does not name, and it must stay readable. */
  reason: 'restore-failed' | (string & {})
  /** When the replacement was made; a link's `observedAt` moves with its resume point. */
  replacedAt: number
}

export function isAgentSessionProviderHandleReplacement(
  handle: AgentSessionProviderHandle,
  value: unknown
): value is AgentSessionProviderHandleReplacement {
  if (
    typeof value !== 'object' ||
    value === null ||
    !('key' in value) ||
    !('reason' in value) ||
    !('replacedAt' in value)
  ) {
    return false
  }
  const { key, reason, replacedAt } = value
  return (
    // Why: older builds read Claude and Codex rows and refuse a creation anywhere but first in a
    // chain, so a replacement there would set the whole chat aside after a downgrade. Every other
    // agent's row is one they never read. A Claude or Codex fallback must first pick a stored shape.
    !isAgentSessionProviderHandleReadByOlderBuilds(handle) &&
    isAgentSessionProviderHandleKeyFor(handle, key) &&
    typeof reason === 'string' &&
    reason.length > 0 &&
    reason.length <= MAX_REPLACEMENT_REASON_LENGTH &&
    typeof replacedAt === 'number' &&
    Number.isSafeInteger(replacedAt) &&
    replacedAt >= 0
  )
}

export function agentSessionProviderHandleReplacementsEqual(
  left: AgentSessionProviderHandleReplacement | undefined,
  right: AgentSessionProviderHandleReplacement | undefined
): boolean {
  return (
    left === right ||
    (left !== undefined &&
      right !== undefined &&
      left.key === right.key &&
      left.reason === right.reason &&
      left.replacedAt === right.replacedAt)
  )
}

/**
 * Durable provider handle chain for an agent session.
 *
 * A handle names one provider conversation without saying what the provider means by it. Shared
 * code reads only its transport, its agent, and the provider's own conversation id; anything else
 * the provider needs to resume is `resumeCursor`, which only that provider's adapter reads. How a
 * handle is stored and sent lives in agent-session-provider-handle-encoding.ts.
 *
 * Resumes extend the chain, forks start a new identity root, and the chain records which is which
 * so a fork is never presented as a resume. A creation the provider never saved can be superseded
 * by a new creation, which takes its place instead of standing beside it: the unsaved handle was
 * never a conversation to continue. A saved conversation the provider could not restore is instead
 * replaced: a new creation follows it and names it, so the chain still says what the agent forgot
 * and when.
 */

import type { AgentType } from './agent-status-types'
import {
  agentSessionProviderHandleReplacementsEqual,
  isAgentSessionProviderHandleReplacement,
  type AgentSessionProviderHandleReplacement
} from './agent-session-provider-handle-replacement'
import {
  agentSessionProviderHandleKey,
  agentSessionProviderHandleRoot,
  decodePersistedAgentSessionProviderHandle,
  encodePersistedAgentSessionProviderHandle,
  isAgentSessionProviderHandle,
  isAgentSessionProviderHandleInNamespace,
  isAgentSessionProviderHandleKeyFor,
  type PersistedAgentSessionProviderHandle
} from './agent-session-provider-handle-encoding'

export type { AgentSessionProviderHandleReplacement } from './agent-session-provider-handle-replacement'
export {
  agentSessionProviderHandleKey,
  agentSessionProviderHandleRoot,
  isAgentSessionProviderHandle,
  isStructuredAgentId
} from './agent-session-provider-handle-encoding'

/**
 * The structured agents every build ships. They are not the whole set: a host may register more,
 * advertises that it does with the registered-agents capability, and lists them through
 * `agentSession.agents`. A client that has not learned a host's list knows only these.
 */
export const AGENT_SESSION_PROVIDER_HANDLE_PROVIDERS = ['claude', 'codex'] as const

export type AgentSessionHandleProvider = (typeof AGENT_SESSION_PROVIDER_HANDLE_PROVIDERS)[number]

/** A structured agent a host registered: one of the built-ins or any agent id the host lists.
 *  Checked as a slug by `isStructuredAgentId`; whether a host runs it is its registry's answer. */
export type StructuredAgentId = string

/** Whether an agent is one of the two built-ins, for features only they have. It does NOT answer
 *  whether an agent has a structured chat: that is `isStructuredAgentId` plus the host's registry. */
export function isAgentSessionHandleProvider(value: unknown): value is AgentSessionHandleProvider {
  return value === 'claude' || value === 'codex'
}

/** The protocol whose id space a handle's `nativeId` lives in. Open: a new transport adds no arm. */
export type AgentSessionProviderTransport = 'claude-sdk' | 'codex-app-server' | (string & {})

export type AgentSessionProviderHandle = {
  /**
   * The id space `nativeId` was minted in, which can differ from the agent's current transport. A
   * mismatch with the running build makes the chat not resumable there, never the record unreadable.
   */
  transport: AgentSessionProviderTransport
  /** Orca agent whose binary resumes the conversation; one transport serves many agents. */
  agent: AgentType
  /** The provider's own conversation id: Claude's session id, Codex's thread id. */
  nativeId: string
  /**
   * Adapter-owned resume position (Claude: transcript leaf). Shared code never parses it; it is never
   * identity, except inside Claude's legacy handle key.
   */
  resumeCursor?: string
}

/** Which provider a handle belongs to. Records and leases compare this, never the handle's data. */
export type AgentSessionProviderHandleNamespace = Pick<
  AgentSessionProviderHandle,
  'transport' | 'agent'
>

export type AgentSessionProviderHandleOrigin = 'created' | 'adopted' | 'resumed' | 'forked'

export type AgentSessionProviderHandleLink = {
  /** Stable id so a lease can name the exact link its owner proved. */
  linkId: string
  handle: AgentSessionProviderHandle
  origin: AgentSessionProviderHandleOrigin
  /** Runtime fence in force when this link was minted; never decreases along the chain. */
  mintedAtFence: number
  observedAt: number
  /** Key of the link a fork was seeded from. Only set when `origin` is `forked`. */
  forkedFromKey?: string
  /** Key of the unsaved creation this creation replaced. Only set when `origin` is `created`. */
  supersedesKey?: string
  /** The saved conversation this creation took over from. Only set when `origin` is `created`. */
  replaces?: AgentSessionProviderHandleReplacement
}

export type AgentSessionProviderHandleChain = readonly AgentSessionProviderHandleLink[]

/** Bounded so one session cannot grow an unbounded persisted record. */
export const MAX_AGENT_SESSION_PROVIDER_HANDLE_LINKS = 256

const LINK_ID_PATTERN = /^[A-Za-z0-9_-]{1,128}$/

/** Every field, resume cursor included: a resume that only moved the adapter's state is still news. */
export function agentSessionProviderHandlesEqual(
  left: AgentSessionProviderHandle,
  right: AgentSessionProviderHandle
): boolean {
  return (
    left.transport === right.transport &&
    left.agent === right.agent &&
    left.nativeId === right.nativeId &&
    left.resumeCursor === right.resumeCursor
  )
}

export function agentSessionProviderHandleChainHead(
  chain: AgentSessionProviderHandleChain
): AgentSessionProviderHandleLink | null {
  return chain.at(-1) ?? null
}

export function findAgentSessionProviderHandleLink(
  chain: AgentSessionProviderHandleChain,
  linkId: string
): AgentSessionProviderHandleLink | null {
  return chain.find((link) => link.linkId === linkId) ?? null
}

export function isAgentSessionProviderHandleLink(
  value: unknown
): value is AgentSessionProviderHandleLink {
  if (typeof value !== 'object' || value === null) {
    return false
  }
  const link = value as Partial<AgentSessionProviderHandleLink>
  if (!isAgentSessionProviderHandle(link.handle)) {
    return false
  }
  const handle = link.handle
  const originValid =
    link.origin === 'created' ||
    link.origin === 'adopted' ||
    link.origin === 'resumed' ||
    link.origin === 'forked'
  return (
    typeof link.linkId === 'string' &&
    LINK_ID_PATTERN.test(link.linkId) &&
    originValid &&
    Number.isSafeInteger(link.mintedAtFence) &&
    (link.mintedAtFence as number) >= 0 &&
    Number.isSafeInteger(link.observedAt) &&
    (link.origin === 'forked'
      ? isAgentSessionProviderHandleKeyFor(handle, link.forkedFromKey)
      : link.forkedFromKey === undefined) &&
    (link.supersedesKey === undefined ||
      (link.origin === 'created' &&
        isAgentSessionProviderHandleKeyFor(handle, link.supersedesKey))) &&
    (link.replaces === undefined ||
      (link.origin === 'created' && isAgentSessionProviderHandleReplacement(handle, link.replaces)))
  )
}

export function isAgentSessionProviderHandleChain(
  value: unknown
): value is AgentSessionProviderHandleLink[] {
  if (!Array.isArray(value) || value.length > MAX_AGENT_SESSION_PROVIDER_HANDLE_LINKS) {
    return false
  }
  let validated: AgentSessionProviderHandleLink[] = []
  try {
    for (const link of value) {
      if (!isAgentSessionProviderHandleLink(link)) {
        return false
      }
      const next = appendLink(validated, link, true)
      // A persisted chain must name every link exactly once; retry elision belongs at append time.
      if (next.length !== validated.length + 1) {
        return false
      }
      validated = next
    }
    return true
  } catch {
    return false
  }
}

/**
 * Append one link, rejecting anything that would let a fork masquerade as a resume or let a
 * late writer rewrite the chain under an older fence.
 */
export function appendAgentSessionProviderHandleLink(
  chain: AgentSessionProviderHandleChain,
  link: AgentSessionProviderHandleLink
): AgentSessionProviderHandleLink[] {
  return appendLink(chain, link, false)
}

/** `supersededHead`: the replacement already took the place of a creation no longer in `chain`. */
function appendLink(
  chain: AgentSessionProviderHandleChain,
  link: AgentSessionProviderHandleLink,
  supersededHead: boolean
): AgentSessionProviderHandleLink[] {
  if (!isAgentSessionProviderHandleLink(link)) {
    throw new Error('agent_session_provider_handle_invalid')
  }
  const head = agentSessionProviderHandleChainHead(chain)
  if (!head) {
    // A replacement names the conversation before it, so it can never open a chain.
    if ((link.origin !== 'created' && link.origin !== 'adopted') || link.replaces !== undefined) {
      throw new Error('agent_session_provider_handle_invalid')
    }
    return [link]
  }
  if (!isAgentSessionProviderHandleInNamespace(link.handle, head.handle)) {
    throw new Error('agent_session_provider_handle_provider_mismatch')
  }
  if (link.mintedAtFence < head.mintedAtFence) {
    throw new Error('agent_session_provider_handle_stale_fence')
  }
  const sameRoot =
    agentSessionProviderHandleRoot(link.handle) === agentSessionProviderHandleRoot(head.handle)
  if (link.origin === 'created') {
    if (link.supersedesKey !== undefined && !supersededHead) {
      return supersedeUnsavedCreation(chain, head, link)
    }
    if (
      link.replaces === undefined ||
      link.replaces.key !== agentSessionProviderHandleKey(head.handle) ||
      sameRoot
    ) {
      throw new Error('agent_session_provider_handle_invalid')
    }
    return appendNewLink(chain, link)
  }
  if (link.origin === 'adopted') {
    throw new Error('agent_session_provider_handle_invalid')
  }
  if (link.origin === 'resumed' && !sameRoot) {
    // Why: a resume that lands on another identity root forked; recording it as a resume would
    // make Orca claim continuity the provider never gave.
    throw new Error('agent_session_provider_handle_forked')
  }
  if (link.origin === 'forked') {
    if (sameRoot) {
      throw new Error('agent_session_provider_handle_invalid')
    }
    if (link.forkedFromKey !== agentSessionProviderHandleKey(head.handle)) {
      throw new Error('agent_session_provider_handle_invalid')
    }
  }
  if (
    link.origin === 'resumed' &&
    agentSessionProviderHandlesEqual(link.handle, head.handle) &&
    link.mintedAtFence === head.mintedAtFence
  ) {
    // Why: re-proving the same handle at the same fence is a retry, not a new identity.
    return [...chain]
  }
  return appendNewLink(chain, link)
}

function appendNewLink(
  chain: AgentSessionProviderHandleChain,
  link: AgentSessionProviderHandleLink
): AgentSessionProviderHandleLink[] {
  if (findAgentSessionProviderHandleLink(chain, link.linkId)) {
    // Why: the lease names its exact proof by link id; reuse would make that reference ambiguous.
    throw new Error('agent_session_provider_handle_invalid')
  }
  if (chain.length >= MAX_AGENT_SESSION_PROVIDER_HANDLE_LINKS) {
    // Why: dropping older links would erase fork provenance, so refuse and let the caller roll
    // the journal epoch instead of silently losing where this conversation came from.
    throw new Error('agent_session_provider_handle_chain_overflow')
  }
  return [...chain, link]
}

/**
 * Replace the head, a creation the provider proved it never saved, with the creation that took its
 * place. Every other head names a conversation the provider held (a resume or fork proved it, an
 * adoption imported it), so only a `created` head can be superseded, and only by a new identity
 * root that names it. A superseded replacement passes on what it replaced: the conversation that
 * was lost is still lost.
 */
function supersedeUnsavedCreation(
  chain: AgentSessionProviderHandleChain,
  head: AgentSessionProviderHandleLink,
  link: AgentSessionProviderHandleLink
): AgentSessionProviderHandleLink[] {
  const earlier = chain.slice(0, -1)
  if (
    head.origin !== 'created' ||
    link.supersedesKey !== agentSessionProviderHandleKey(head.handle) ||
    agentSessionProviderHandleRoot(link.handle) === agentSessionProviderHandleRoot(head.handle) ||
    (link.replaces !== undefined &&
      !agentSessionProviderHandleReplacementsEqual(link.replaces, head.replaces)) ||
    link.linkId === head.linkId
  ) {
    throw new Error('agent_session_provider_handle_invalid')
  }
  const next = head.replaces ? { ...link, replaces: head.replaces } : link
  // Why: in place, so a chat reopened unused across many restarts never grows toward the cap.
  return earlier.length === 0 ? [next] : appendLink(earlier, next, true)
}

// ─── Stored form ────────────────────────────────────────────────────────────

/** A link as a record row stores it: only the handle has a stored form of its own. */
export type PersistedAgentSessionProviderHandleLink = Omit<
  AgentSessionProviderHandleLink,
  'handle'
> & {
  handle: PersistedAgentSessionProviderHandle
}

export function encodePersistedAgentSessionProviderHandleChain(
  chain: AgentSessionProviderHandleChain
): PersistedAgentSessionProviderHandleLink[] {
  return chain.map((link) => ({
    ...link,
    handle: encodePersistedAgentSessionProviderHandle(link.handle)
  }))
}

/** The in-memory chain a stored one names, or null when any link or the chain itself is invalid. */
export function decodePersistedAgentSessionProviderHandleChain(
  value: unknown
): AgentSessionProviderHandleLink[] | null {
  if (!Array.isArray(value) || value.length > MAX_AGENT_SESSION_PROVIDER_HANDLE_LINKS) {
    return null
  }
  const decoded: unknown[] = []
  for (const link of value) {
    const handle =
      typeof link === 'object' && link !== null && 'handle' in link
        ? decodePersistedAgentSessionProviderHandle(link.handle)
        : null
    if (!handle) {
      return null
    }
    decoded.push({ ...link, handle })
  }
  return isAgentSessionProviderHandleChain(decoded) ? decoded : null
}

