// The queued-message part of the agent-session wire: the published draft cards,
// the queue's pause beside them, and the draft mutations' answers.

import type { UnreadAgentSessionFailureFact } from './agent-session-failure'
import type { AgentJournalMessageItem } from './agent-session-journal-types'

/** The draft could not be converted into a send; an explicit Send retries it. */
export const QUEUED_MESSAGE_PAUSED_SEND_FAILED = 'send_failed' as const

export type AgentSessionQueuedMessagePausedReason = typeof QUEUED_MESSAGE_PAUSED_SEND_FAILED

/** The whole queue is paused and sends nothing on its own: 'stopped' — the user interrupted
 *  ("Queue paused because you interrupted"). Resume (`agentSession.queuedMessagesResume`), or any
 *  turn starting, lifts it; Send-now on one card sends that card and leaves the rest paused until
 *  its turn starts. A /clear or a reopen also holds cards until the chat's next turn, but nothing
 *  runs then, so neither is published. A client treats an unknown reason as a plain pause, so a
 *  newer host can add one. */
export type AgentSessionQueuePause = { reason: 'stopped' }

/** What rides beside a frame's `queuedMessages`, published together with the list. */
export type AgentSessionQueuePublicationFields = {
  /** Null when the queue sends on its own. */
  queuePause?: AgentSessionQueuePause | null
  /** The card the queue sends next once nothing runs, null while anything holds the queue.
   *  Absent from an older host, read as null. */
  nextQueuedMessageId?: string | null
}

export type AgentSessionQueuedMessagesResumeResult = {
  /** False when nothing was paused, and on a replay of an already-run Resume. */
  resumed: boolean
}

/** One draft the host holds for this conversation, published whole-list on the
 *  subscribe stream and on history pages. Text-only v1. */
export type AgentSessionQueuedMessage = {
  messageId: string
  position: number
  body: AgentJournalMessageItem
  state: 'waiting' | 'returned'
  /** This one card is held, whatever the queue's pause: its conversion failed. */
  paused?: true
  /** Why it is held, as a marker the client localizes: 'send_failed' ("couldn't send"); only an
   *  explicit Send releases it. A client must treat an unknown marker as a plain hold, so a newer
   *  host can add one. The queue-level pause is `queuePause`, published beside the list. */
  pausedReason?: AgentSessionQueuedMessagePausedReason
  /** A returned card's refusal: the `reason` and `rejection` pair its submission settled with.
   *  Only a failure returns a card; a draft a Stop or restart took back waits again. Clients classify it from `returnedRejection` (falling back to `returnedReason` when a host
   *  wrote no fact) exactly as they classify a rejected submission's `rejection`, e.g.
   *  `classifyDispatchRejection({ reason: returnedReason, rejection: returnedRejection })`. */
  returnedReason?: string | null
  returnedRejection?: UnreadAgentSessionFailureFact
}

/** No body: the card leaving the published list IS the outcome, so a lost
 *  answer needs no re-ask and no text ever rides the wire back. */
export type AgentSessionQueuedMessageDeleteResult =
  | { deleted: true; messageId: string }
  /** `dispatched` means it already became a submission; `missing` covers a
   *  pruned tombstone. Replays answer from tombstone receipts. */
  | { deleted: false; messageId: string; disposition: 'dispatched' | 'withdrawn' | 'missing' }

/** `agentSession.queuedMessageUpdate` (`agent-session.queued-message-edit.v1`). `unchanged`: the
 *  card already reads as asked, which is also how a resent Save whose answer was lost succeeds.
 *  `changed`: someone else's edit landed first; nothing was overwritten. */
export type AgentSessionQueuedMessageUpdateResult =
  | { status: 'updated' | 'unchanged'; messageId: string; fingerprint: string }
  | { status: 'changed' | 'not-editable'; messageId: string }
  | { status: 'gone'; messageId: string; disposition: 'dispatched' | 'withdrawn' | 'missing' }

/** `agentSession.queuedMessageEditHold`: one editor's lease, keyed by the authenticated caller and
 *  `editId`. It expires on its own; renewing extends it, and release frees only this editor's. */
export type AgentSessionQueuedMessageEditHoldParams = {
  sessionId: string
  messageId: string
  editId: string
} & ({ action: 'acquire'; expectedBodyFingerprint: string } | { action: 'renew' | 'release' })

export type AgentSessionQueuedMessageEditHoldResult =
  | { status: 'held'; fingerprint: string; leaseDurationMs: number; remainingMs: number }
  | { status: 'released' | 'expired' | 'changed' | 'gone' | 'not-editable' }

src/shared/agent-session-queued-submissi.source:
import type { AgentJournalSubmission } from './agent-session-journal-types'

/** Accepted by the host and not yet handed to the provider: provably unwritten, so every way out
 *  of this state is delivery or a rejection, never doubt. */
export function isQueuedAgentJournalSubmission(
  submission: Pick<AgentJournalSubmission, 'handoverRecorded' | 'dispatchState' | 'handedOverAt'>
): boolean {
  return (
    submission.handoverRecorded === true &&
    submission.dispatchState === 'pending' &&
    submission.handedOverAt === undefined
  )
}

src/shared/agent-session-record.ts.source:
import { isAgentSessionRewindRecord, type AgentSessionRewindRecord } from './agent-session-rewind'
import { isAgentSessionLaunchArgs } from './agent-session-launch-args'
import { isAgentSessionConversationName } from './agent-session-conversation-name'
import {
  isPersistedAgentSessionHandoffStage,
  isPersistedAgentSessionRuntimeKind,
  type PersistedAgentSessionLease,
  type PersistedAgentSessionRecord
} from './agent-session-legacy-handoff-lease'
/**
 * Durable agent-session record and its single-writer lease.
 *
 * The record is the session's identity — where it runs, which provider it talks to, which account
 * home is pinned to it — and is independent of any terminal tab. The lease is the separate
 * question of which process is currently allowed to write to it.
 */

import type { ExecutionHostId } from './execution-host'
import {
  isAgentSessionConversationCommandRecord,
  type AgentSessionConversationCommandRecord
} from './agent-session-conversation-command'
import {
  decodePersistedAgentSessionProviderHandleChain,
  type AgentSessionProviderHandleLink
} from './agent-session-provider-handle'
import {
  isAgentSessionProviderContextBoundary,
  type AgentSessionProviderContextBoundary
} from './agent-session-provider-context'
import { isStructuredAgentId } from './agent-session-provider-handle-encoding'
import {
  isAgentSessionAccountHome,
  MAX_PATH_LENGTH,
  type AgentSessionAccountHome
} from './agent-session-account-home'

export type { AgentSessionAccountHome } from './agent-session-account-home'

export const AGENT_SESSION_RECORD_SCHEMA_VERSION = 2 as const

export type AgentSessionWorkspaceKind = 'git-worktree' | 'folder'

/**
 * Where the provider process actually runs. WSL is called out separately from the execution host
 * id because a WSL workspace is served by the local host but is a distinct filesystem, account
 * root, and process namespace — two sessions there must never collide with their native twins.
 */
export type AgentSessionExecutionLocation = {
  executionHostId: ExecutionHostId
  /** Distro name when the provider runs inside WSL; null for native and remote hosts. */
  wslDistro: string | null
  workspaceId: string
  workspaceKind: AgentSessionWorkspaceKind
}

/** Provider launch environment captured by the host when the session is created. */
export type AgentSessionLaunchEnv = Record<string, string>

/** Provider CLI arguments captured by the host when the session is created. */
export type AgentSessionLaunchArgs = string[]

/** Still persisted because older builds read it. The removed terminal handoff's `tui` is mapped
 *  away at decode (agent-session-legacy-handoff-lease). */
export type AgentSessionOwnerRuntimeKind = 'native'

/** The acquisition stage. Stages only older builds wrote are mapped away at decode. */
export type AgentSessionHandoffStage = 'new-owner-proving' | 'recovering'

/**
 * PID-reuse-safe process identity. `spawnToken` is the only element available on every platform:
 * process start time costs a CIM query on Windows and is absent in some containers.
 */
export type AgentSessionProcessIdentity = {
  hostId: string
  pid: number
  processStartTimeMs: number | null
  spawnToken: string
  /** The Orca runtime that started this process and holds its transport, stamped when the owner is
   *  recorded; absent on owners older builds recorded. */
  runtime?: string
}

export type AgentSessionJournalCheckpoint = { epoch: number; sequence: number }

/**
 * `released` means no owner: a durable record that outlives its owner needs a name for that.
 * `conflicted` is how a terminal owner an older build recorded loads: recovery waits it out and
 * never stops it, because it is the user's own agent.
 */
export type AgentSessionClaimStatus = 'reserved' | 'live' | 'conflicted' | 'released'

export type AgentSessionDeathEvidence = {
  kind: 'exit-observed' | 'pid-absent' | 'identity-mismatch'
  detail: string
  observedAt: number
  /** Fence of the owner (or reservation) this death is about; a fence names exactly one. Absent on
   *  evidence older builds wrote, which then speaks for no turn. */
  ownerFence?: number
  /** The death interval's lower bound: the last time the runtime holding the owner's transport
   *  proved it alive. Only a probe's proof records it: absent on a surface-release exit, a failed
   *  start, and evidence older builds wrote. */
  lastProvenAliveAt?: number
  /** How the Orca runtime that held the owner ended, when the owner died with it: the quit or
   *  update it had begun, else 'crash'. Absent when a provider died on its own while Orca ran, and
   *  whenever that cannot be told. A string, since a newer build may write a cause this one does
   *  not know; read it with `isAgentSessionOrcaStopCause`. */
  runtimeEnd?: string
}

export type AgentSessionLease = {
  sessionId: string
  runtimeKind: AgentSessionOwnerRuntimeKind
  /** Durable monotonic integer; only acquisition CAS and proven eviction move it. */
  runtimeFence: number
  handoffStage: AgentSessionHandoffStage | null
  /** Link id of the provider handle this owner proved; the full chain lives on the record. */
  provenHandleLinkId: string | null
  /** Null between the durable reservation and the observed spawn. */
  ownerProcess: AgentSessionProcessIdentity | null
  /** Reserved before any process exists, then matched against the child's environment. */
  reservedSpawnToken: string | null
  leaseDeadlineAt: number
  /** While `ownerProcess` is set, the last time its transport holder proved it alive; parking in
   *  `recovering` proves nothing, so it leaves this alone. */
  lastRenewedAt: number
  handoffOperationId: string | null
  journalCheckpoint: AgentSessionJournalCheckpoint | null
  /** Key id that minted the HMAC claim this lease was granted under. */
  claimKeyId: string
  claimStatus: AgentSessionClaimStatus
  /** True from load until the host adjudicates it; no writer is granted while set. */
  unreconciled: boolean
  /**
   * Lowest fence a future grant may use. Set only by an earlier build's import of its records file,
   * when the copy came from its backup or sat beside a set-aside copy of the same chat: either may
   * hide a fence already granted. The CURRENT fence is deliberately left alone: `live` means a
   * handle proven at exactly that number, so rewriting it would invalidate the record it is trying
   * to save.
   */
  minimumNextFence?: number
  /** Null on a released lease when nothing proved its owner gone. */
  deathEvidence: AgentSessionDeathEvidence | null
}

export type AgentSessionRecord = {
  schemaVersion: typeof AGENT_SESSION_RECORD_SCHEMA_VERSION
  sessionId: string
  location: AgentSessionExecutionLocation
  /** The agent this session names, whether this build can run it or not. */
  provider: string
  providerHandleChain: AgentSessionProviderHandleLink[]
  providerContextBoundary?: AgentSessionProviderContextBoundary
  accountHome: AgentSessionAccountHome
  /** The directory the provider first launched in, in the execution host's path syntax. Floating
   *  sessions resume here; worktree and folder ids still resolve by id to their durable place. */
  launchDirectory?: string
  /** Provider options the user chose, replayed whenever a new owner starts the session. */
  options?: Record<string, string>
  /** The permission mode the user chose; Orca's, so a provider's options answer never replaces it. */
  permissionMode?: string
  rewind?: AgentSessionRewindRecord
  conversationCommand?: AgentSessionConversationCommandRecord
  /** The name Orca gave this conversation, so a later acquisition need not name it again. */
  conversationName?: string
  launchArgs?: AgentSessionLaunchArgs
  lease: AgentSessionLease
  createdAt: number
  updatedAt: number
}

/** Replaces the provider options or sets the permission mode, never both, so neither write
 *  touches the other. */
export type AgentSessionOptionsReplacement = {
  sessionId: string
  fence: number
  now: number
} & ({ options: Readonly<Record<string, string>> } | { permissionMode: string })

const MAX_ID_LENGTH = 512
/** A death evidence's `detail` past this fails a load, so whoever writes one cuts it here. */
export const MAX_AGENT_SESSION_DEATH_DETAIL_CHARS = MAX_ID_LENGTH
const MAX_LAUNCH_ENV_ENTRIES = 256
const MAX_LAUNCH_ENV_VALUE_LENGTH = 65_536
const SESSION_ID_PATTERN = /^[A-Za-z0-9_-]{8,128}$/

function isBoundedString(value: unknown, max: number): value is string {
  return typeof value === 'string' && value.length > 0 && value.length <= max
}

export function isAgentSessionId(value: unknown): value is string {
  return typeof value === 'string' && SESSION_ID_PATTERN.test(value)
}

/** NUL cannot occur in a host id, distro name, or workspace id, so no component can forge a join. */
const SCOPE_KEY_SEPARATOR = '\u0000'

/**
 * Scope key for host-and-workspace isolation. Native, WSL, and SSH copies of one workspace id are
 * different sessions; collapsing them would let one host adjudicate another host's lease.
 */
export function agentSessionScopeKey(location: AgentSessionExecutionLocation): string {
  return [location.executionHostId, location.wslDistro ?? '', location.workspaceId].join(
    SCOPE_KEY_SEPARATOR
  )
}

export function agentSessionExecutionLocationsEqual(
  left: AgentSessionExecutionLocation,
  right: AgentSessionExecutionLocation
): boolean {
  return (
    agentSessionScopeKey(left) === agentSessionScopeKey(right) &&
    left.workspaceKind === right.workspaceKind
  )
}

export function isAgentSessionExecutionLocation(
  value: unknown
): value is AgentSessionExecutionLocation {
  if (typeof value !== 'object' || value === null) {
    return false
  }
  const location = value as Partial<AgentSessionExecutionLocation>
  return (
    isBoundedString(location.executionHostId, MAX_ID_LENGTH) &&
    (location.wslDistro === null || isBoundedString(location.wslDistro, MAX_ID_LENGTH)) &&
    isBoundedString(location.workspaceId, MAX_ID_LENGTH) &&
    (location.workspaceKind === 'git-worktree' || location.workspaceKind === 'folder')
  )
}

export function isAgentSessionProcessIdentity(
  value: unknown
): value is AgentSessionProcessIdentity {
  if (typeof value !== 'object' || value === null) {
    return false
  }
  const identity = value as Partial<AgentSessionProcessIdentity>
  return (
    isBoundedString(identity.hostId, MAX_ID_LENGTH) &&
    Number.isSafeInteger(identity.pid) &&
    (identity.pid as number) > 0 &&
    (identity.processStartTimeMs === null ||
      (Number.isSafeInteger(identity.processStartTimeMs) &&
        (identity.processStartTimeMs as number) >= 0)) &&
    isBoundedString(identity.spawnToken, MAX_ID_LENGTH) &&
    (identity.runtime === undefined || isBoundedString(identity.runtime, MAX_ID_LENGTH))
  )
}

export function isAgentSessionOptions(value: unknown): value is Record<string, string> {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) {
    return false
  }
  const entries = Object.entries(value)
  return (
    entries.length <= 32 &&
    entries.every(
      ([key, option]) =>
        isBoundedString(key, MAX_ID_LENGTH) && isBoundedString(option, MAX_ID_LENGTH)
    )
  )
}

export function isAgentSessionLaunchEnv(value: unknown): value is AgentSessionLaunchEnv {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) {
    return false
  }
  const entries = Object.entries(value)
  return (
    entries.length <= MAX_LAUNCH_ENV_ENTRIES &&
    entries.every(
      ([key, entry]) =>
        isBoundedString(key, MAX_ID_LENGTH) &&
        typeof entry === 'string' &&
        entry.length <= MAX_LAUNCH_ENV_VALUE_LENGTH
    )
  )
}

function isAgentSessionJournalCheckpoint(value: unknown): value is AgentSessionJournalCheckpoint {
  if (typeof value !== 'object' || value === null) {
    return false
  }
  const checkpoint = value as Partial<AgentSessionJournalCheckpoint>
  return (
    Number.isSafeInteger(checkpoint.epoch) &&
    (checkpoint.epoch as number) >= 0 &&
    Number.isSafeInteger(checkpoint.sequence) &&
    (checkpoint.sequence as number) >= 0
  )
}

function isAgentSessionDeathEvidence(value: unknown): value is AgentSessionDeathEvidence {
  if (typeof value !== 'object' || value === null) {
    return false
  }
  const evidence = value as Partial<AgentSessionDeathEvidence>
  const { observedAt, lastProvenAliveAt, ownerFence, runtimeEnd } = evidence
  return (
    (evidence.kind === 'exit-observed' ||
      evidence.kind === 'pid-absent' ||
      evidence.kind === 'identity-mismatch') &&
    isBoundedString(evidence.detail, MAX_AGENT_SESSION_DEATH_DETAIL_CHARS) &&
    typeof observedAt === 'number' &&
    Number.isSafeInteger(observedAt) &&
    observedAt >= 0 &&
    (ownerFence === undefined || (Number.isSafeInteger(ownerFence) && ownerFence >= 0)) &&
    (lastProvenAliveAt === undefined ||
      (Number.isSafeInteger(lastProvenAliveAt) &&
        lastProvenAliveAt >= 0 &&
        lastProvenAliveAt <= observedAt)) &&
    (runtimeEnd === undefined || isBoundedString(runtimeEnd, MAX_ID_LENGTH))
  )
}

function isPersistedAgentSessionLease(value: unknown): value is PersistedAgentSessionLease {
  if (typeof value !== 'object' || value === null) {
    return false
  }
  const lease = value as Partial<AgentSessionLease>
  return (
    isAgentSessionId(lease.sessionId) &&
    isPersistedAgentSessionRuntimeKind(lease.runtimeKind) &&
    Number.isSafeInteger(lease.runtimeFence) &&
    (lease.runtimeFence as number) >= 0 &&
    (lease.handoffStage === null || isPersistedAgentSessionHandoffStage(lease.handoffStage)) &&
    (lease.provenHandleLinkId === null || isBoundedString(lease.provenHandleLinkId, 128)) &&
    (lease.ownerProcess === null || isAgentSessionProcessIdentity(lease.ownerProcess)) &&
    (lease.reservedSpawnToken === null ||
      isBoundedString(lease.reservedSpawnToken, MAX_ID_LENGTH)) &&
    Number.isSafeInteger(lease.leaseDeadlineAt) &&
    Number.isSafeInteger(lease.lastRenewedAt) &&
    (lease.handoffOperationId === null ||
      isBoundedString(lease.handoffOperationId, MAX_ID_LENGTH)) &&
    (lease.journalCheckpoint === null ||
      isAgentSessionJournalCheckpoint(lease.journalCheckpoint)) &&
    isBoundedString(lease.claimKeyId, MAX_ID_LENGTH) &&
    (lease.claimStatus === 'reserved' ||
      lease.claimStatus === 'live' ||
      lease.claimStatus === 'conflicted' ||
      lease.claimStatus === 'released') &&
    typeof lease.unreconciled === 'boolean' &&
    (lease.deathEvidence === null || isAgentSessionDeathEvidence(lease.deathEvidence))
  )
}

/** Stored identity is independent of registrations; availability is checked only at start. */
export function isPersistedAgentSessionRecord(
  value: unknown
): value is PersistedAgentSessionRecord {
  if (typeof value !== 'object' || value === null) {
    return false
  }
  const record = value as Partial<AgentSessionRecord>
  const fieldsValid =
    record.schemaVersion === AGENT_SESSION_RECORD_SCHEMA_VERSION &&
    isAgentSessionId(record.sessionId) &&
    isAgentSessionExecutionLocation(record.location) &&
    isStructuredAgentId(record.provider) &&
    isAgentSessionAccountHome(record.accountHome) &&
    (record.launchDirectory === undefined ||
      isBoundedString(record.launchDirectory, MAX_PATH_LENGTH)) &&
    (record.options === undefined || isAgentSessionOptions(record.options)) &&
    (record.permissionMode === undefined ||
      isBoundedString(record.permissionMode, MAX_ID_LENGTH)) &&
    (record.rewind === undefined || isAgentSessionRewindRecord(record.rewind)) &&
    (record.providerContextBoundary === undefined ||
      isAgentSessionProviderContextBoundary(record.providerContextBoundary)) &&
    (record.conversationCommand === undefined ||
      isAgentSessionConversationCommandRecord(record.conversationCommand)) &&
    (record.conversationName === undefined ||
      isAgentSessionConversationName(record.conversationName)) &&
    (record.launchArgs === undefined || isAgentSessionLaunchArgs(record.launchArgs)) &&
    !Object.hasOwn(record, 'launchEnv') &&
    isPersistedAgentSessionLease(record.lease) &&
    record.lease.sessionId === record.sessionId &&
    Number.isSafeInteger(record.createdAt) &&
    Number.isSafeInteger(record.updatedAt)
  if (!fieldsValid) {
    return false
  }
  const validated = record as AgentSessionRecord
  // The row holds stored handles; validate the chain they decode to.
  const chain = decodePersistedAgentSessionProviderHandleChain(validated.providerHandleChain)
  const head = chain?.at(-1)
  return (
    chain !== null &&
    // Chain validation already enforces one namespace.
    (!head || head.handle.agent === validated.provider) &&
    (validated.providerContextBoundary === undefined ||
      validated.providerContextBoundary.afterFence <= validated.lease.runtimeFence) &&
    (validated.lease.claimStatus !== 'live' ||
      (validated.lease.ownerProcess !== null &&
        // Null: the owner's process is live and its provider has not answered with a handle yet.
        (validated.lease.provenHandleLinkId === null ||
          (head?.linkId === validated.lease.provenHandleLinkId &&
            head.mintedAtFence === validated.lease.runtimeFence))))
  )
}

src/shared/agent-session-refusal-details.source:
// What a refusal says beyond its code: one reason list and one set of facts per code.
//
// A code alone cannot say what to do: `agent_session_operation_invalid` covers a cleared
// conversation (open the current one) and a busy command (wait). Each reason here is one situation
// with its own honest words and next step; a reason two codes share is listed under each. There is
// no catch-all: a site that cannot name its situation sends the code with no reason, the same as an
// older host, and the reader falls back to what it does for the code.

import type { AgentSessionAccountKind } from './agent-session-availability'
import type { AgentJournalResolution } from './agent-session-journal-types'
import {
  readCodexInstallationProblem,
  type CodexInstallationProblem
} from './codex-cli-installation'
import {
  readAgentSessionArgumentProblem,
  type AgentSessionArgumentProblem
} from './agent-session-argument-problem'
import { isAgentJournalResolution } from './agent-session-journal-schemas'
import { AGENT_SESSION_REWIND_REASONS, type AgentSessionRewindReason } from './agent-session-rewind'
import type { TuiAgent } from './tui-agent'
import { TUI_AGENT_DISPLAY_NAMES } from './tui-agent-display-names'
import type {
  AgentSessionOwnerVerdict,
  AgentSessionWireRefusalCode
} from './agent-session-wire-refusals'

export const AGENT_SESSION_REFUSAL_REASONS = {
  agent_session_operation_invalid: [
    // The request
    'requestMalformed',
    'operationIdInvalid',
    'messageIdReused',
    'operationRefusedEarlier',
    'journalWriteFailed',
    /** A Stop that could not be saved. */
    'stopFailed',
    /** A card's Cancel whose dismissal could not be saved. */
    'cancelNotSaved',
    /** The message names a chat attachment the host no longer stores. */
    'attachmentExpired',
    // The conversation's state
    'conversationCleared',
    /** Older hosts only: a /clear that never committed; its replacement may not exist. */
    'clearUnconfirmed',
    /** Older hosts only: a command blocked behind that /clear. */
    'conversationCommandUnconfirmed',
    'conversationCommandInFlight',
    'handoffInFlight',
    'turnActive',
    'promptPending',
    'backgroundTasksRunning',
    'messagesUnsettled',
    /** The chat's queued messages hold too much text to show on every client. */
    'queueTooLarge',
    'rewindRefused',
    'rewindUnconfirmed',
    // A prompt card or an option
    'promptGone',
    /** The agent that raised the prompt has ended, so nothing can take its answer. */
    'promptOwnerEnded',
    'optionRejected',
    // The provider
    'providerStarting',
    'goalsUnsupported',
    'providerRejected',
    'providerStartFailed',
    'notSignedIn',
    /** The agent's CLI is not installed on the host that would run it. */
    'cliMissing',
    'historyTooLarge',
    /** The launch's own Anthropic sign-in variables would override the managed Claude account. */
    'managedAccountEnvOverride',
    'accountSwitchInProgress',
    /** A Claude account is added in WSL and no Windows one is selected, which a chat can't run under. */
    'managedAccountUnsupported',
    /** A floating chat resumes only in the folder it ran in, and that folder is gone. */
    'launchFolderMissing',
    /** The chat's transcript is in a Claude account other than the selected one. */
    'historyInOtherAccount',
    /** The selected Claude account's folder is gone. */
    'claudeAccountFolderMissing',
    /** The selected Claude account's folder could not be set up. */
    'claudeAccountSetupFailed',
    /** Settings → Agents → Command names no program this host can run. */
    'agentCommandNotRunnable',
    /** The runtime Orca installs for the agent is not installed on this host. */
    'runtimeNotInstalled',
    /** The agent started, then Orca could not open the chat's conversation for it. */
    'attachFailed'
  ],
  agent_session_ownership_unknown: [
    'sessionNotAttached',
    'noLiveOwner',
    /** Orca cannot prove an agent process it recorded or started has exited. */
    'ownerUnproven',
    'claimConflicted',
    'recordMissing',
    'replaySuperseded',
    'leaseMoved',
    'spawnIdentityMismatch',
    'notResumable',
    'noProviderChild',
    'conversationHeldElsewhere',
    /** The close a stop began could not prove its child gone: that child takes no input and none
     *  starts beside it. Sent with `ownerVerdict: 'unverifiable'`. */
    'previousExitUnverifiable'
  ],
  agent_session_conflict: [
    'chatStarting',
    'ownerUnproven',
    'claimConflicted',
    'ownerAlive',
    'identityMismatch',
    'sessionExists',
    'conversationHeldElsewhere',
    'tabIdTaken'
  ],
  execution_owner_reconciling: ['hostReconciling', 'recordUnreadable'],
  agent_session_checkpoint_stale: ['fenceStale', 'leaseMoved', 'recordMissing'],
  agent_session_identity_required: ['recordMissing', 'transcriptNotFound', 'transcriptUnreadable'],
  agent_session_operation_conflict: ['fingerprintMismatch', 'operationIdReused', 'handoffInFlight'],
  agent_session_operation_expired: ['operationExpired'],
  agent_session_operation_capacity: ['operationCapacity'],
  agent_session_operation_unknown: [
    'outcomeUnknown',
    'resultLost',
    'rewindUnconfirmed',
    'tabUnconfirmed'
  ],
  agent_session_item_revision_stale: ['promptMoved'],
  agent_session_already_resolved: ['promptAlreadyResolved'],
  agent_session_journal_unreadable: [
    /** SQLite reports the chat's journal damaged or not a database; no retry reads past it. */
    'journalCorrupt',
    /** Any other failed open, which can clear. */
    'journalUnavailable',
    /** A newer Orca wrote the journal, or this chat's rows; only an update writes past it. */
    'journalWrittenByNewerOrca'
  ],
  structured_agent_session_unsupported: [
    'clientCapabilityMissing',
    'hostDisabled',
    'hostUnsupported'
  ],
  // Sent with no reason when starting the agent for an operation throws; older clients read it too.
  agent_session_owner_restart_failed: []
} as const satisfies Record<AgentSessionWireRefusalCode, readonly string[]>

export type AgentSessionRefusalReason<C extends AgentSessionWireRefusalCode> =
  (typeof AGENT_SESSION_REFUSAL_REASONS)[C][number]

/** A reason under any code, for a reader that keys words on the name alone. */
export type AgentSessionAnyRefusalReason = AgentSessionRefusalReason<AgentSessionWireRefusalCode>

type RewindFacts = {
  /** Which rewind check refused. */
  rewindReason?: AgentSessionRewindReason
}

type PromptFacts = {
  /** The revision the host actually holds. */
  currentRevision?: number
  /** The winning answer and who gave it. */
  resolution?: AgentJournalResolution
}

type NoFacts = Record<never, never>

export type AgentSessionConversationOwner = { sessionId: string; workspaceId: string }

type ConversationOwnerFacts = { owner?: AgentSessionConversationOwner }

/** The facts a code carries beside its reason. */
type AgentSessionRefusalFactsByCode = {
  agent_session_operation_invalid: RewindFacts & {
    account?: AgentSessionAccountKind
    argumentProblem?: AgentSessionArgumentProblem
    /** The chat's agent a `stopFailed` Stop could not stop. */
    agent?: TuiAgent
    codexInstallation?: CodexInstallationProblem
  }
  agent_session_operation_unknown: RewindFacts
  agent_session_checkpoint_stale: {
    /** So the client can retry without another round trip. */
    currentFence?: number
  }
  agent_session_item_revision_stale: PromptFacts
  agent_session_already_resolved: PromptFacts
  agent_session_ownership_unknown: ConversationOwnerFacts
  agent_session_conflict: ConversationOwnerFacts
  execution_owner_reconciling: NoFacts
  agent_session_identity_required: NoFacts
  agent_session_operation_conflict: NoFacts
  agent_session_operation_expired: NoFacts
  agent_session_operation_capacity: NoFacts
  agent_session_journal_unreadable: NoFacts
  structured_agent_session_unsupported: NoFacts
  agent_session_owner_restart_failed: NoFacts
}

/** A durably failed create says whether anything still runs for it, whichever code it failed
 *  with: `exited` proves nothing does, so a new operation cannot collide with this one. */
type AgentSessionRefusalCommonFacts = { ownerVerdict?: AgentSessionOwnerVerdict }

export type AgentSessionRefusalFacts<C extends AgentSessionWireRefusalCode> =
  AgentSessionRefusalFactsByCode[C] & AgentSessionRefusalCommonFacts

/** What an emitter must name: a reason its code lists, and that code's facts. */
export type AgentSessionRefusalDetailsByCode = {
  [C in AgentSessionWireRefusalCode]: {
    reason: AgentSessionRefusalReason<C>
  } & AgentSessionRefusalFacts<C>
}

/** Details as the wire and a durable record carry them. The reason is absent where the host could
 *  not name the situation; the whole object is absent from older hosts. */
export type AgentSessionRefusalDetails<C extends AgentSessionWireRefusalCode> = {
  reason?: AgentSessionRefusalReason<C>
} & AgentSessionRefusalFacts<C>

/** Details under whichever code, for a store that keeps them beside a code it reads as a string. */
export type AgentSessionAnyRefusalDetails = AgentSessionRefusalDetails<AgentSessionWireRefusalCode>

/** The loose top-level fields released clients read; the host writes them only from details. */
export type AgentSessionLegacyRefusalFields = {
  currentFence?: number
  currentRevision?: number
  resolution?: AgentJournalResolution
  ownerVerdict?: AgentSessionOwnerVerdict
  rewindReason?: AgentSessionRewindReason
}

const FACT_KEYS_BY_CODE: Partial<
  Record<AgentSessionWireRefusalCode, readonly (keyof AgentSessionLegacyRefusalFields)[]>
> = {
  agent_session_operation_invalid: ['rewindReason'],
  agent_session_operation_unknown: ['rewindReason'],
  agent_session_checkpoint_stale: ['currentFence'],
  agent_session_item_revision_stale: ['currentRevision', 'resolution'],
  agent_session_already_resolved: ['currentRevision', 'resolution']
}

const OWNER_VERDICTS: readonly AgentSessionOwnerVerdict[] = ['live', 'unverifiable', 'exited']

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

function readFact(
  key: keyof AgentSessionLegacyRefusalFields,
  value: unknown
): AgentSessionLegacyRefusalFields {
  switch (key) {
    case 'currentFence':
      return Number.isSafeInteger(value) && typeof value === 'number' ? { currentFence: value } : {}
    case 'currentRevision':
      return Number.isSafeInteger(value) && typeof value === 'number'
        ? { currentRevision: value }
        : {}
    case 'resolution':
      return isAgentJournalResolution(value) ? { resolution: value } : {}
    case 'ownerVerdict': {
      const ownerVerdict = OWNER_VERDICTS.find((verdict) => verdict === value)
      return ownerVerdict ? { ownerVerdict } : {}
    }
    case 'rewindReason': {
      const rewindReason = AGENT_SESSION_REWIND_REASONS.find((reason) => reason === value)
      return rewindReason ? { rewindReason } : {}
    }
  }
}

/** An agent this build can name; a newer host's agent reads as none. */
function isNamedAgent(value: unknown): value is TuiAgent {
  return typeof value === 'string' && Object.hasOwn(TUI_AGENT_DISPLAY_NAMES, value)
}

export function isAgentSessionRefusalReason<C extends AgentSessionWireRefusalCode>(
  code: C,
  value: unknown
): value is AgentSessionRefusalReason<C> {
  const reasons: readonly string[] = AGENT_SESSION_REFUSAL_REASONS[code]
  return typeof value === 'string' && reasons.includes(value)
}

/**
 * Details as a reader meets them: from the wire, a ledger row or a stored failure, possibly
 * written by another build. Keeps only a reason and facts this code lists, so a reason a newer
 * host added reads as none; undefined when nothing is left.
 */
export function readAgentSessionRefusalDetails<C extends AgentSessionWireRefusalCode>(
  code: C,
  value: unknown
): AgentSessionRefusalDetails<C> | undefined {
  if (!isRecord(value)) {
    return undefined
  }
  const keys = [...(FACT_KEYS_BY_CODE[code] ?? []), 'ownerVerdict' as const]
  const facts = keys.reduce<AgentSessionLegacyRefusalFields>(
    (kept, key) => ({ ...kept, ...readFact(key, value[key]) }),
    {}
  )
  const argumentProblem =
    code === 'agent_session_operation_invalid'
      ? readAgentSessionArgumentProblem(value.argumentProblem)
      : undefined
  const codexInstallation =
    code === 'agent_session_operation_invalid'
      ? readCodexInstallationProblem(value.codexInstallation)
      : undefined
  const owner =
    (code === 'agent_session_conflict' || code === 'agent_session_ownership_unknown') &&
    value.reason === 'conversationHeldElsewhere' &&
    isRecord(value.owner) &&
    typeof value.owner.sessionId === 'string' &&
    value.owner.sessionId.trim().length > 0 &&
    typeof value.owner.workspaceId === 'string' &&
    value.owner.workspaceId.trim().length > 0
      ? { sessionId: value.owner.sessionId, workspaceId: value.owner.workspaceId }
      : undefined
  const read = {
    ...(isAgentSessionRefusalReason(code, value.reason) ? { reason: value.reason } : {}),
    ...facts,
    ...(owner ? { owner } : {}),
    ...(code === 'agent_session_operation_invalid' &&
    value.reason === 'notSignedIn' &&
    (value.account === 'managed' || value.account === 'system')
      ? { account: value.account }
      : {}),
    ...(argumentProblem ? { argumentProblem } : {}),
    ...(code === 'agent_session_operation_invalid' &&
    value.reason === 'stopFailed' &&
    isNamedAgent(value.agent)
      ? { agent: value.agent }
      : {}),
    ...(codexInstallation ? { codexInstallation } : {})
  }
  // oxlint-disable-next-line typescript/consistent-type-assertions -- SAFETY: the reason was checked against `code`'s list and only the facts `code` lists (plus the verdict every code may carry) were kept.
  return Object.keys(read).length > 0 ? (read as AgentSessionRefusalDetails<C>) : undefined
}

/** The loose fields released clients read, taken from details; the one place they are written. */
export function agentSessionLegacyRefusalFields(
  details: AgentSessionLegacyRefusalFields | undefined
): AgentSessionLegacyRefusalFields {
  if (!details) {
    return {}
  }
  const { currentFence, currentRevision, resolution, ownerVerdict, rewindReason } = details
  return {
    ...(rewindReason !== undefined ? { rewindReason } : {}),
    ...(currentFence !== undefined ? { currentFence } : {}),
    ...(resolution !== undefined ? { resolution } : {}),
    ...(currentRevision !== undefined ? { currentRevision } : {}),
    ...(ownerVerdict !== undefined ? { ownerVerdict } : {})
  }
}

src/shared/agent-session-refusal-notice..source:
// The one way a chat surface puts a write that did not happen into words.
//
// A refusal's `message` is never shown. Every code has at least one host emitter whose message is
// written for a log or carries a marker (the census is pinned in the test), so the refusal's
// reason, when the host names one, and otherwise its code, pick the copy with the write. A code's
// own row names a cause only where every emitter of the code means it; it is also the words for a
// host too old to send a reason. A notice says how to get past a refusal only where the person has
// a step to take; retrying is the control that sent the write, except on the phone, whose message
// goes back to the composer, and a history that couldn't open right now says to try again unless
// something beside the words retries it.
// Surfaces keep the fact and choose the words when they show it, so nothing saved carries copy.

import {
  agentSessionFailureSentence,
  type AgentSessionFailureWordsContext
} from './agent-session-failure-words'
import {
  AGENT_SESSION_HISTORY_UNREAD_CAUSES,
  AGENT_SESSION_WRITE_NOTICE_COPY,
  type AgentSessionWriteNoticePart,
  type AgentSessionWriteNoticeSentence
} from './agent-session-write-notice-copy'
import type { AgentSessionWireRefusal } from './agent-session-wire-refusals'
import {
  agentSessionRefusalFailure,
  parseAgentSessionWriteFailure,
  type AgentSessionWriteFailure,
  type AgentSessionWriteKind,
  type AgentSessionWriteRefusal
} from './agent-session-write-failure'
import { agentSessionRefusalReasonWords } from './agent-session-refusal-reason-words'
import { TUI_AGENT_DISPLAY_NAMES } from './tui-agent-display-names'

export {
  agentSessionRefusalReasonWords,
  type AgentSessionRefusalAction,
  type AgentSessionRefusalReasonWords
} from './agent-session-refusal-reason-words'

const NOT_DONE: Record<AgentSessionWriteKind, AgentSessionWriteNoticeSentence> = {
  'read-history': 'notDoneReadHistory',
  send: 'notDoneSend',
  'composer-send': 'notDoneSend',
  stop: 'notDoneStop',
  'stop-task': 'notDoneStopTask',
  'stop-tasks': 'notDoneStopTasks',
  answer: 'notDoneAnswer',
  option: 'notDoneOption',
  command: 'notDoneCommand',
  clear: 'notDoneCommand',
  compact: 'notDoneCommand',
  goal: 'notDoneGoal'
}

/** A /clear or /compact refused because the agent is working: one plain sentence for every
 *  reason that is, saying only what the person sees and can do. */
const COMMAND_WHILE_WORKING: Partial<
  Record<AgentSessionWriteKind, Partial<Record<string, AgentSessionWriteNoticeSentence[]>>>
> = {
  clear: {
    turnActive: ['agentStillWorking', 'runClearWhenDone'],
    messagesUnsettled: ['agentStillWorking', 'runClearWhenDone'],
    promptPending: ['clearAfterAnswer']
  },
  compact: {
    turnActive: ['agentStillWorking', 'runCompactWhenDone'],
    messagesUnsettled: ['agentStillWorking', 'runCompactWhenDone'],
    promptPending: ['compactAfterAnswer']
  }
}

/** That the write did not happen, for one that a second attempt can carry out. Only the phone says
 *  how: its message goes back to the composer and it has no Retry control. Everywhere else the
 *  control that sent the write is the way to try again. */
export function agentSessionWriteNotDoneParts(
  write: AgentSessionWriteKind
): AgentSessionWriteNoticeSentence[] {
  return write === 'composer-send' ? ['notDoneSend', 'tryAgainComposerSend'] : [NOT_DONE[write]]
}

/** A cause, and that the request did not happen unless the cause already says so. */
function causeParts(
  cause: AgentSessionWriteNoticeSentence,
  write: AgentSessionWriteKind
): AgentSessionWriteNoticeSentence[] {
  // Says the request didn't happen, but a read asked for nothing "this" could name.
  if (cause === 'notAvailable') {
    return write === 'read-history' ? [NOT_DONE[write]] : [cause]
  }
  const saysNotDone =
    (write === 'read-history' && AGENT_SESSION_HISTORY_UNREAD_CAUSES.has(cause)) ||
    (cause === 'questionChanged' && write === 'answer') ||
    (cause === 'cancelNotSaved' && write === 'stop')
  return saysNotDone ? [cause] : [cause, NOT_DONE[write]]
}

/** The notice a named reason has of its own; undefined leaves the code's words. */
function reasonParts(
  failure: AgentSessionWriteRefusal,
  write: AgentSessionWriteKind,
  context: AgentSessionFailureWordsContext
): AgentSessionWriteNoticePart[] | undefined {
  if (
    failure.code === 'agent_session_operation_invalid' &&
    failure.details?.codexInstallation &&
    (write === 'send' || write === 'composer-send')
  ) {
    return [
      NOT_DONE[write],
      { failure: { kind: 'startFailed', refusal: failure }, surface: 'rejection', context }
    ]
  }
  if (
    failure.code === 'agent_session_operation_invalid' &&
    failure.details?.argumentProblem &&
    (write === 'send' || write === 'composer-send')
  ) {
    const argumentProblem = failure.details.argumentProblem
    return [
      NOT_DONE[write],
      {
        failure: { kind: 'startFailed', argumentProblem },
        surface: 'rejection',
        context: { ...context, agentName: argumentProblem.agent }
      }
    ]
  }
  const commandWhileWorking =
    failure.code === 'agent_session_operation_invalid'
      ? COMMAND_WHILE_WORKING[write]?.[failure.details?.reason ?? '']
      : undefined
  if (commandWhileWorking) {
    return commandWhileWorking
  }
  const words = agentSessionRefusalReasonWords(failure)
  if (!words || 'words' in words) {
    return undefined
  }
  if ('writes' in words) {
    if (!words.writes.includes(write)) {
      return undefined
    }
    const agent =
      failure.code === 'agent_session_operation_invalid' ? failure.details?.agent : undefined
    const said: AgentSessionWriteNoticePart[] = [
      {
        failure: { kind: words.fact },
        surface: 'row',
        context: agent ? { ...context, agentName: TUI_AGENT_DISPLAY_NAMES[agent] } : context
      }
    ]
    return context.retryControl && words.action === 'retry' ? said : [...said, words.step]
  }
  if ('fact' in words) {
    if (write === 'answer' && words.fact === 'providerExited') {
      // An approval or question was waiting on the person when its agent stopped: one sentence
      // that says the answer was not sent, names the agent, and says how to go on.
      return [{ failure: { kind: words.fact }, surface: 'answer', context }]
    }
    return write === 'send' || write === 'composer-send'
      ? [
          NOT_DONE[write],
          {
            failure: {
              kind: words.fact,
              ...(words.fact === 'notSignedIn' &&
              failure.code === 'agent_session_operation_invalid' &&
              failure.details?.account
                ? { account: failure.details.account }
                : {})
            },
            surface: 'rejection',
            context
          }
        ]
      : undefined
  }
  const { cause, step } = write === 'read-history' && words.history ? words.history : words
  const said = causeParts(cause, write)
  // A Retry beside the words is the step for a reason whose action is to retry.
  const retried = context.retryControl && words.action === 'retry'
  return step && !retried ? [...said, step] : said
}

/** What stopped a refused start, for a line that already says the chat did not start and shows its
 *  own Retry. Empty when the refusal names no reason with words of its own. */
export function agentSessionRefusalCauseParts(
  failure: AgentSessionWriteFailure,
  context: { agentName?: string } = {}
): AgentSessionWriteNoticePart[] {
  const parts =
    failure.kind === 'refused'
      ? reasonParts(failure, 'send', { ...context, retryControl: true })
      : undefined
  return parts?.filter((part) => part !== 'notDoneSend') ?? []
}

/** `context.retryControl`: a Retry beside the words is the step for a reason whose action is to
 *  retry, and for sending again; any other step stays. */
export function agentSessionWriteNoticeParts(
  failure: AgentSessionWriteFailure,
  write: AgentSessionWriteKind,
  context: AgentSessionFailureWordsContext = {}
): AgentSessionWriteNoticePart[] {
  const notDone = NOT_DONE[write]
  if (failure.kind === 'failed') {
    return agentSessionWriteNotDoneParts(write)
  }
  if (failure.kind === 'unconfirmed') {
    return ['outcomeUnknown']
  }
  const byReason = reasonParts(failure, write, context)
  if (byReason) {
    return byReason
  }
  switch (failure.code) {
    // The cause is in the chat's own status row. Some restarts can be retried and some need a new
    // chat, and the code does not say which.
    case 'agent_session_owner_restart_failed':
      return ['restartFailed', notDone]
    // Several different owner states share these codes. Each is refused before the id is recorded,
    // so the phone's resend under the same id can go through.
    case 'agent_session_checkpoint_stale':
    case 'agent_session_conflict':
    case 'agent_session_ownership_unknown':
    case 'execution_owner_reconciling':
      return agentSessionWriteNotDoneParts(write)
    // Only an older Orca host (one that capped its operation records) refuses this way; updating
    // it is the fix, since retrying soon would be refused again.
    case 'agent_session_operation_capacity':
      return [notDone, 'capacity']
    // The phone resends under the same id, which the host refuses the same way again. The rest
    // stand for reasons the code does not name (a cleared conversation, a pending question, a
    // provider's own rejection...), so any cause or next step could be false.
    case 'agent_session_operation_conflict':
    case 'agent_session_operation_expired':
    case 'agent_session_operation_invalid':
    case 'agent_session_identity_required':
      return [notDone]
    case 'agent_session_operation_unknown':
      return ['outcomeUnknown']
    // A Stop names the prompt it was pressed under, so it can be refused this way too.
    case 'agent_session_item_revision_stale':
    case 'agent_session_already_resolved':
      return causeParts('questionChanged', write)
    // A host that names no reason raised it for damage and for an open that can clear alike.
    case 'agent_session_journal_unreadable':
      return causeParts('historyUnreadable', write)
    case 'structured_agent_session_unsupported':
      return ['unsupported']
  }
  // A newer host can send a code this client has never heard of.
  return [notDone]
}

/** A send nobody can confirm: the host's own reason first when it gave one, never "not sent". */
export function agentSessionUnconfirmedSendParts(
  thrownRefusal: AgentSessionWriteFailure | null | undefined
): AgentSessionWriteNoticePart[] {
  const cause = thrownRefusal
    ? agentSessionWriteNoticeParts(thrownRefusal, 'composer-send').filter(
        (part) =>
          part !== 'notDoneSend' && part !== 'tryAgainComposerSend' && part !== 'outcomeUnknown'
      )
    : []
  return [...cause, 'sendOutcomeLost']
}

export function agentSessionWriteNoticeEnglish(
  parts: readonly AgentSessionWriteNoticePart[]
): string {
  return parts
    .map((part) =>
      typeof part === 'string'
        ? AGENT_SESSION_WRITE_NOTICE_COPY[part]
        : 'text' in part
          ? part.text
          : agentSessionFailureSentence(part.failure, part.surface, part.context)
    )
    .join(' ')
}

/** English, for a surface without translations. Takes the refusal as the wire gives it; its
 *  message is not read. */
export function agentSessionRefusalNotice(
  refusal: Pick<AgentSessionWireRefusal, 'code' | 'message' | 'details'>,
  write: AgentSessionWriteKind,
  context: AgentSessionFailureWordsContext = {}
): string {
  return agentSessionWriteNoticeEnglish(
    agentSessionWriteNoticeParts(agentSessionRefusalFailure(refusal), write, context)
  )
}

/** English, for a write whose request failed without a refusal. */
export function agentSessionWriteFailureNotice(write: AgentSessionWriteKind): string {
  return agentSessionWriteNoticeEnglish(agentSessionWriteNoticeParts({ kind: 'failed' }, write))
}

/** The notice for a refused read of a chat's history, from the refusal's code and any details a
 *  host sent; a code this build does not know says only that the history did not load. */
export function agentSessionReadHistoryRefusalParts(
  code: string,
  details?: unknown,
  context: AgentSessionFailureWordsContext = {}
): AgentSessionWriteNoticePart[] {
  const failure = parseAgentSessionWriteFailure({ kind: 'refused', code, details })
  return failure
    ? agentSessionWriteNoticeParts(failure, 'read-history', context)
    : agentSessionWriteNotDoneParts('read-history')
}

src/shared/agent-session-refusal-reason-.source:
// The words and next step each refusal reason gets, for every code: a reason the host adds does not
// compile until it has words here.

import type { AgentSessionFailureKind } from './agent-session-failure'
import type { AgentSessionRefusalReason } from './agent-session-refusal-details'
import type { AgentSessionWriteNoticeSentence } from './agent-session-write-notice-copy'
import type { AgentSessionWireRefusalCode } from './agent-session-wire-refusals'
import type { AgentSessionWriteKind, AgentSessionWriteRefusal } from './agent-session-write-failure'

/** What the person can do about a refusal with this reason. */
export type AgentSessionRefusalAction =
  /** Use the control that sent the write again. */
  | 'retry'
  /** Wait for what the notice names; its step says what. */
  | 'wait'
  /** Take the step the notice names first. */
  | 'actFirst'
  /** Continue somewhere else: the current conversation, or a new chat. */
  | 'goElsewhere'
  | 'checkChat'
  | 'updateOrca'
  /** What the write was for is over: the question it answered moved on. */
  | 'nothingLeft'
  /** Orca's own state or fault; nothing the person does gets past it. */
  | 'hostFinding'

export type AgentSessionRefusalReasonWords =
  /** The code's own words are the honest ones for this reason. */
  | { words: 'code'; action: AgentSessionRefusalAction }
  /** What stopped the write, and the step past it where the person has one to take. */
  | {
      cause: AgentSessionWriteNoticeSentence
      step?: AgentSessionWriteNoticeSentence
      action: AgentSessionRefusalAction
      /** Its words when what failed is reading the chat's history. */
      history?: { cause: AgentSessionWriteNoticeSentence; step: AgentSessionWriteNoticeSentence }
    }
  /** A start that failed: the sentence that failure has everywhere, whose next step is a send. */
  | { fact: AgentSessionFailureKind; action: AgentSessionRefusalAction }
  /** A failure's sentence, naming the agent, then `step`: the whole notice for `writes`. */
  | {
      fact: AgentSessionFailureKind
      action: AgentSessionRefusalAction
      step: AgentSessionWriteNoticeSentence
      writes: readonly AgentSessionWriteKind[]
    }

function codeWords(action: AgentSessionRefusalAction): AgentSessionRefusalReasonWords {
  return { words: 'code', action }
}

function causeWords(
  cause: AgentSessionWriteNoticeSentence,
  action: AgentSessionRefusalAction,
  step?: AgentSessionWriteNoticeSentence
): AgentSessionRefusalReasonWords {
  return step ? { cause, step, action } : { cause, action }
}

const AGENT_STARTING = causeWords('agentStarting', 'wait', 'waitForStart')
const OWNER_UNPROVEN = causeWords('ownerUnproven', 'actFirst', 'reopenChat')
// Only a terminal agent an older build recorded holds a claim; quitting it frees the chat.
const TERMINAL_CLAIM = causeWords('terminalAgentHoldsChat', 'actFirst', 'quitTerminalAgent')

// Every reason of every code, so a reason the host adds does not compile until it has words.
// Reasons only a create, attach, hold or adopted import meets never reach a chat write; they keep
// their code's words.
const REASON_WORDS = {
  agent_session_operation_invalid: {
    requestMalformed: codeWords('hostFinding'),
    operationIdInvalid: codeWords('hostFinding'),
    messageIdReused: codeWords('hostFinding'),
    // Settled under that id, so the control's retry goes out under a new one.
    operationRefusedEarlier: codeWords('retry'),
    journalWriteFailed: causeWords('recordFailed', 'retry'),
    // Any other write reads the code's words, as a client before this reason does.
    stopFailed: { fact: 'stopFailed', action: 'retry', step: 'tryAgain', writes: ['stop'] },
    // The card's Cancel button stays; its notice names the step.
    cancelNotSaved: causeWords('cancelNotSaved', 'retry', 'tryAgain'),
    attachmentExpired: causeWords('attachmentExpired', 'actFirst', 'reattachFile'),
    conversationCleared: causeWords(
      'conversationCleared',
      'goElsewhere',
      'openCurrentConversation'
    ),
    // Only an older host sends this, and it keeps refusing the chat, so only a new chat continues.
    clearUnconfirmed: causeWords('clearUnfinished', 'goElsewhere', 'startNewChat'),
    // Only an older host sends this, for a /clear it never settled; only that host resolves it.
    conversationCommandUnconfirmed: codeWords('hostFinding'),
    conversationCommandInFlight: causeWords('commandRunning', 'wait', 'waitForCommand'),
    // The chat's agent process is being replaced, which a start or restart does.
    handoffInFlight: AGENT_STARTING,
    turnActive: causeWords('turnActive', 'wait', 'waitForTurn'),
    promptPending: causeWords('promptPending', 'actFirst', 'answerFirst'),
    backgroundTasksRunning: causeWords('backgroundTasksRunning', 'wait', 'waitForBackgroundTasks'),
    messagesUnsettled: causeWords('messagesUnsettled', 'actFirst', 'settleEarlierMessage'),
    queueTooLarge: causeWords('queueTooLarge', 'actFirst', 'shrinkQueue'),
    // The rewind control words its own refusals; anywhere else says only that it did not happen.
    rewindRefused: codeWords('hostFinding'),
    rewindUnconfirmed: codeWords('hostFinding'),
    promptGone: causeWords('questionChanged', 'nothingLeft'),
    // An approval or question waited on the person when its agent stopped: said naming the agent,
    // with sending a message as the step on.
    promptOwnerEnded: { fact: 'providerExited', action: 'nothingLeft' },
    optionRejected: causeWords('optionRejected', 'retry'),
    providerStarting: AGENT_STARTING,
    goalsUnsupported: causeWords('goalsUnsupported', 'hostFinding'),
    providerRejected: causeWords('agentRefused', 'retry'),
    providerStartFailed: { fact: 'providerStartFailed', action: 'retry' },
    notSignedIn: { fact: 'notSignedIn', action: 'actFirst' },
    cliMissing: { fact: 'cliMissing', action: 'actFirst' },
    historyTooLarge: { fact: 'historyTooLarge', action: 'goElsewhere' },
    managedAccountEnvOverride: { fact: 'managedAccountEnvOverride', action: 'actFirst' },
    accountSwitchInProgress: { fact: 'accountSwitchInProgress', action: 'wait' },
    managedAccountUnsupported: { fact: 'managedAccountUnsupported', action: 'actFirst' },
    launchFolderMissing: { fact: 'launchFolderMissing', action: 'actFirst' },
    historyInOtherAccount: { fact: 'historyInOtherAccount', action: 'actFirst' },
    claudeAccountFolderMissing: { fact: 'claudeAccountFolderMissing', action: 'actFirst' },
    claudeAccountSetupFailed: { fact: 'claudeAccountSetupFailed', action: 'retry' },
    agentCommandNotRunnable: { fact: 'agentCommandNotRunnable', action: 'actFirst' },
    runtimeNotInstalled: { fact: 'runtimeNotInstalled', action: 'actFirst' },
    attachFailed: codeWords('retry')
  },
  agent_session_ownership_unknown: {
    sessionNotAttached: codeWords('retry'),
    noLiveOwner: codeWords('retry'),
    ownerUnproven: OWNER_UNPROVEN,
    claimConflicted: TERMINAL_CLAIM,
    recordMissing: codeWords('retry'),
    replaySuperseded: codeWords('retry'),
    leaseMoved: codeWords('retry'),
    spawnIdentityMismatch: codeWords('hostFinding'),
    notResumable: codeWords('retry'),
    noProviderChild: codeWords('retry'),
    conversationHeldElsewhere: codeWords('retry'),
    // Trying again retries the stop that could not prove the exit.
    previousExitUnverifiable: causeWords('ownerUnproven', 'retry')
  },
  agent_session_conflict: {
    chatStarting: AGENT_STARTING,
    ownerUnproven: OWNER_UNPROVEN,
    claimConflicted: TERMINAL_CLAIM,
    ownerAlive: codeWords('retry'),
    identityMismatch: codeWords('hostFinding'),
    sessionExists: codeWords('retry'),
    conversationHeldElsewhere: codeWords('retry'),
    tabIdTaken: codeWords('retry')
  },
  execution_owner_reconciling: {
    hostReconciling: causeWords('hostReconciling', 'wait', 'waitMoment'),
    recordUnreadable: causeWords('recordUnreadable', 'hostFinding')
  },
  agent_session_checkpoint_stale: {
    fenceStale: codeWords('retry'),
    leaseMoved: codeWords('retry'),
    recordMissing: codeWords('retry')
  },
  agent_session_identity_required: {
    recordMissing: causeWords('chatNotFound', 'goElsewhere', 'startNewChat'),
    transcriptNotFound: codeWords('retry'),
    transcriptUnreadable: causeWords('historyUnavailable', 'retry', 'tryAgain')
  },
  agent_session_operation_conflict: {
    fingerprintMismatch: codeWords('hostFinding'),
    operationIdReused: codeWords('hostFinding'),
    handoffInFlight: codeWords('retry')
  },
  agent_session_operation_expired: { operationExpired: codeWords('retry') },
  agent_session_operation_capacity: { operationCapacity: codeWords('updateOrca') },
  agent_session_operation_unknown: {
    outcomeUnknown: codeWords('checkChat'),
    resultLost: codeWords('checkChat'),
    rewindUnconfirmed: codeWords('checkChat'),
    tabUnconfirmed: codeWords('checkChat')
  },
  agent_session_item_revision_stale: { promptMoved: codeWords('nothingLeft') },
  agent_session_already_resolved: { promptAlreadyResolved: codeWords('nothingLeft') },
  agent_session_journal_unreadable: {
    // No retry reads past damage, and the words name no step: it only can't load.
    journalCorrupt: causeWords('historyUnusable', 'hostFinding'),
    // Says its step despite 'retry' unless a Retry stands beside it: the phone often has none.
    journalUnavailable: causeWords('historyUnavailable', 'retry', 'tryAgain'),
    // A write meets it on a newer Orca's database, or from an older host keeping the chat
    // read-only; a read meets it on this one chat, which only an update opens.
    journalWrittenByNewerOrca: {
      ...causeWords('savedByNewerOrca', 'updateOrca', 'updateOrcaToKeepUsing'),
      history: { cause: 'chatSavedByNewerOrca', step: 'updateOrcaToOpenChat' }
    }
  },
  // Mostly thrown as an RPC error; `hostUnsupported` is also returned and recorded. The code's own
  // words ask for an update, which only a method the host doesn't know proves; no reason here means
  // an older Orca. An unsupported location or agent, or no chat host, is not fixed by updating, and
  // a client missing the capability words this with its own older copy. Only `hostUnsupported`
  // names its cause: this agent or location can't run as a chat.
  structured_agent_session_unsupported: {
    clientCapabilityMissing: causeWords('notAvailable', 'hostFinding'),
    hostDisabled: causeWords('notAvailable', 'hostFinding'),
    hostUnsupported: causeWords('cannotRunHere', 'hostFinding')
  },
  agent_session_owner_restart_failed: {}
} satisfies {
  [C in AgentSessionWireRefusalCode]: Record<
    AgentSessionRefusalReason<C>,
    AgentSessionRefusalReasonWords
  >
}

/** The words and next step a reason gets; undefined when the refusal names none. */
export function agentSessionRefusalReasonWords(
  failure: AgentSessionWriteRefusal
): AgentSessionRefusalReasonWords | undefined {
  const reason = failure.details?.reason
  const byReason: Partial<Record<string, AgentSessionRefusalReasonWords>> | undefined =
    REASON_WORDS[failure.code]
  return reason === undefined ? undefined : byReason?.[reason]
}

src/shared/agent-session-rewind.ts.source:
import { z } from 'zod'
import {
  AgentJournalItemBodySchema,
  AgentJournalProducerLinkageFields,
  AgentJournalTurnScopeSchema
} from './agent-session-journal-schemas'
import { parseAgentJournalItemKey } from './agent-session-journal-item-key'
import type { AgentSessionMutationEnvelope } from './agent-session-wire'

export const AGENT_SESSION_REWIND_REASONS = [
  'unsupported',
  'history-not-paginated',
  'busy',
  'stale-epoch',
  'invalid-target',
  'history-limit',
  'provider-refused',
  'proof-mismatch',
  'outcome-unknown'
] as const
export type AgentSessionRewindReason = (typeof AGENT_SESSION_REWIND_REASONS)[number]
export type AgentSessionRewindSupport =
  | { supported: true }
  | { supported: false; reason: AgentSessionRewindReason }
export type AgentSessionRewindParams = {
  envelope: AgentSessionMutationEnvelope
  itemId: string
  expectedEpoch: string
}
export type AgentSessionRewindResult = {
  itemId: string
  epoch: string
  sequence?: number
}

const Key = z.string().min(1).max(4096)
export const AgentSessionRewindRecordSchema = z.object({
  operationId: Key,
  callerKey: Key,
  itemId: Key,
  providerItemId: Key.optional(),
  expectedEpoch: Key,
  contextClearOperationId: Key.optional(),
  contextClearSequence: z.number().int().positive().optional(),
  phase: z.enum(['prepared', 'provider-succeeded', 'completed', 'refused']),
  epoch: Key.optional(),
  sequence: z.number().int().nonnegative().optional(),
  hydrationVerified: z.boolean().optional(),
  reason: z.string().min(1).max(512).optional(),
  retained: z
    .array(
      z.object({
        itemId: Key.refine((key) => parseAgentJournalItemKey(key) !== null),
        body: AgentJournalItemBodySchema,
        observedAt: z.number().finite(),
        // Absent on records written before rows stated them: the rebuild then places the row by position.
        turnScope: AgentJournalTurnScopeSchema.optional(),
        // The row's execution provenance, carried into the rebuilt epoch. Absent on records written
        // before rows carried it.
        ownerFence: z.number().int().nonnegative().optional(),
        // The run executing a reusable child's row, kept apart from `ownerFence`. Absent on records
        // written before rows carried it.
        executionOwner: z.number().int().nonnegative().optional(),
        ...AgentJournalProducerLinkageFields
      })
    )
    .max(10_000)
})
export type AgentSessionRewindRecord = z.infer<typeof AgentSessionRewindRecordSchema>
export const isAgentSessionRewindRecord = (value: unknown): value is AgentSessionRewindRecord =>
  AgentSessionRewindRecordSchema.safeParse(value).success

export function isAgentSessionRewindResult(value: unknown): value is AgentSessionRewindResult {
  if (!value || typeof value !== 'object') {
    return false
  }
  const result = value as Partial<AgentSessionRewindResult>
  return typeof result.itemId === 'string' && typeof result.epoch === 'string'
}

src/shared/agent-session-sign-in.ts.source:
import { TUI_AGENT_DISPLAY_NAMES } from './tui-agent-display-names'

export const AGENT_SESSION_SIGN_IN = [
  { agent: 'claude', loginCommand: ['claude', 'auth', 'login'] },
  { agent: 'codex', loginCommand: ['codex', 'login'] },
  { agent: 'grok', loginCommand: ['grok', 'login'] },
  { agent: 'opencode', loginCommand: ['opencode', 'auth', 'login'] },
  { agent: 'pi', loginCommand: ['pi'], slashCommand: '/login' },
  { agent: 'omp', loginCommand: [] }
] as const

export function agentSessionSignInFor(agent: string | undefined) {
  return AGENT_SESSION_SIGN_IN.find(
    (entry) => entry.agent === agent || TUI_AGENT_DISPLAY_NAMES[entry.agent] === agent
  )
}

src/shared/agent-session-turn-completion.source:
import type { AgentJournalCursor, AgentJournalTurnOutcome } from './agent-session-journal-types'
import type { AgentSessionExecutionLocation } from './agent-session-record'

// Turn completion feed: the per-turn EDGE beside the status feed's STATE.

/**
 * The session's latest request reaching a terminal outcome — a root turn, or a send the agent or
 * its start refused — derived by the EXECUTION HOST at journal commit.
 *
 * This is the EDGE, with turn identity; `AgentSessionStatusSummary.turnOutcome` is the STATE.
 * The summary carries the verdict only while the session is idle, as a fact about the main agent's
 * last turn that a status reader may act on (attention alerts, the `mainAgent.outcome` row field),
 * and never a turn id: a reader that needs to know WHICH turn finished, or to react exactly once
 * per finish, subscribes here. Re-broadcasting the summary on every status change therefore
 * repeats a state, not a completion.
 *
 * `outcome` is the journal's recorded verdict (the provider's, a stop, or the host's supersede) and
 * is never inferred — a turn the host only observed ending carries no outcome and produces no event
 * at all, because absent means UNKNOWN, not success.
 */
export type AgentSessionTurnCompletion = {
  journalCursor?: AgentJournalCursor
  /** Host-and-workspace scope; a bare provider turn id is not globally unique. */
  scope: AgentSessionExecutionLocation
  sessionId: string
  /** The request's identity: the root turn's id, or for a send refused before any turn, that
   *  send's journal item key. Neither is minted here. */
  turnId: string
  outcome: AgentJournalTurnOutcome
  /** Execution host's clock at journal commit. */
  completedAt: number
  /** The request settled while a prompt waits on the user. Absent otherwise, and from older hosts. */
  awaitingUser?: true
}

/**
 * An approval or question newly waiting on the user, derived by the EXECUTION HOST at journal
 * commit. It usually lands mid-turn, where no completion fires. One event per prompt: a revision
 * of a still-pending prompt keeps its id and stays silent.
 */
export type AgentSessionPromptAttention = {
  journalCursor?: AgentJournalCursor
  scope: AgentSessionExecutionLocation
  sessionId: string
  /** The prompt's journal item id. */
  promptId: string
  /** Execution host's clock at journal commit. */
  raisedAt: number
}

/**
 * LIVE-ONLY: there is no snapshot arm and no replay arm, by decision. A subscriber is told what
 * completes or asks while it is subscribed and nothing else; edges that land while it is away are
 * dropped rather than queued, so nothing durable can strand. On reconnect the client baselines.
 */
export type AgentSessionTurnCompletionEvent =
  | { type: 'completion'; completion: AgentSessionTurnCompletion }
  /** Sent only to a subscriber that asked with `includePrompts`, so an older client never sees it. */
  | { type: 'prompt'; prompt: AgentSessionPromptAttention }
  | { type: 'end' }

