import { compareAppVersions, isValidAppVersion, parseCliVersion } from './app-version'

export const CODEX_MINIMUM_SUPPORTED_VERSION = '0.136.0'

export type CodexCliInstallation = {
  status: 'missing' | 'unsupported' | 'ready' | 'unknown'
  version: string | null
  minimumVersion: string
}

export type CodexInstallationProblem = {
  installedVersion: string | null
  minimumVersion: string
}

export function parseCodexCliVersion(output: string | null | undefined): string | null {
  const lines = output?.split(/\r?\n/).map((line) => line.trim()) ?? []
  const identified = lines.filter((line) => /^codex(?:-cli)?\s/i.test(line))
  const candidates = identified.length ? identified : lines.filter(Boolean)
  const versions = candidates.map((line) => {
    const value = line.replace(/^codex(?:-cli)?\s+/i, '').replace(/^v/i, '')
    return isValidAppVersion(value) ? parseCliVersion(value) : null
  })
  return versions.length && versions.every((version) => version !== null && version === versions[0])
    ? versions[0]
    : null
}

export function codexCliInstallation(
  installed: boolean,
  output: string | null
): CodexCliInstallation {
  const version = parseCodexCliVersion(output)
  return {
    status: !installed
      ? 'missing'
      : version === null
        ? 'unknown'
        : compareAppVersions(version, CODEX_MINIMUM_SUPPORTED_VERSION) < 0
          ? 'unsupported'
          : 'ready',
    version,
    minimumVersion: CODEX_MINIMUM_SUPPORTED_VERSION
  }
}

export function readCodexInstallationProblem(value: unknown): CodexInstallationProblem | undefined {
  if (
    typeof value !== 'object' ||
    value === null ||
    !('installedVersion' in value) ||
    !('minimumVersion' in value) ||
    (value.installedVersion !== null &&
      (typeof value.installedVersion !== 'string' || !isValidAppVersion(value.installedVersion))) ||
    typeof value.minimumVersion !== 'string' ||
    !isValidAppVersion(value.minimumVersion)
  ) {
    return undefined
  }
  return { installedVersion: value.installedVersion, minimumVersion: value.minimumVersion }
}

src/shared/harness-injected-user-turns.t.source:
// Why: agent harnesses (Claude Code and its forks) inject machinery into the
// conversation as user-role turns — background task notifications, system
// reminders, inter-agent messages, slash-command envelopes, local-command
// output, interruption and compaction notices. These fire user-prompt hooks
// and land in transcripts, but they are not something the user typed, so
// prompt-derived UI must not surface them.
//
// We match only tags we have observed from harnesses, never a broad kebab
// shape: a real prompt starting with a custom `<my-element>` or a Grok
// `<user_query>` envelope is a genuine user turn, and misclassifying it would
// hide the turn (drop it from transcripts, demote its session title, or leave
// the agent visibly done after an interrupt).
const LEADING_TAG_NAME = /^<([a-z][a-z0-9-]*)(?:[\s>]|$)/

// Consumers must only treat tags we have observed from harnesses as machinery;
// arbitrary kebab tags can be genuine user code.
const KNOWN_HARNESS_TAG_NAMES = new Set([
  'agent-message',
  'bash-input',
  'bash-stderr',
  'bash-stdout',
  'command-args',
  'command-message',
  'command-name',
  'cross-session-message',
  'fork-boilerplate',
  'local-command-caveat',
  'local-command-stderr',
  'local-command-stdout',
  'mcp-polling-update',
  'mcp-resource-update',
  'system-reminder',
  'task-notification',
  'teammate-message',
  'user-memory-input',
  'user-prompt-submit-hook'
])

// Injected turns identified by a leading string rather than a known tag name:
// the harness only emits <channel> in its attributed `<channel source=…>` form
// (a bare <channel> is a real RSS/XML paste), plus prose deliveries and notices.
const COMPACT_CONTINUATION_PREFIX = 'this session is being continued from a previous conversation'
const HARNESS_INJECTED_TURN_PREFIXES = [
  '<channel source=',
  '[request interrupted',
  'a message arrived from ',
  'another claude session sent a message',
  'no response requested.',
  'caveat: the messages below were generated by the user while running local commands',
  COMPACT_CONTINUATION_PREFIX
]

// Why: classification only inspects leading tags/prefixes. Cap the toLowerCase
// copy so vault-scan / prompt-seed paths stay O(1) on multi-KB pastes.
const HARNESS_CLASSIFY_HEAD_LIMIT = 256
const HARNESS_CLASSIFY_LEADING_WS_LIMIT = 64

/** True only for observed harness shapes. Match on trimmed, lowercased text.
 *  Unknown kebab tags stay user turns — only tags we have observed count. */
export function isKnownHarnessInjectedUserTurnText(text: string): boolean {
  const normalized = normalizedHarnessTurnHead(text)
  if (!normalized) {
    return false
  }
  const tagName = LEADING_TAG_NAME.exec(normalized)?.[1]
  if (tagName && KNOWN_HARNESS_TAG_NAMES.has(tagName)) {
    return true
  }
  return HARNESS_INJECTED_TURN_PREFIXES.some((prefix) => normalized.startsWith(prefix))
}

/** True only for the observed post-compaction continuation prompt. */
export function isCompactContinuationUserTurnText(text: string): boolean {
  return normalizedHarnessTurnHead(text).startsWith(COMPACT_CONTINUATION_PREFIX)
}

function normalizedHarnessTurnHead(text: string): string {
  let start = 0
  const wsScanEnd = Math.min(text.length, HARNESS_CLASSIFY_LEADING_WS_LIMIT)
  while (start < wsScanEnd && isAsciiWhitespace(text.charCodeAt(start))) {
    start += 1
  }
  if (start >= text.length) {
    return ''
  }
  const headEnd = Math.min(text.length, start + HARNESS_CLASSIFY_HEAD_LIMIT)
  return text.slice(start, headEnd).toLowerCase()
}

function isAsciiWhitespace(code: number): boolean {
  return code === 32 || code === 9 || code === 10 || code === 13 || code === 12
}

src/shared/json-text-structure-limit.ts.source:
export type JsonTextStructureLimits = Readonly<{
  structuralTokens: number
  nestingDepth: number
}>

export class JsonTextStructureCapacityError extends Error {
  constructor(
    readonly resource: keyof JsonTextStructureLimits,
    readonly limit: number
  ) {
    super(
      resource === 'structuralTokens'
        ? `JSON structure exceeds ${limit} tokens`
        : `JSON nesting exceeds ${limit} levels`
    )
    this.name = 'JsonTextStructureCapacityError'
  }
}

export function assertJsonTextStructureWithinLimits(
  content: string,
  limits: JsonTextStructureLimits
): void {
  new JsonTextStructureValidator(limits).consume(content)
}

/** Carries string/escape and structure state across bounded chunks. */
export class JsonTextStructureValidator {
  private structuralTokens = 0
  private depth = 0
  private maximumDepth = 0
  private inString = false
  private escaped = false

  constructor(private readonly limits: JsonTextStructureLimits) {
    assertLimit(limits.structuralTokens)
    assertLimit(limits.nestingDepth)
  }

  consume(content: string): void {
    let linearString = false
    for (let index = 0; index < content.length; index += 1) {
      const character = content[index]
      if (this.inString) {
        if (this.escaped) {
          this.escaped = false
          continue
        }
        if (!linearString) {
          const quote = content.indexOf('"', index)
          const end = quote === -1 ? content.length : quote
          let backslashes = 0
          for (let at = end - 1; at >= index && content[at] === '\\'; at -= 1) {
            backslashes++
          }
          if (quote === -1) {
            this.escaped = backslashes % 2 !== 0
            return
          }
          index = quote
          if (backslashes % 2 === 0) {
            this.inString = false
          } else {
            // Escape-heavy strings scan linearly instead of repeating native searches.
            linearString = true
          }
          continue
        }
        if (character === '\\') {
          this.escaped = true
        } else if (character === '"') {
          this.inString = false
          linearString = false
        }
        continue
      }
      if (character === '"') {
        this.inString = true
        continue
      }
      if (!isStructuralToken(character)) {
        continue
      }
      this.structuralTokens++
      if (this.structuralTokens > this.limits.structuralTokens) {
        throw new JsonTextStructureCapacityError('structuralTokens', this.limits.structuralTokens)
      }
      if (character === '{' || character === '[') {
        this.depth++
        this.maximumDepth = Math.max(this.maximumDepth, this.depth)
        if (this.depth > this.limits.nestingDepth) {
          throw new JsonTextStructureCapacityError('nestingDepth', this.limits.nestingDepth)
        }
      } else if (character === '}' || character === ']') {
        this.depth = Math.max(0, this.depth - 1)
      }
    }
  }

  usage(): { structuralTokens: number; nestingDepth: number } {
    return { structuralTokens: this.structuralTokens, nestingDepth: this.maximumDepth }
  }
}

function assertLimit(value: number): void {
  if (!Number.isSafeInteger(value) || value < 0) {
    throw new RangeError('JSON structure limits must be non-negative safe integers')
  }
}

function isStructuralToken(character: string | undefined): boolean {
  return (
    character === '{' ||
    character === '}' ||
    character === '[' ||
    character === ']' ||
    character === ',' ||
    character === ':'
  )
}

src/shared/main-agent-status.ts.source:
import type { AgentStatusState } from './agent-status-types'
import type { AgentTurnOutcome } from './agent-turn-outcome'

/** The main agent's OWN state, kept apart from the row's combined `state`. The row's
 *  `state` answers "what should the user see" and folds live child work in, so a settled main agent
 *  whose subagent still runs reads `working`; this answers "what is the main agent itself doing".
 *  Persisted on disk and carried on every wire, so its shape is permanent. */
export type AgentMainAgentStatus = {
  state: AgentStatusState
  /** The recorded verdict on the main agent's most recent finished turn: reported by the
   *  provider, `cancellation` inferred from the user's own interrupt keystroke, or what the host
   *  observed of an end the provider gave no verdict on. Present only while `state` is `done`; a
   *  new turn clears it. ABSENT MEANS UNKNOWN — a plain Stop never infers `success`, because an
   *  older provider that omits its interrupt flag would turn a cancel into a false success. */
  outcome?: AgentTurnOutcome
  /** Present only while `state` is `working`: a person's Stop is ending this turn. Published by a
   *  structured session's host; readers present it ("Stopping…") and never store it. */
  stopping?: true
  /** When the main agent's own `state` first appeared (ms). The row's `stateStartedAt` dates the
   *  combined state instead, so the two differ while child work holds the row open. */
  stateStartedAt: number
}

export function mainAgentStatusEqual(
  a: AgentMainAgentStatus | undefined,
  b: AgentMainAgentStatus | undefined
): boolean {
  if (a === b) {
    return true
  }
  if (!a || !b) {
    return false
  }
  return (
    a.state === b.state &&
    a.outcome === b.outcome &&
    a.stopping === b.stopping &&
    a.stateStartedAt === b.stateStartedAt
  )
}

