import type { AgentType } from './agent-status-types'
import {
  getAgentSlashCommands,
  type NativeChatCommandReply,
  type SlashCommandSuggestion
} from './native-chat-slash-commands'

export type NativeChatAgentProfile = {
  skillPrefix: '$' | '/'
  /** OpenClaude reads Claude-owned roots, so this can differ from the agent. */
  skillSourceOwner: AgentType
  /** The agent's own harness expands a slash command out of the message text, so
   *  the chat host claims only the commands it implements itself. */
  expandsSlashCommandsFromText?: true
  /** Catalog commands the model acts on when they arrive as prose, even though
   *  the runtime has no slash parser of its own. */
  textDrivenCommands?: readonly string[]
}

const NATIVE_CHAT_AGENT_PROFILES: Partial<Record<AgentType, NativeChatAgentProfile>> = {
  codex: {
    skillPrefix: '$',
    skillSourceOwner: 'codex',
    // The app-server has no slash parser, but the model owns goal tools and
    // calls create_goal itself when `/goal <objective>` reaches it as prose.
    textDrivenCommands: ['goal']
  },
  claude: {
    skillPrefix: '/',
    skillSourceOwner: 'claude',
    expandsSlashCommandsFromText: true
  },
  openclaude: {
    skillPrefix: '/',
    skillSourceOwner: 'claude',
    expandsSlashCommandsFromText: true
  },
  opencode: { skillPrefix: '/', skillSourceOwner: 'opencode', expandsSlashCommandsFromText: true },
  opencode2: {
    skillPrefix: '/',
    skillSourceOwner: 'opencode2',
    expandsSlashCommandsFromText: true
  },
  grok: {
    skillPrefix: '/',
    skillSourceOwner: 'grok'
  }
}

export function getNativeChatAgentProfile(
  agent: AgentType | null | undefined
): NativeChatAgentProfile | null {
  return agent ? (NATIVE_CHAT_AGENT_PROFILES[agent] ?? null) : null
}

/** The catalog that send classification, collision detection, and transcript
 *  envelope surfacing key off. Grok has no verified catalog yet, so its slash
 *  surface stays skills-only — this is the single place that policy lives. */
export function getVerifiedNativeChatCommands(agent: AgentType): readonly SlashCommandSuggestion[] {
  return agent === 'grok' ? [] : getAgentSlashCommands(agent)
}

/** How the chat finds the reply to a verified command over a terminal session;
 *  null when the agent answers it in the terminal or the command is unknown. */
export function getNativeChatCommandReply(
  agent: AgentType,
  commandName: string
): NativeChatCommandReply | null {
  return (
    getVerifiedNativeChatCommands(agent).find((command) => command.name === commandName)?.reply ??
    null
  )
}

/** The verified catalog minus commands only the desktop chat answers: a surface
 *  without the composer's answers or the transcript's reply rows (mobile) would
 *  offer a command that appears to do nothing. */
export function getAgentAnsweredNativeChatCommands(
  agent: AgentType
): readonly SlashCommandSuggestion[] {
  return getVerifiedNativeChatCommands(agent).filter((command) => command.reply === undefined)
}

/** The mirror of the claimed set: catalog commands this agent acts on when they
 *  arrive as message text. The picker offers these too, so a command the agent
 *  implements is discoverable and not merely typable. */
export function getTextDrivenNativeChatCommands(
  agent: AgentType | null | undefined
): readonly SlashCommandSuggestion[] {
  if (!agent) {
    return []
  }
  const names = new Set(getNativeChatAgentProfile(agent)?.textDrivenCommands ?? [])
  return names.size === 0
    ? []
    : getVerifiedNativeChatCommands(agent).filter((command) => names.has(command.name))
}

/** Catalog commands the chat host answers itself. Whatever is left over reaches
 *  the agent as ordinary text, which is only correct where the agent implements
 *  the command — so an agent unclaims a command only via the profile above.
 *  Claiming stays the default: it is what stops a hand-typed `/clear` from being
 *  sent to the model as literal prompt text. */
export function getHostClaimedNativeChatCommands(
  agent: AgentType
): readonly SlashCommandSuggestion[] {
  const profile = getNativeChatAgentProfile(agent)
  if (profile?.expandsSlashCommandsFromText) {
    return []
  }
  const passedThrough = new Set(profile?.textDrivenCommands ?? [])
  return getVerifiedNativeChatCommands(agent).filter((command) => !passedThrough.has(command.name))
}

src/shared/native-chat-command-envelope..source:
// Claude-family harnesses record a slash input's user turn as a command
// envelope (`<command-name>/x</command-name>…`), not as the typed text. The
// noise filter rightly hides those for catalog commands — Orca shows a local
// `Ran /x` line instead — but a skill invocation IS the user's chat turn, so
// dropping its envelope makes the assistant appear to answer an empty
// conversation. Surface non-catalog envelopes back as plain user text.

import { isTextBlock, type NativeChatMessage } from './native-chat-types'

const COMMAND_NAME = /<command-name>([\s\S]*?)<\/command-name>/
const COMMAND_ARGS = /<command-args>([\s\S]*?)<\/command-args>/

export type NativeChatCommandEnvelope = { name: string; args: string }

/** Parse a user turn recorded as a command envelope. Returns null for any text
 *  that does not lead with an envelope tag (ordinary prompts, XML pastes). */
export function parseNativeChatCommandEnvelope(text: string): NativeChatCommandEnvelope | null {
  const trimmed = text.trimStart()
  if (!trimmed.toLowerCase().startsWith('<command-')) {
    return null
  }
  const name = COMMAND_NAME.exec(trimmed)?.[1]?.trim()
  if (!name) {
    return null
  }
  return { name, args: COMMAND_ARGS.exec(trimmed)?.[1]?.trim() ?? '' }
}

/**
 * Replace skill-invocation envelopes with the token the user sent (`/name
 * args`) so the turn renders as their message and the optimistic echo can
 * reconcile against it. Catalog commands stay untouched — the noise filter
 * hides them and the local `Ran /name` marker is their feedback.
 */
export function surfaceSkillInvocationUserTurns(
  messages: readonly NativeChatMessage[],
  catalogCommandNames: ReadonlySet<string>
): NativeChatMessage[] {
  let changed = false
  const out = messages.map((message) => {
    if (message.role !== 'user' || !message.blocks.every(isTextBlock)) {
      return message
    }
    const envelope = parseNativeChatCommandEnvelope(
      message.blocks.map((block) => block.text).join('\n')
    )
    if (!envelope || catalogCommandNames.has(envelope.name.replace(/^\//, ''))) {
      return message
    }
    // Why: the harness canonicalizes a plugin skill to `/plugin:name`, but the
    // user (and the picker) sent the short frontmatter name. Render the short
    // token so the bubble shows what was typed and the optimistic echo prunes
    // instead of duplicating the turn.
    const shortName = envelope.name.replace(/^\//, '').split(':').at(-1) ?? ''
    const token = `/${shortName}`
    changed = true
    return {
      ...message,
      blocks: [{ type: 'text' as const, text: envelope.args ? `${token} ${envelope.args}` : token }]
    }
  })
  return changed ? out : (messages as NativeChatMessage[])
}

src/shared/native-chat-command-output.ts.source:
// Claude-family harnesses record a local command's reply as a
// `<local-command-stdout>` user turn linked to the command's envelope row. The
// noise filter hides those rows, which is right for commands whose effect is the
// feedback (`/model`, `/compact`). For a command that exists to report
// something, the reply is the answer, so the chat surfaces it.

import type { AgentType } from './agent-status-types'
import { stripAnsiEscapeSequences } from './ansi-escape-sequences'
import { getVerifiedNativeChatCommands } from './native-chat-agent-profiles'
import { parseNativeChatCommandEnvelope } from './native-chat-command-envelope'
import { isTextBlock, type NativeChatMessage } from './native-chat-types'

const LOCAL_COMMAND_STDOUT = /^\s*<local-command-stdout>([\s\S]*?)<\/local-command-stdout>\s*$/

function userText(message: NativeChatMessage): string | null {
  return message.role === 'user' && message.blocks.every(isTextBlock)
    ? message.blocks.map((block) => block.text).join('\n')
    : null
}

/** The command a user turn's envelope names, without its slash; null for other turns. */
function envelopeCommand(message: NativeChatMessage): string | null {
  const text = userText(message)
  const envelope = text === null ? null : parseNativeChatCommandEnvelope(text)
  return envelope ? envelope.name.replace(/^\//, '') : null
}

/**
 * Replace the stdout row answering a command whose catalog row declares a
 * transcript reply with its plain text as command output. A reply answers the
 * row it is linked to; without that link (an older host, or the command row
 * outside the loaded window) it stays hidden.
 */
export function surfaceNativeChatCommandOutputs(
  messages: NativeChatMessage[],
  agent: AgentType
): NativeChatMessage[] {
  const transcriptReplies = new Set(
    getVerifiedNativeChatCommands(agent)
      .filter((command) => command.reply === 'transcript')
      .map((command) => command.name)
  )
  // Why: this runs on every transcript update; agents declaring no such reply skip the scan.
  if (transcriptReplies.size === 0) {
    return messages
  }
  let rowsById: Map<string, NativeChatMessage> | null = null
  let changed = false
  const out = messages.map((message) => {
    if (message.parentId === undefined) {
      return message
    }
    const stdout = LOCAL_COMMAND_STDOUT.exec(userText(message) ?? '')?.[1]
    if (stdout === undefined) {
      return message
    }
    rowsById ??= new Map(messages.map((row) => [row.id, row]))
    const parent = rowsById.get(message.parentId)
    const command = parent ? envelopeCommand(parent) : null
    if (command === null || !transcriptReplies.has(command)) {
      return message
    }
    const text = stripAnsiEscapeSequences(stdout).trim()
    if (!text) {
      return message
    }
    changed = true
    return {
      ...message,
      role: 'system' as const,
      blocks: [{ type: 'text' as const, text, presentation: 'command-output' }]
    }
  })
  return changed ? out : messages
}

src/shared/native-chat-empty-state.ts.source:
// Canonical English copy for the native-chat empty/loading/error states, shared
// by the desktop renderer (as its i18n fallback strings) and the mobile app
// (used directly — mobile ships English only) so the two surfaces never drift.
// `{{value0}}` is the agent label; each caller substitutes it (i18n on desktop,
// `formatNativeChatEmptyStateCopy` on mobile).

export type NativeChatEmptyStateCopy = { title: string; subtitle: string }

export const NATIVE_CHAT_EMPTY_STATE_COPY = {
  loading: {
    title: 'Loading conversation…',
    subtitle: 'Reading the agent transcript.'
  },
  empty: {
    title: 'Start a chat with {{value0}}',
    subtitle: 'Ask {{value0}} to inspect code, explain output, or make a change.'
  },
  error: {
    title: 'Could not load conversation',
    subtitle: 'The transcript could not be read. Toggle back to the terminal to keep working.'
  },
  notAgent: {
    title: 'No conversation here',
    subtitle: 'This terminal is not running a recognized coding agent.'
  }
} as const satisfies Record<string, NativeChatEmptyStateCopy>

/** Resolve the empty-state copy with the agent label substituted for `{{value0}}`.
 *  For platforms without an i18n layer (mobile). */
export function formatNativeChatEmptyStateCopy(
  kind: keyof typeof NATIVE_CHAT_EMPTY_STATE_COPY,
  agentLabel: string
): NativeChatEmptyStateCopy {
  const copy = NATIVE_CHAT_EMPTY_STATE_COPY[kind]
  return {
    title: copy.title.replaceAll('{{value0}}', agentLabel),
    subtitle: copy.subtitle.replaceAll('{{value0}}', agentLabel)
  }
}

src/shared/native-chat-folded-tool-resul.source:
import { unpairedToolResultIndices } from './native-chat-tool-pairs'
import type { NativeChatBlock, NativeChatMessage } from './native-chat-types'

type ToolContribution = {
  source: NativeChatMessage
  blocks: readonly NativeChatBlock[]
  start: number
  insertAt: number
  sourceRow?: number
}

/** Retains each result's source row while a run combines provider records. */
export class FoldedToolResultSources {
  private readonly contributions = new Map<number, ToolContribution[]>()

  constructor(private readonly sourceMessages: readonly NativeChatMessage[]) {}

  append(
    row: number,
    target: NativeChatMessage,
    source: NativeChatMessage,
    blocks: readonly NativeChatBlock[],
    insertAt: number,
    sourceRow?: number
  ): void {
    let contributors = this.contributions.get(row)
    if (!contributors) {
      contributors = [
        { source: target, blocks: target.blocks, start: 0, insertAt: row + 1, sourceRow: row }
      ]
      this.contributions.set(row, contributors)
    }
    contributors.push({ source, blocks, start: target.blocks.length, insertAt, sourceRow })
  }

  project(rows: NativeChatMessage[]): NativeChatMessage[] {
    let retained: (NativeChatMessage | null)[] | undefined
    const unpairedByRow = new Map<number, ReadonlySet<number>>()
    for (const [rowIndex, message] of rows.entries()) {
      if (
        message.unpairedToolResults ||
        !message.blocks.some((block) => block.type === 'tool-result')
      ) {
        continue
      }
      const unpaired = unpairedToolResultIndices(message.blocks)
      if (unpaired.size === 0) {
        continue
      }
      const blocks = message.blocks.filter((_block, index) => !unpaired.has(index))
      retained ??= Array.from(rows)
      retained[rowIndex] = blocks.length > 0 ? { ...message, blocks } : null
      unpairedByRow.set(rowIndex, unpaired)
    }
    if (!retained) {
      return rows
    }
    const orphans = new Map<number, NativeChatMessage[]>()
    const allocatedIds = new Set(this.sourceMessages.map((message) => message.id))
    const occurrences = new Map<string, number>()
    for (const [rowIndex, unpaired] of unpairedByRow) {
      const message = rows[rowIndex]!
      const contributors = this.contributions.get(rowIndex) ?? [
        {
          source: message,
          blocks: message.blocks,
          start: 0,
          insertAt: rowIndex + 1,
          sourceRow: rowIndex
        }
      ]
      for (const contribution of contributors) {
        const orphanBlocks = contribution.blocks.filter(
          (block, index) =>
            block.type === 'tool-result' &&
            block.callId !== undefined &&
            unpaired.has(contribution.start + index)
        )
        if (orphanBlocks.length === 0) {
          continue
        }
        const sourceStillDraws =
          contribution.sourceRow !== undefined && retained[contribution.sourceRow] !== null
        const id = sourceStillDraws
          ? orphanRowId(contribution.source.id, allocatedIds, occurrences)
          : contribution.source.id
        allocatedIds.add(id)
        const orphan: NativeChatMessage = {
          ...contribution.source,
          id,
          role: 'tool',
          blocks: orphanBlocks,
          unpairedToolResults: true
        }
        const at = orphans.get(contribution.insertAt)
        if (at) {
          at.push(orphan)
        } else {
          orphans.set(contribution.insertAt, [orphan])
        }
      }
    }
    const projected: NativeChatMessage[] = []
    for (let index = 0; index <= retained.length; index += 1) {
      projected.push(...(orphans.get(index) ?? []))
      const message = retained[index]
      if (message) {
        projected.push(message)
      }
    }
    return projected
  }
}

function orphanRowId(
  sourceId: string,
  allocated: ReadonlySet<string>,
  occurrences: Map<string, number>
): string {
  let occurrence = occurrences.get(sourceId) ?? 0
  let id = `unpaired-tool-results:${JSON.stringify([sourceId, occurrence])}`
  while (allocated.has(id)) {
    occurrence += 1
    id = `unpaired-tool-results:${JSON.stringify([sourceId, occurrence])}`
  }
  occurrences.set(sourceId, occurrence + 1)
  return id
}

src/shared/native-chat-image-transcript-.source:
import { unwrapClaudePastedContent } from './claude-pasted-content'
import {
  stripAnsiEscapeSequences,
  TERMINAL_CONTROL_CHARACTER_PATTERN
} from './ansi-escape-sequences'
import { isTextBlock, type NativeChatBlock, type NativeChatMessage } from './native-chat-types'

const IMAGE_SOURCE_MARKER = /^\[Image:\s*source:\s*(.+?)\]\s*$/
const IMAGE_PROMPT_MARKER = /\[Image #\d+\]/
const IMAGE_PROMPT_MARKERS = /\[Image #\d+\]/g
const IMAGE_PROMPT_MARKER_AT_START = /^[^\S\r\n]*\[Image #\d+\]/
const IMAGE_PROMPT_MARKER_AT_END = /\[Image #\d+\][^\S\r\n]*$/
const HORIZONTAL_WHITESPACE_START = /^[^\S\r\n]+/
const HORIZONTAL_WHITESPACE_END = /[^\S\r\n]+$/

export function imageSourcePathFromText(text: string): string | null {
  return text.match(IMAGE_SOURCE_MARKER)?.[1]?.trim() ?? null
}

/** Every image-source path a user turn carries, or [] when it is not a pure
 *  image-source turn.
 *
 *  Why not `soleText`: Claude records a multi-image paste as ONE companion message
 *  holding one `[Image: source: ...]` text block per image, so requiring a single
 *  block missed every multi-image turn. A turn qualifies only when it is all text
 *  and every block is a marker, so a real prompt is never mistaken for one. */
export function imageSourcePathsFromMessage(message: NativeChatMessage): string[] {
  if (message.role !== 'user' || message.blocks.length === 0) {
    return []
  }
  const paths: string[] = []
  for (const block of message.blocks) {
    if (!isTextBlock(block)) {
      return []
    }
    const path = imageSourcePathFromText(block.text)
    if (path === null) {
      return []
    }
    paths.push(path)
  }
  return paths
}

export function isImageSourceUserTurn(message: NativeChatMessage): boolean {
  return imageSourcePathsFromMessage(message).length > 0
}

export function stripImagePromptMarker(text: string): string {
  const stripped = text.replace(IMAGE_PROMPT_MARKERS, '')
  if (stripped === text) {
    return text
  }
  let result = IMAGE_PROMPT_MARKER_AT_START.test(text)
    ? stripped.replace(HORIZONTAL_WHITESPACE_START, '')
    : stripped
  if (IMAGE_PROMPT_MARKER_AT_END.test(text)) {
    result = result.replace(HORIZONTAL_WHITESPACE_END, '')
  }
  return result
}

/** Normalizes PTY-backed user text into the pending-echo comparison key. */
export function normalizeNativeChatUserText(text: string): string {
  // Strip sequences first so their printable tails cannot survive a lone-control pass.
  return stripImagePromptMarker(
    stripAnsiEscapeSequences(unwrapClaudePastedContent(text)).replace(
      TERMINAL_CONTROL_CHARACTER_PATTERN,
      ''
    )
  )
    .trim()
    .replace(/\s+/g, ' ')
}

export function normalizedNativeChatUserMessageText(message: NativeChatMessage): string | null {
  if (message.role !== 'user') {
    return null
  }
  const normalized = normalizeNativeChatUserText(
    message.blocks
      .filter(isTextBlock)
      .map((block) => unwrapClaudePastedContent(block.text))
      .join(' ')
  )
  return normalized || null
}

function stripImagePromptMarkersFromTextBlocks(
  blocks: readonly NativeChatBlock[]
): NativeChatBlock[] {
  let sawText = false
  let next: NativeChatBlock[] | null = null
  for (let index = 0; index < blocks.length; index += 1) {
    const block = blocks[index]!
    if (!isTextBlock(block)) {
      next?.push(block)
      continue
    }
    const isFirstText = !sawText
    sawText = true
    const text = stripImagePromptMarker(block.text)
    if (!text.trim() && (text !== block.text || isFirstText)) {
      next ??= blocks.slice(0, index)
      continue
    }
    if (text !== block.text) {
      next ??= blocks.slice(0, index)
      next.push({ ...block, text })
      continue
    }
    next?.push(block)
  }
  return next ?? (blocks as NativeChatBlock[])
}

export function hasImagePromptMarker(message: NativeChatMessage): boolean {
  return message.blocks.some((block) => isTextBlock(block) && IMAGE_PROMPT_MARKER.test(block.text))
}

/** Claude records image paths as source turns followed by a prompt carrying
 *  image markers. Merge the whole run back into one native user turn. */
export function normalizeImageTranscriptMessages(
  messages: readonly NativeChatMessage[]
): NativeChatMessage[] {
  let normalized: NativeChatMessage[] | null = null
  for (let index = 0; index < messages.length; index += 1) {
    const message = messages[index]!
    if (message.role !== 'user') {
      normalized?.push(message)
      continue
    }
    const messageImagePaths = imageSourcePathsFromMessage(message)
    if (messageImagePaths.length > 0) {
      normalized ??= messages.slice(0, index)
      const imagePaths = [...messageImagePaths]
      let nextIndex = index + 1
      while (nextIndex < messages.length) {
        const candidate = messages[nextIndex]!
        const candidatePaths = imageSourcePathsFromMessage(candidate)
        if (
          candidate.role !== 'user' ||
          candidate.source !== message.source ||
          candidatePaths.length === 0
        ) {
          break
        }
        imagePaths.push(...candidatePaths)
        nextIndex += 1
      }
      const prompt = messages[nextIndex]
      if (
        prompt?.role === 'user' &&
        prompt.source === message.source &&
        hasImagePromptMarker(prompt)
      ) {
        normalized.push({
          ...prompt,
          blocks: [
            ...imagePaths.map((path) => ({ type: 'image-ref' as const, path })),
            ...stripImagePromptMarkersFromTextBlocks(prompt.blocks)
          ]
        })
        index = nextIndex
        continue
      }
      // Only THIS turn's paths: `imagePaths` also holds the following source turns the
      // fold scan looked at, and without a prompt to fold into they stay separate turns.
      normalized.push({
        ...message,
        blocks: messageImagePaths.map((path) => ({ type: 'image-ref' as const, path }))
      })
      continue
    }
    const blocks = stripImagePromptMarkersFromTextBlocks(message.blocks)
    if (blocks === message.blocks) {
      normalized?.push(message)
    } else {
      normalized ??= messages.slice(0, index)
      normalized.push({ ...message, blocks })
    }
  }
  return normalized ?? (messages as NativeChatMessage[])
}

src/shared/native-chat-message-preparati.source:
// What a chat reads from a terminal agent's transcript before folding it into rows. Desktop and
// mobile both prepare through here, so a turn one of them draws is never dropped by the other.

import type { AgentType } from './agent-status-types'
import { getVerifiedNativeChatCommands } from './native-chat-agent-profiles'
import { surfaceSkillInvocationUserTurns } from './native-chat-command-envelope'
import { surfaceNativeChatCommandOutputs } from './native-chat-command-output'
import { normalizeImageTranscriptMessages } from './native-chat-image-transcript-markers'
import type { NativeChatMessage } from './native-chat-types'

/** A skill invocation as the `/name args` the user sent, and a reporting command's reply as its
 *  output; the harness records both as envelopes the noise filter would otherwise hide. */
export function surfaceNativeChatHarnessTurns(
  messages: readonly NativeChatMessage[],
  agent: AgentType
): NativeChatMessage[] {
  const commandNames = new Set(getVerifiedNativeChatCommands(agent).map((command) => command.name))
  return surfaceNativeChatCommandOutputs(
    surfaceSkillInvocationUserTurns(messages, commandNames),
    agent
  )
}

/** The harness turns surfaced, then image marker turns folded into the prompt they belong to. */
export function prepareNativeChatMessages(
  messages: readonly NativeChatMessage[],
  agent: AgentType
): NativeChatMessage[] {
  return normalizeImageTranscriptMessages(surfaceNativeChatHarnessTurns(messages, agent))
}

src/shared/native-chat-messages-waiting-.source:
// Which rows wait at the tail, after the live turn's activity line, rather than in the transcript.

import type { AgentJournalRenderItem, AgentJournalSubmission } from './agent-session-journal-types'
import type { AgentSessionLatestTurn } from './agent-session-wire'
import { readAgentJournalTurn } from './agent-session-turn-record'
import type { NativeChatRole } from './native-chat-types'
import { isStructuredAgentSessionCommandTurn } from './structured-agent-session-command-entry'
import { runningStructuredAgentSessionTurnScope } from './structured-agent-session-live-turn'
import { structuredAgentSessionOpeningSendIn } from './structured-agent-session-opening-send'

/**
 * The rows accepted but not yet handed over while a conversation command's turn runs, as a message
 * sent during `/compact` is: the host hands nothing over until the command ends, so they draw after
 * that turn's live activity. Any other running turn takes a send within moments, so it stays put,
 * unless a person's Stop is ending it (`stopping`): the host holds a send made then until it ends,
 * so those, and this client's own sends made then that it has not recorded yet, draw after the
 * live activity too. A send made before the Stop stays where it is. While a send ahead is still
 * opening its turn (`submissions`), the rows sent after it wait too, queued or not recorded yet:
 * the host takes none of them into that turn until it opens, and a queued row's place, the row that
 * accepted it, is above the handover that moved that send.
 */
export function nativeChatMessagesWaitingBehindLiveTurn(
  messages: readonly {
    id: string
    role?: NativeChatRole
    queued?: true
    unsent?: true
    sentWhileStopping?: true
    awaitsRetry?: true
    journalPosition?: unknown
  }[],
  items: readonly AgentJournalRenderItem[] | null | undefined,
  stopping = false,
  submissions?: readonly AgentJournalSubmission[],
  /** The host's view of current work (`latestTurn`, `working`): an ended generation's running turn
   *  or unanswered send holds nothing. Absent from an older host, whose rows are read instead. */
  host: { latestTurn?: AgentSessionLatestTurn | null; working?: boolean } = {}
): ReadonlySet<string> {
  const waits = (message: (typeof messages)[number]): boolean =>
    message.queued === true || (stopping && message.sentWhileStopping === true)
  // Behind a turn still opening: queued, or a send of this client's the host has not recorded and
  // is not waiting on the user's Retry.
  const unrecorded = (message: (typeof messages)[number]): boolean =>
    message.role === 'user' &&
    message.journalPosition === undefined &&
    message.unsent !== true &&
    message.awaitsRetry !== true
  const candidates = messages.filter((message) => waits(message) || unrecorded(message))
  if (candidates.length === 0 || !items) {
    return new Set()
  }
  const behindHold = stopping || commandTurnRunning(items, host.latestTurn)
  const behindOpening =
    host.working !== false &&
    submissions !== undefined &&
    structuredAgentSessionOpeningSendIn(items, submissions) !== null
  return new Set(
    candidates
      .filter(
        (message) =>
          (behindHold && waits(message)) ||
          (behindOpening && (message.queued === true || unrecorded(message)))
      )
      .map((message) => message.id)
  )
}

function commandTurnRunning(
  items: readonly AgentJournalRenderItem[],
  latestTurn: AgentSessionLatestTurn | null | undefined
): boolean {
  const running = runningStructuredAgentSessionTurnScope({
    items,
    ...(latestTurn !== undefined ? { latestTurn } : {})
  })
  const bodyOf = (itemId: string) => items.find((item) => item.itemId === itemId)?.body
  return (
    running.kind === 'turn' &&
    isStructuredAgentSessionCommandTurn(readAgentJournalTurn(bodyOf(running.turnItemId)), bodyOf)
  )
}

/** While a send is still opening its turn, that send's turn is the live one, not a message sent
 *  after it that waits behind it (`nativeChatMessagesWaitingBehindLiveTurn`). */
export function nativeChatOpeningTurnKey(
  messages: readonly { id: string }[],
  turnKeys: readonly (string | undefined)[],
  journal: {
    items: readonly AgentJournalRenderItem[]
    submissions: readonly AgentJournalSubmission[]
  }
): string | undefined {
  const opening = structuredAgentSessionOpeningSendIn(journal.items, journal.submissions)
  const index = opening === null ? -1 : messages.findIndex((message) => message.id === opening)
  return index === -1 ? undefined : turnKeys[index]
}

