const COPY_BLOCK_CODE_UNITS = 4 * 1024

export function copyUtf16SuffixToOwnedString(value: string, suffixCodeUnits: number): string {
  const suffixLength = Math.max(0, Math.min(value.length, suffixCodeUnits))
  const start = value.length - suffixLength
  const blocks: string[] = []
  const codeUnits: number[] = []
  codeUnits.length = Math.min(COPY_BLOCK_CODE_UNITS, suffixLength)

  // Why: slice can retain an arbitrarily large V8 backing string.
  for (let offset = start; offset < value.length; offset += COPY_BLOCK_CODE_UNITS) {
    const blockLength = Math.min(COPY_BLOCK_CODE_UNITS, value.length - offset)
    codeUnits.length = blockLength
    for (let index = 0; index < blockLength; index += 1) {
      codeUnits[index] = value.charCodeAt(offset + index)
    }
    blocks.push(String.fromCharCode(...codeUnits))
  }
  return blocks.join('')
}

src/shared/provider-timeline-item-key.ts.source:
/** The encoded key inside a provider-keyed journal record, independent of session and thread. */
export function spelledProviderTimelineItemKey(recordId: string): string | null {
  if (!recordId.startsWith('item:p:')) {
    return null
  }
  // Parts are URI-encoded; only separators retain literal colons and slashes.
  const scoped = recordId.slice(recordId.lastIndexOf(':') + 1)
  return scoped.slice(scoped.lastIndexOf('/') + 1)
}

src/shared/sentence-joining.ts.source:
// Japanese and Chinese run on after a full-width terminator; any other sentence takes a space.
const RUNS_ON_AFTER = /[。！？]$/

/** Whole sentences as one passage. Each gap follows the sentence before it, not the UI language, so
 *  a sentence a language pack left in English keeps its space beside translated ones. */
export function joinSentences(sentences: readonly string[]): string {
  return sentences
    .map((sentence, index) =>
      index === 0 || RUNS_ON_AFTER.test(sentences[index - 1]) ? sentence : ` ${sentence}`
    )
    .join('')
}

