// The one definition of a structured journal's tool actions: which rows the chat draws as a
// tool call, and the block it draws. The status line reads the same definition, so the sidebar
// names a tool exactly as the chat draws it.

import type {
  AgentJournalDiffItem,
  AgentJournalItemBody,
  AgentJournalToolCallItem
} from './agent-session-journal-types'
import type { NativeChatToolCallBlock } from './native-chat-types'

export type StructuredAgentSessionToolAction = AgentJournalToolCallItem | AgentJournalDiffItem

// Codex rewrites an edit's `apply_patch` call into a diff once its changes exist.
export function isStructuredAgentSessionToolAction(
  body: AgentJournalItemBody | undefined
): body is StructuredAgentSessionToolAction {
  return body?.kind === 'tool-call' || body?.kind === 'diff'
}

/** A diff carries no lifecycle, so it reads as settled; otherwise a finished edit would stay the
 *  running call for the rest of its turn. */
export function isRunningStructuredAgentSessionToolAction(
  action: StructuredAgentSessionToolAction
): boolean {
  return action.kind === 'tool-call' && action.state === 'running'
}

/** `itemId`: the journal row's, the call's id when the provider gave none. A call and its result
 *  are one row, so the result names its call by it; without an id a result pairs with the oldest
 *  unanswered call, which in a run of several rows can be another row's. */
export function structuredAgentSessionToolCallBlock(
  action: StructuredAgentSessionToolAction,
  itemId: string
): NativeChatToolCallBlock {
  if (action.kind === 'diff') {
    return { type: 'tool-call', name: 'Diff', input: { path: action.path }, callId: itemId }
  }
  return {
    type: 'tool-call',
    name: action.name,
    input: action.input,
    state: action.state,
    ...(action.endedAs !== undefined ? { endedAs: action.endedAs } : {}),
    callId: action.callId ?? itemId,
    ...(action.mcpIdentity !== undefined ? { mcpIdentity: action.mcpIdentity } : {}),
    ...(action.exitCode !== undefined ? { exitCode: action.exitCode } : {}),
    ...(action.durationMs !== undefined ? { durationMs: action.durationMs } : {}),
    ...(action.webSearchResults !== undefined ? { webSearchResults: action.webSearchResults } : {})
  }
}

src/shared/structured-agent-session-unan.source:
import type { AgentJournalSubmission } from './agent-session-journal-types'
import { isQueuedAgentJournalSubmission } from './agent-session-queued-submission'

/** One send the provider has neither opened a turn for nor refused; the rule is explained on
 *  `hasUnansweredStructuredAgentSessionDispatch`, which asks it of every send. */
export function isUnansweredStructuredAgentSessionDispatch(
  submission: AgentJournalSubmission,
  currentFence?: number | null
): boolean {
  if (isQueuedAgentJournalSubmission(submission)) {
    // Accepted and still owed to whichever child the host starts next, whatever the fence.
    return true
  }
  return (
    (currentFence == null || submission.fence >= currentFence) &&
    (submission.dispatchState === 'pending' ||
      (submission.dispatchState === 'unknown' &&
        submission.recovered !== true &&
        // Older hosts publish the recovery reason but omit the optional marker.
        submission.reason !== 'host_restarted_before_acknowledgement'))
  )
}

/**
 * A send the host has journaled that the provider has neither opened a turn for nor refused.
 *
 * Codex declares `turn/started` within ~150ms, but Claude's running row can only be written once
 * the SDK echoes the user message back — a 3.4s median and 18s at p90 on real journals, and no
 * echo at all while it retries a rate-limited request. Waiting on that echo to call a session
 * working leaves the whole gap reading idle in the chat and in every session list, so the send
 * itself is the evidence.
 *
 * A live `unknown` still counts because an ambiguous adapter reply does not prove the provider
 * stopped. A recovered `unknown` does not — it outlived the host generation that sent it, so
 * there is nothing still running to report.
 */
export function hasUnansweredStructuredAgentSessionDispatch(
  submissions: readonly AgentJournalSubmission[],
  currentFence?: number | null
): boolean {
  return submissions.some((submission) =>
    isUnansweredStructuredAgentSessionDispatch(submission, currentFence)
  )
}

